static void capture_mft_geometry_snapshot_local(MftGeometrySnapshot *out)
{
    if (out == NULL) {
        return;
    }

    memset(out, 0, sizeof(*out));
    out->partition_start = g_partition_start;
    out->cluster_size = g_cluster_size;
    out->record_size = g_mft_record_size;
    out->expected_mft_base_offset = g_expected_mft_base_offset;
    out->expected_mft_mirror_offset = g_expected_mft_mirror_offset;
    out->ntfs_volume_serial = g_ntfs_volume_serial;
    out->has_ntfs_geometry = g_has_ntfs_geometry;
    out->direct_mft_source = g_direct_mft_source;
    out->source_is_definitely_non_ntfs = g_source_is_definitely_non_ntfs;
    snprintf(
        out->source_filesystem_hint,
        sizeof(out->source_filesystem_hint),
        "%s",
        g_source_filesystem_hint
    );
}

static void restore_mft_geometry_snapshot_local(const MftGeometrySnapshot *snapshot)
{
    if (snapshot == NULL) {
        return;
    }

    g_partition_start = snapshot->partition_start;
    g_cluster_size = snapshot->cluster_size;
    g_mft_record_size = snapshot->record_size;
    g_expected_mft_base_offset = snapshot->expected_mft_base_offset;
    g_expected_mft_mirror_offset = snapshot->expected_mft_mirror_offset;
    g_ntfs_volume_serial = snapshot->ntfs_volume_serial;
    g_has_ntfs_geometry = snapshot->has_ntfs_geometry;
    g_direct_mft_source = snapshot->direct_mft_source;
    g_source_is_definitely_non_ntfs = snapshot->source_is_definitely_non_ntfs;
    snprintf(
        g_source_filesystem_hint,
        sizeof(g_source_filesystem_hint),
        "%s",
        snapshot->source_filesystem_hint
    );
}

static int read_saved_source_path_from_scan_state_local(
    char *out_path,
    size_t out_path_size
)
{
    char scan_state_path[1024];
    FILE *file;
    char line[2048];

    if (out_path == NULL || out_path_size == 0U) {
        return 0;
    }
    out_path[0] = '\0';

    if (snprintf(
            scan_state_path,
            sizeof(scan_state_path),
            "%s/" APP_STATE_DIR_NAME "/scan_state.txt",
            g_mft_output_dir) >= (int)sizeof(scan_state_path)) {
        return 0;
    }

    file = fopen(scan_state_path, "r");
    if (file == NULL) {
        return 0;
    }

    while (fgets(line, sizeof(line), file) != NULL) {
        const char prefix[] = "source_path=";
        size_t prefix_len = sizeof(prefix) - 1U;

        if (strncmp(line, prefix, prefix_len) != 0) {
            continue;
        }

        line[strcspn(line, "\r\n")] = '\0';
        if (line[prefix_len] == '\0') {
            break;
        }

        {
            const char *saved_path = line + prefix_len;
            size_t copy_len = strlen(saved_path);

            if (copy_len >= out_path_size) {
                copy_len = out_path_size - 1U;
            }
            memcpy(out_path, saved_path, copy_len);
            out_path[copy_len] = '\0';
        }
        fclose(file);
        return 1;
    }

    fclose(file);
    return 0;
}

static void clear_mft_resume_offset_delta_local(void)
{
    g_mft_saved_partition_start_snapshot = 0LL;
    g_mft_resume_actual_partition_start = 0LL;
    g_mft_resume_offset_delta = 0LL;
    g_mft_resume_offset_delta_active = 0;
}

static int mft_entry_effective_abs_offset_local(
    const MftEntry *entry,
    long long *out_abs_offset
)
{
    long long effective;

    if (out_abs_offset != NULL) {
        *out_abs_offset = -1LL;
    }
    if (entry == NULL) {
        return 0;
    }

    effective = entry->abs_offset;
    if (g_mft_resume_offset_delta_active &&
        entry->has_data &&
        !entry->is_resident &&
        effective >= 0) {
        if ((g_mft_resume_offset_delta > 0 &&
             effective > LLONG_MAX - g_mft_resume_offset_delta) ||
            (g_mft_resume_offset_delta < 0 &&
             effective < LLONG_MIN - g_mft_resume_offset_delta)) {
            return 0;
        }
        effective += g_mft_resume_offset_delta;
    }

    if (out_abs_offset != NULL) {
        *out_abs_offset = effective;
    }
    return 1;
}

static long long mft_entry_effective_abs_offset_or_raw_local(const MftEntry *entry)
{
    long long effective = -1LL;

    if (mft_entry_effective_abs_offset_local(entry, &effective)) {
        return effective;
    }
    return entry != NULL ? entry->abs_offset : -1LL;
}

static int mft_snapshot_offset_from_effective_offset_local(
    long long effective_abs_offset,
    long long *out_snapshot_abs_offset
)
{
    long long snapshot_abs_offset = effective_abs_offset;

    if (out_snapshot_abs_offset != NULL) {
        *out_snapshot_abs_offset = -1LL;
    }
    if (effective_abs_offset < 0) {
        return 0;
    }

    if (g_mft_resume_offset_delta_active) {
        if ((g_mft_resume_offset_delta > 0 &&
             effective_abs_offset < LLONG_MIN + g_mft_resume_offset_delta) ||
            (g_mft_resume_offset_delta < 0 &&
             effective_abs_offset > LLONG_MAX + g_mft_resume_offset_delta)) {
            return 0;
        }
        snapshot_abs_offset = effective_abs_offset - g_mft_resume_offset_delta;
    }

    if (out_snapshot_abs_offset != NULL) {
        *out_snapshot_abs_offset = snapshot_abs_offset;
    }
    return 1;
}

