static double monotonic_seconds_local(void)
{
    struct timespec now;

    clock_gettime(CLOCK_MONOTONIC, &now);
    return (double)now.tv_sec + ((double)now.tv_nsec / 1000000000.0);
}

static void mft_name_match_preview_output_budget_start(double seconds)
{
    g_mft_name_match_preview_output_budget_exhausted = 0;
    if (seconds <= 0.0) {
        g_mft_name_match_preview_output_deadline_at = 0.0;
        return;
    }
    g_mft_name_match_preview_output_deadline_at =
        monotonic_seconds_local() + seconds;
}

static void mft_name_match_preview_output_budget_clear(void)
{
    g_mft_name_match_preview_output_deadline_at = 0.0;
    g_mft_name_match_preview_output_budget_exhausted = 0;
}

static int mft_name_match_preview_output_budget_should_yield(void)
{
    if (g_mft_name_match_preview_output_deadline_at <= 0.0) {
        return 0;
    }
    if (monotonic_seconds_local() <=
        g_mft_name_match_preview_output_deadline_at) {
        return 0;
    }
    g_mft_name_match_preview_output_budget_exhausted = 1;
    return 1;
}

static int mft_name_match_preview_output_budget_was_exhausted(void)
{
    return g_mft_name_match_preview_output_budget_exhausted;
}

