static int usn_name_index_put(
    long long family_base_offset,
    int record_number,
    uint16_t record_seq,
    uint64_t parent_record,
    uint16_t parent_seq,
    uint64_t created_filetime,
    const char *name
)
{
    return name_catalog_index_put(
        family_base_offset,
        record_number,
        record_seq,
        parent_record,
        parent_seq,
        created_filetime,
        0ULL,
        0ULL,
        name,
        MFT_NAME_NAMESPACE_UNKNOWN,
        MFT_NAME_CATALOG_SOURCE_USN
    );
}

static int mft_apply_i30_name_to_entry(MftEntry *entry)
{
    const MftI30NameEntry *fallback = NULL;
    int changed = 0;
    int fallback_has_i30 = 0;

    if (entry == NULL) {
        return 0;
    }
    if (!i30_name_index_lookup(entry->family_base_offset, entry->record_number, &fallback) ||
        fallback == NULL) {
        return 0;
    }
    if (entry->record_seq != 0U &&
        fallback->record_seq != 0U &&
        entry->record_seq != fallback->record_seq) {
        return 0;
    }
    if (entry->record_seq == 0U && fallback->record_seq != 0U) {
        entry->record_seq = fallback->record_seq;
        changed = 1;
    }

    fallback_has_i30 =
        (fallback->source_flags & MFT_NAME_CATALOG_SOURCE_I30) != 0U ||
        fallback->source_flags == 0U;
    if (!entry->has_name ||
        (fallback_has_i30 &&
         mft_compare_name_preference(
             fallback->name,
             fallback->name_namespace,
             entry->name,
             entry->name_namespace) > 0)) {
        snprintf(entry->name, sizeof(entry->name), "%s", fallback->name);
        entry->name_namespace = fallback->name_namespace;
        entry->has_name = 1;
        changed = 1;
    }

    if (entry->parent_record == 0U ||
        entry->parent_record == UINT64_MAX ||
        entry->parent_record == (uint64_t)entry->record_number) {
        entry->parent_record = fallback->parent_record;
        entry->parent_seq = fallback->parent_seq;
        changed = 1;
    }

    if (entry->created_unix <= 0 && fallback->created_filetime != 0U) {
        entry->created_filetime = fallback->created_filetime;
        entry->created_unix =
            (time_t)filetime_to_unix_seconds(fallback->created_filetime);
        format_filetime(
            fallback->created_filetime,
            entry->created,
            sizeof(entry->created)
        );
        changed = 1;
    }

    if (entry->data_size == 0U && fallback->data_size != 0U) {
        entry->data_size = fallback->data_size;
        if (entry->valid_data_size == 0U) {
            entry->valid_data_size = fallback->data_size;
        }
        changed = 1;
    }

    if (entry->allocated_size == 0U && fallback->allocated_size != 0U) {
        entry->allocated_size = fallback->allocated_size;
        changed = 1;
    }

    return changed;
}

void mft_set_recovery_categories(
    int recover_img,
    int recover_vid,
    int recover_doc
)
{
    g_recover_img_enabled = recover_img ? 1 : 0;
    g_recover_vid_enabled = recover_vid ? 1 : 0;
    g_recover_doc_enabled = recover_doc ? 1 : 0;
    g_recovery_target_cache_entry_count = (size_t)-1;
    g_recovery_target_cache_recovered_count = (size_t)-1;
}

void mft_set_requested_formats_csv(const char *formats_csv)
{
    char work[1024];
    char *token;

    g_requested_format_extension_count = 0U;
    memset(
        g_requested_format_extensions,
        0,
        sizeof(g_requested_format_extensions)
    );

    if (formats_csv == NULL || formats_csv[0] == '\0') {
        g_recovery_target_cache_entry_count = (size_t)-1;
        g_recovery_target_cache_recovered_count = (size_t)-1;
        return;
    }
    if (strlen(formats_csv) >= sizeof(work)) {
        return;
    }

    snprintf(work, sizeof(work), "%s", formats_csv);
    token = strtok(work, ",;");
    while (token != NULL &&
           g_requested_format_extension_count < MFT_REQUESTED_FORMAT_MAX) {
        size_t length = 0U;
        size_t i;
        size_t index;
        int seen = 0;

        while (*token != '\0' && isspace((unsigned char)*token)) {
            token++;
        }
        while (token[length] != '\0' &&
               !isspace((unsigned char)token[length])) {
            length++;
        }
        while (length > 0U && token[0] == '.') {
            token++;
            length--;
        }
        if (length == 0U) {
            token = strtok(NULL, ",;");
            continue;
        }
        if (length >= MFT_REQUESTED_FORMAT_TEXT_MAX) {
            length = MFT_REQUESTED_FORMAT_TEXT_MAX - 1U;
        }

        for (i = 0U; i < length; i++) {
            g_requested_format_extensions[g_requested_format_extension_count][i] =
                (char)tolower((unsigned char)token[i]);
        }
        g_requested_format_extensions[g_requested_format_extension_count][length] =
            '\0';

        for (index = 0U; index < g_requested_format_extension_count; index++) {
            if (strcmp(
                    g_requested_format_extensions[index],
                    g_requested_format_extensions[
                        g_requested_format_extension_count]) == 0) {
                seen = 1;
                break;
            }
        }
        if (!seen) {
            g_requested_format_extension_count++;
        } else {
            memset(
                g_requested_format_extensions[g_requested_format_extension_count],
                0,
                MFT_REQUESTED_FORMAT_TEXT_MAX
            );
        }
        token = strtok(NULL, ",;");
    }

    g_recovery_target_cache_entry_count = (size_t)-1;
    g_recovery_target_cache_recovered_count = (size_t)-1;
}

void mft_set_contextual_output_mode(MftContextualOutputMode mode)
{
    g_contextual_output_mode = mode;
}

void mft_set_reset_existing_store(int enabled)
{
    g_reset_existing_store = enabled ? 1 : 0;
    g_mft_log_prepare_seen = 0;
    g_mft_relevant_log_prepare_seen = 0;
}

void mft_set_deleted_filter(int enabled, int deleted_value)
{
    g_deleted_filter_enabled = enabled ? 1 : 0;
    g_deleted_filter_value = deleted_value;
    g_recovery_target_cache_entry_count = (size_t)-1;
    g_recovery_target_cache_recovered_count = (size_t)-1;
}

void mft_set_deleted_filter_recycle_policy(int include_with_live_filter)
{
    g_deleted_filter_include_recycle_with_live = include_with_live_filter ? 1 : 0;
    g_recovery_target_cache_entry_count = (size_t)-1;
    g_recovery_target_cache_recovered_count = (size_t)-1;
}

void mft_set_date_filter(int enabled, int start_yyyymmdd, int end_yyyymmdd)
{
    g_date_filter_enabled = enabled ? 1 : 0;
    g_date_filter_start_yyyymmdd = start_yyyymmdd;
    g_date_filter_end_yyyymmdd = end_yyyymmdd;
    g_recovery_target_cache_entry_count = (size_t)-1;
    g_recovery_target_cache_recovered_count = (size_t)-1;
}

static int filetime_to_yyyymmdd_local(uint64_t filetime)
{
    int64_t unix_seconds;
    time_t value;
    struct tm tm_value;

    if (filetime == 0) {
        return 0;
    }

    unix_seconds = (int64_t)(filetime / 10000000ULL) - 11644473600LL;
    if (unix_seconds <= 0) {
        return 0;
    }

    value = (time_t)unix_seconds;
    if (gmtime_r(&value, &tm_value) == NULL) {
        return 0;
    }

    return (tm_value.tm_year + 1900) * 10000 +
           (tm_value.tm_mon + 1) * 100 +
           tm_value.tm_mday;
}

static int name_is_recycle_root(const char *name)
{
    return name != NULL &&
           (strcasecmp(name, "$Recycle.Bin") == 0 ||
            strcasecmp(name, "Recycler") == 0 ||
            strcasecmp(name, "Recycled") == 0);
}

static int entry_is_deleted_like(const MftEntry *entry)
{
    const MftEntry *current = entry;
    size_t depth = 0;

    if (entry == NULL) {
        return 0;
    }
    if ((entry->flags & 0x0001U) == 0U) {
        return 1;
    }

    while (current != NULL && depth++ < 256U) {
        if (name_is_recycle_root(current->name)) {
            return 1;
        }
        if (current->record_number == 5 ||
            current->parent_record == (uint64_t)current->record_number ||
            current->parent_record > (uint64_t)INT32_MAX) {
            break;
        }
        current = find_entry_by_family_and_record(
            current->family_base_offset,
            (int)current->parent_record);
    }

    return 0;
}

static int build_deleted_contextual_path_from_entry(
    const MftEntry *entry,
    char *out,
    size_t out_size
)
{
    int created_date;

    if (out == NULL || out_size == 0) {
        return 0;
    }
    out[0] = '\0';
    if (entry == NULL || !entry->has_name || entry->name[0] == '\0') {
        return 0;
    }

    created_date = filetime_to_yyyymmdd_local(entry->created_filetime);
    if (created_date != 0) {
        return snprintf(
                   out,
                   out_size,
                   "/" APP_DELETED_DIR_NAME "/%08d/%s",
                   created_date,
                   entry->name) < (int)out_size;
    }
    return snprintf(
               out,
               out_size,
               "/" APP_DELETED_DIR_NAME "/%s",
               entry->name) < (int)out_size;
}

static int entry_has_confident_deleted_output_state(const MftEntry *entry)
{
    return entry != NULL && entry_is_deleted_like(entry);
}

static int prefix_deleted_recovered_relative_path(
    char *out,
    size_t out_size,
    const char *relative_path
)
{
    const char *trimmed = relative_path;

    if (out == NULL || out_size == 0U) {
        return 0;
    }
    out[0] = '\0';
    if (trimmed == NULL) {
        return 0;
    }
    while (*trimmed == '/') {
        trimmed++;
    }
    if (trimmed[0] == '\0') {
        return snprintf(out, out_size, APP_DELETED_DIR_NAME) < (int)out_size;
    }
    if (strncmp(trimmed, APP_DELETED_DIR_NAME "/", strlen(APP_DELETED_DIR_NAME) + 1U) == 0 ||
        strcmp(trimmed, APP_DELETED_DIR_NAME) == 0) {
        return snprintf(out, out_size, "%s", trimmed) < (int)out_size;
    }
    return snprintf(
               out,
               out_size,
               APP_DELETED_DIR_NAME "/%s",
               trimmed) < (int)out_size;
}

static int entry_matches_runtime_filters(const MftEntry *entry)
{
    if (entry == NULL) {
        return 0;
    }

    if (g_deleted_filter_enabled) {
        int is_deleted = entry_is_deleted_like(entry);

        if (g_deleted_filter_value != 2 &&
            is_deleted != g_deleted_filter_value &&
            !(g_deleted_filter_value == 0 &&
              g_deleted_filter_include_recycle_with_live &&
              entry_is_deleted_like(entry))) {
            return 0;
        }
    }

    if (g_date_filter_enabled) {
        int created_date = filetime_to_yyyymmdd_local(entry->created_filetime);

        if (created_date == 0 ||
            created_date < g_date_filter_start_yyyymmdd ||
            created_date > g_date_filter_end_yyyymmdd) {
            return 0;
        }
    }

    return 1;
}

/* ========================= BASIC READ HELPERS ========================= */

static uint16_t read_u16_le(const unsigned char *p)
{
    return (uint16_t)(p[0] | (p[1] << 8));
}

static uint32_t read_u32_le(const unsigned char *p)
{
    return ((uint32_t)p[0]) |
           ((uint32_t)p[1] << 8) |
           ((uint32_t)p[2] << 16) |
           ((uint32_t)p[3] << 24);
}

static uint64_t read_u64_le(const unsigned char *p)
{
    return ((uint64_t)p[0]) |
           ((uint64_t)p[1] << 8) |
           ((uint64_t)p[2] << 16) |
           ((uint64_t)p[3] << 24) |
           ((uint64_t)p[4] << 32) |
           ((uint64_t)p[5] << 40) |
           ((uint64_t)p[6] << 48) |
           ((uint64_t)p[7] << 56);
}

static int write_bytes(FILE *fp, const void *data, size_t length)
{
    return fp != NULL &&
           data != NULL &&
           fwrite(data, 1, length, fp) == length;
}

static int write_u16_le(FILE *fp, uint16_t value)
{
    unsigned char out[2];

    out[0] = (unsigned char)(value & 0xFFU);
    out[1] = (unsigned char)((value >> 8) & 0xFFU);
    return write_bytes(fp, out, sizeof(out));
}

static int write_u32_le(FILE *fp, uint32_t value)
{
    unsigned char out[4];

    out[0] = (unsigned char)(value & 0xFFU);
    out[1] = (unsigned char)((value >> 8) & 0xFFU);
    out[2] = (unsigned char)((value >> 16) & 0xFFU);
    out[3] = (unsigned char)((value >> 24) & 0xFFU);
    return write_bytes(fp, out, sizeof(out));
}

static int write_u64_le(FILE *fp, uint64_t value)
{
    unsigned char out[8];
    size_t i;

    for (i = 0; i < sizeof(out); i++) {
        out[i] = (unsigned char)((value >> (i * 8U)) & 0xFFU);
    }

    return write_bytes(fp, out, sizeof(out));
}

static int write_i64_le(FILE *fp, long long value)
{
    return write_u64_le(fp, (uint64_t)value);
}

static uint64_t fnv1a64_bytes(uint64_t hash, const void *data, size_t length)
{
    const unsigned char *bytes = (const unsigned char *)data;
    size_t i;

    if (data == NULL) {
        return hash;
    }

    for (i = 0; i < length; i++) {
        hash ^= (uint64_t)bytes[i];
        hash *= 1099511628211ULL;
    }

    return hash;
}

static int8_t read_i8(const unsigned char *p)
{
    return (int8_t)p[0];
}

static int has_ntfs_oem_id(const unsigned char *boot_sector, size_t length)
{
    if (boot_sector == NULL || length < 11) {
        return 0;
    }

    return memcmp(boot_sector + 3, "NTFS    ", 8) == 0;
}

static int has_valid_sector_signature(
    const unsigned char *sector,
    size_t length
)
{
    if (sector == NULL || length < 512) {
        return 0;
    }

    return sector[510] == 0x55 && sector[511] == 0xAA;
}

static int read_sector_at(
    FILE *input_file,
    long long absolute_offset,
    unsigned char *sector,
    size_t sector_size
)
{
    if (input_file == NULL || sector == NULL || sector_size == 0) {
        return 0;
    }

    if (fseek(input_file, (long)absolute_offset, SEEK_SET) != 0) {
        return 0;
    }

    return fread(sector, 1, sector_size, input_file) == sector_size;
}

static int get_seekable_source_size_local(FILE *input_file, uint64_t *out_size)
{
    struct stat st;
    off_t current;
    off_t end;
#ifdef __APPLE__
    uint64_t block_count = 0ULL;
    uint32_t block_size = 0U;
#endif
#ifdef __linux__
    unsigned long long block_size = 0ULL;
#endif

    if (out_size != NULL) {
        *out_size = 0ULL;
    }
    if (input_file == NULL || out_size == NULL) {
        return 0;
    }

    if (fstat(fileno(input_file), &st) == 0 &&
        S_ISREG(st.st_mode) &&
        st.st_size > 0) {
        *out_size = (uint64_t)st.st_size;
        return 1;
    }

#ifdef __APPLE__
    if ((S_ISCHR(st.st_mode) || S_ISBLK(st.st_mode)) &&
        ioctl(fileno(input_file), DKIOCGETBLOCKCOUNT, &block_count) == 0 &&
        ioctl(fileno(input_file), DKIOCGETBLOCKSIZE, &block_size) == 0 &&
        block_size > 0U) {
        *out_size = block_count * (uint64_t)block_size;
        return 1;
    }
#endif

#ifdef __linux__
    if (S_ISBLK(st.st_mode) &&
        ioctl(fileno(input_file), BLKGETSIZE64, &block_size) == 0 &&
        block_size > 0ULL) {
        *out_size = (uint64_t)block_size;
        return 1;
    }
#endif

    current = ftello(input_file);
    if (current < 0) {
        return 0;
    }
    if (fseeko(input_file, 0, SEEK_END) != 0) {
        (void)fseeko(input_file, current, SEEK_SET);
        return 0;
    }
    end = ftello(input_file);
    (void)fseeko(input_file, current, SEEK_SET);
    if (end <= 0) {
        return 0;
    }

    *out_size = (uint64_t)end;
    return 1;
}

static int ntfs_power_of_two_u64(uint64_t value)
{
    return value != 0ULL && (value & (value - 1ULL)) == 0ULL;
}

static int find_mbr_ntfs_partition_start(
    const unsigned char *mbr_sector,
    long long *partition_start
)
{
    int i;
    long long best_start = -1;
    uint32_t best_sector_count = 0;

    if (mbr_sector == NULL || partition_start == NULL) {
        return 0;
    }

    if (!has_valid_sector_signature(mbr_sector, 512)) {
        return 0;
    }

    for (i = 0; i < 4; i++) {
        const unsigned char *entry = mbr_sector + 446 + (i * 16);
        uint8_t status = entry[0];
        uint8_t partition_type = entry[4];
        uint32_t start_lba = read_u32_le(entry + 8);
        uint32_t sector_count = read_u32_le(entry + 12);
        long long start_offset;

        if (partition_type != 0x07 || start_lba == 0 || sector_count == 0) {
            continue;
        }

        start_offset = (long long)start_lba * 512LL;

        /*
         * Modern Windows disks commonly have a small active "System Reserved"
         * NTFS partition before the real user data volume. Picking the active
         * entry here makes the naming engine build a beautiful tree for the
         * wrong volume. Prefer the largest NTFS partition; GPT already follows
         * the same spirit.
         */
        (void)status;
        if (best_start < 0 || sector_count > best_sector_count) {
            best_start = start_offset;
            best_sector_count = sector_count;
        }
    }

    if (best_start < 0) {
        return 0;
    }

    *partition_start = best_start;
    return 1;
}

static int bytes_are_all_zero(const unsigned char *data, size_t length)
{
    size_t i;

    if (data == NULL) {
        return 1;
    }

    for (i = 0; i < length; i++) {
        if (data[i] != 0x00) {
            return 0;
        }
    }

    return 1;
}

static int guid_is_microsoft_basic_data(const unsigned char *guid)
{
    static const unsigned char basic_data_guid[16] = {
        0xA2, 0xA0, 0xD0, 0xEB,
        0xE5, 0xB9,
        0x33, 0x44,
        0x87, 0xC0,
        0x68, 0xB6, 0xB7, 0x26, 0x99, 0xC7
    };

    if (guid == NULL) {
        return 0;
    }

    return memcmp(guid, basic_data_guid, sizeof(basic_data_guid)) == 0;
}

static int find_gpt_ntfs_partition_start(
    FILE *input_file,
    long long *partition_start
)
{
    unsigned char gpt_header[512];
    unsigned char boot_sector[512];
    unsigned char *partition_entry = NULL;
    uint64_t entries_lba;
    uint32_t entry_count;
    uint32_t entry_size;
    uint64_t best_first_lba = 0;
    uint64_t best_sector_count = 0;
    int best_is_basic_data = 0;
    uint32_t i;
    int found = 0;

    if (input_file == NULL || partition_start == NULL) {
        return 0;
    }

    if (!read_sector_at(input_file, 512LL, gpt_header, sizeof(gpt_header))) {
        return 0;
    }

    if (memcmp(gpt_header, "EFI PART", 8) != 0) {
        return 0;
    }

    entries_lba = read_u64_le(gpt_header + 72);
    entry_count = read_u32_le(gpt_header + 80);
    entry_size = read_u32_le(gpt_header + 84);

    if (entries_lba == 0 || entry_count == 0) {
        return 0;
    }

    if (entry_size < 128 || entry_size > 4096) {
        return 0;
    }

    if (entry_count > 4096U) {
        entry_count = 4096U;
    }

    partition_entry = (unsigned char *)malloc(entry_size);
    if (partition_entry == NULL) {
        return 0;
    }

    for (i = 0; i < entry_count; i++) {
        long long entry_offset;
        uint64_t first_lba;
        uint64_t last_lba;
        uint64_t sector_count;
        int is_basic_data;

        entry_offset =
            (long long)(entries_lba * 512ULL) + (long long)((uint64_t)i * entry_size);

        if (!read_sector_at(input_file, entry_offset, partition_entry, entry_size)) {
            continue;
        }

        if (bytes_are_all_zero(partition_entry, 16)) {
            continue;
        }

        first_lba = read_u64_le(partition_entry + 32);
        last_lba = read_u64_le(partition_entry + 40);

        if (first_lba == 0 || last_lba < first_lba) {
            continue;
        }

        if (!read_sector_at(
                input_file,
                (long long)(first_lba * 512ULL),
                boot_sector,
                sizeof(boot_sector))) {
            continue;
        }

        if (!has_ntfs_oem_id(boot_sector, sizeof(boot_sector))) {
            continue;
        }

        sector_count = last_lba - first_lba + 1U;
        is_basic_data = guid_is_microsoft_basic_data(partition_entry);

        if (!found ||
            (is_basic_data && !best_is_basic_data) ||
            (is_basic_data == best_is_basic_data &&
             sector_count > best_sector_count)) {
            best_first_lba = first_lba;
            best_sector_count = sector_count;
            best_is_basic_data = is_basic_data;
            found = 1;
        }
    }

    free(partition_entry);

    if (!found) {
        return 0;
    }

    *partition_start = (long long)(best_first_lba * 512ULL);
    return 1;
}

#ifdef __APPLE__
static int ascii_digit_local(char ch)
{
    return ch >= '0' && ch <= '9';
}

static int derive_macos_whole_disk_name_local(
    const char *path,
    char *out,
    size_t out_size
)
{
    const char *suffix = NULL;
    size_t digits = 0;

    if (path == NULL || out == NULL || out_size == 0) {
        return 0;
    }

    if (strncmp(path, "/dev/rdisk", 10) == 0) {
        suffix = path + 10;
    } else if (strncmp(path, "/dev/disk", 9) == 0) {
        suffix = path + 9;
    } else {
        return 0;
    }

    while (ascii_digit_local(suffix[digits])) {
        digits++;
    }
    if (digits == 0 || suffix[digits] != '\0') {
        return 0;
    }

    return snprintf(out, out_size, "disk%.*s", (int)digits, suffix) <
           (int)out_size;
}

static int parse_diskutil_bytes_line_local(
    const char *line,
    const char *prefix,
    uint64_t *out_value
)
{
    unsigned long long parsed = 0ULL;
    size_t prefix_length;

    if (line == NULL || prefix == NULL || out_value == NULL) {
        return 0;
    }

    prefix_length = strlen(prefix);
    if (strncmp(line, prefix, prefix_length) != 0) {
        return 0;
    }
    if (sscanf(line + prefix_length, "%llu Bytes", &parsed) != 1) {
        return 0;
    }

    *out_value = (uint64_t)parsed;
    return 1;
}

static int parse_diskutil_size_parenthetical_local(
    const char *line,
    uint64_t *out_value
)
{
    const char *paren;
    unsigned long long parsed = 0ULL;

    if (line == NULL || out_value == NULL) {
        return 0;
    }

    paren = strchr(line, '(');
    if (paren == NULL) {
        return 0;
    }
    if (sscanf(paren, "(%llu Bytes)", &parsed) != 1) {
        return 0;
    }

    *out_value = (uint64_t)parsed;
    return 1;
}

static void copy_trimmed_diskutil_value_local(
    const char *line,
    const char *prefix,
    char *out,
    size_t out_size
)
{
    const char *value;
    size_t length;

    if (line == NULL || prefix == NULL || out == NULL || out_size == 0U) {
        return;
    }

    if (strncmp(line, prefix, strlen(prefix)) != 0) {
        return;
    }

    value = line + strlen(prefix);
    while (*value == ' ' || *value == '\t') {
        value++;
    }

    length = strcspn(value, "\r\n");
    while (length > 0U &&
           (value[length - 1U] == ' ' || value[length - 1U] == '\t')) {
        length--;
    }

    if (length >= out_size) {
        length = out_size - 1U;
    }

    memcpy(out, value, length);
    out[length] = '\0';
}

static int macos_hint_is_definitely_non_ntfs_local(const char *personality)
{
    if (personality == NULL || personality[0] == '\0') {
        return 0;
    }

    return strcasecmp(personality, "ntfs") != 0 &&
           strcasecmp(personality, "windows_ntfs") != 0;
}

static int detect_macos_source_filesystem_hint_local(
    const char *path,
    char *personality_out,
    size_t personality_out_size
)
{
    char command[512];
    char line[512];
    FILE *pipe;

    if (path == NULL || personality_out == NULL || personality_out_size == 0U) {
        return 0;
    }

    personality_out[0] = '\0';
    if (snprintf(
            command,
            sizeof(command),
            "diskutil info '%s' 2>/dev/null",
            path) >= (int)sizeof(command)) {
        return 0;
    }

    pipe = popen(command, "r");
    if (pipe == NULL) {
        return 0;
    }

    while (fgets(line, sizeof(line), pipe) != NULL) {
        copy_trimmed_diskutil_value_local(
            line,
            "   File System Personality:",
            personality_out,
            personality_out_size
        );
    }

    (void)pclose(pipe);
    return personality_out[0] != '\0';
}

static void maybe_set_macos_non_ntfs_hint_local(const char *input_path)
{
    if (g_source_filesystem_hint[0] != '\0') {
        return;
    }

    if (detect_macos_source_filesystem_hint_local(
            input_path,
            g_source_filesystem_hint,
            sizeof(g_source_filesystem_hint))) {
        return;
    }
}

static void commit_macos_non_ntfs_hint_local(void)
{
    if (g_source_filesystem_hint[0] == '\0') {
        return;
    }

    g_source_is_definitely_non_ntfs =
        macos_hint_is_definitely_non_ntfs_local(g_source_filesystem_hint);
}

static int read_macos_slice_boot_sector_local(
    FILE *input_file,
    const char *slice_id,
    uint64_t partition_offset,
    unsigned char *boot_sector
)
{
    char raw_slice_path[96];
    char slice_path[96];
    FILE *slice_file;

    if (boot_sector == NULL || slice_id == NULL) {
        return 0;
    }

    if (input_file != NULL &&
        partition_offset <= (uint64_t)LLONG_MAX &&
        read_sector_at(
            input_file,
            (long long)partition_offset,
            boot_sector,
            512) &&
        has_ntfs_oem_id(boot_sector, 512)) {
        return 1;
    }

    if (snprintf(raw_slice_path, sizeof(raw_slice_path), "/dev/r%s", slice_id) >=
            (int)sizeof(raw_slice_path) ||
        snprintf(slice_path, sizeof(slice_path), "/dev/%s", slice_id) >=
            (int)sizeof(slice_path)) {
        return 0;
    }

    slice_file = fopen(raw_slice_path, "rb");
    if (slice_file == NULL) {
        slice_file = fopen(slice_path, "rb");
    }
    if (slice_file == NULL) {
        return 0;
    }

    if (fread(boot_sector, 1, 512, slice_file) != 512) {
        fclose(slice_file);
        return 0;
    }

    fclose(slice_file);
    return has_ntfs_oem_id(boot_sector, 512);
}

static int configure_ntfs_geometry_from_macos_diskutil(
    const char *input_path,
    FILE *input_file
)
{
    char whole_disk[64];
    unsigned char best_boot_sector[512];
    uint64_t best_partition_offset = 0;
    uint64_t best_volume_size = 0;
    int best_is_basic_data = 0;
    int found = 0;
    int slice_number;
    int consecutive_missing = 0;

    if (!derive_macos_whole_disk_name_local(
            input_path,
            whole_disk,
            sizeof(whole_disk))) {
        return 0;
    }

    memset(best_boot_sector, 0, sizeof(best_boot_sector));

    for (slice_number = 1; slice_number <= 32; slice_number++) {
        char slice_id[64];
        char info_command[128];
        char info_line[512];
        FILE *info_pipe;
        unsigned char boot_sector[512];
        uint64_t partition_offset = 0;
        uint64_t volume_size = 0;
        int have_offset = 0;
        int have_size = 0;
        int is_ntfs = 0;
        int is_basic_data = 0;
        int saw_output = 0;

        if (snprintf(slice_id, sizeof(slice_id), "%ss%d", whole_disk, slice_number) >=
                (int)sizeof(slice_id) ||
            snprintf(
                info_command,
                sizeof(info_command),
                "diskutil info /dev/%s 2>/dev/null",
                slice_id) >= (int)sizeof(info_command)) {
            continue;
        }

        info_pipe = popen(info_command, "r");
        if (info_pipe == NULL) {
            continue;
        }

        while (fgets(info_line, sizeof(info_line), info_pipe) != NULL) {
            saw_output = 1;
            if (strncmp(info_line, "   File System Personality:", 27) == 0 &&
                strstr(info_line, "NTFS") != NULL) {
                is_ntfs = 1;
            } else if (strncmp(info_line, "   Partition Type:", 18) == 0 &&
                       strstr(info_line, "Microsoft Basic Data") != NULL) {
                is_basic_data = 1;
            } else if (parse_diskutil_bytes_line_local(
                           info_line,
                           "   Partition Offset: ",
                           &partition_offset)) {
                have_offset = 1;
            } else if (strncmp(
                           info_line,
                           "   Disk Size:",
                           strlen("   Disk Size:")) == 0 &&
                       parse_diskutil_size_parenthetical_local(
                           info_line,
                           &volume_size)) {
                have_size = 1;
            }
        }
        (void)pclose(info_pipe);

        if (!saw_output) {
            consecutive_missing++;
            if (consecutive_missing >= 4 && slice_number > 4) {
                break;
            }
            continue;
        }
        consecutive_missing = 0;

        if ((!is_ntfs && !is_basic_data) || !have_offset || !have_size ||
            partition_offset > (uint64_t)LLONG_MAX ||
            !read_macos_slice_boot_sector_local(
                input_file,
                slice_id,
                partition_offset,
                boot_sector)) {
            continue;
        }

        if (!found ||
            (is_basic_data && !best_is_basic_data) ||
            (is_basic_data == best_is_basic_data &&
             volume_size > best_volume_size)) {
            memcpy(best_boot_sector, boot_sector, sizeof(best_boot_sector));
            best_partition_offset = partition_offset;
            best_volume_size = volume_size;
            best_is_basic_data = is_basic_data;
            found = 1;
        }
    }

    if (!found) {
        return 0;
    }

    return configure_ntfs_geometry_from_boot_sector(
        best_boot_sector,
        (long long)best_partition_offset);
}
#endif

static void mark_source_as_confirmed_ntfs_local(void)
{
    g_source_is_definitely_non_ntfs = 0;
    snprintf(
        g_source_filesystem_hint,
        sizeof(g_source_filesystem_hint),
        "%s",
        "NTFS"
    );
}

static int configure_ntfs_geometry_from_boot_sector(
    const unsigned char *boot_sector,
    long long partition_start
)
{
    uint16_t bytes_per_sector;
    uint8_t sectors_per_cluster;
    int record_size_raw;
    uint64_t mft_lcn;
    uint64_t mft_mirror_lcn;

    if (!has_ntfs_oem_id(boot_sector, 512)) {
        return 0;
    }

    bytes_per_sector = read_u16_le(boot_sector + 11);
    sectors_per_cluster = boot_sector[13];
    record_size_raw = read_i8(boot_sector + 64);
    mft_lcn = read_u64_le(boot_sector + 48);
    mft_mirror_lcn = read_u64_le(boot_sector + 56);

    if (bytes_per_sector == 0 || sectors_per_cluster == 0) {
        return 0;
    }

    g_partition_start = partition_start;
    g_cluster_size = (uint32_t)bytes_per_sector * (uint32_t)sectors_per_cluster;
    g_ntfs_volume_serial = read_u64_le(boot_sector + 72);
    if (g_cluster_size == 0) {
        g_cluster_size = 4096;
    }

    if (record_size_raw < 0) {
        g_mft_record_size = (uint32_t)1U << (uint8_t)(-record_size_raw);
    } else if (record_size_raw > 0) {
        g_mft_record_size = (uint32_t)record_size_raw * g_cluster_size;
    }

    if (g_mft_record_size == 0) {
        g_mft_record_size = 1024;
    }

    g_expected_mft_base_offset =
        g_partition_start + (long long)(mft_lcn * (uint64_t)g_cluster_size);
    g_expected_mft_mirror_offset =
        g_partition_start + (long long)(mft_mirror_lcn * (uint64_t)g_cluster_size);
    g_mft_base_offset = -1;
    g_has_ntfs_geometry = 1;

    return 1;
}

static void log_detected_mft_mirror(void)
{
    if (g_expected_mft_mirror_offset < 0) {
        return;
    }

    //log_info("Detected NTFS $MFTMirr at offset %lld", g_expected_mft_mirror_offset);
}

typedef struct {
    uint16_t bytes_per_sector;
    uint8_t sectors_per_cluster;
    int record_size_raw;
    uint64_t total_sectors;
    uint64_t volume_bytes;
    uint64_t cluster_size;
    uint64_t cluster_count;
    uint64_t mft_lcn;
    uint64_t mirror_lcn;
} MftNtfsBootFields;

static int ntfs_boot_sector_fields_plausible(
    const unsigned char *boot_sector,
    MftNtfsBootFields *out_fields
)
{
    MftNtfsBootFields fields;

    if (out_fields != NULL) {
        memset(out_fields, 0, sizeof(*out_fields));
    }
    if (boot_sector == NULL ||
        !has_ntfs_oem_id(boot_sector, 512) ||
        !has_valid_sector_signature(boot_sector, 512)) {
        return 0;
    }

    memset(&fields, 0, sizeof(fields));
    fields.bytes_per_sector = read_u16_le(boot_sector + 11);
    fields.sectors_per_cluster = boot_sector[13];
    fields.record_size_raw = read_i8(boot_sector + 64);
    fields.total_sectors = read_u64_le(boot_sector + 40);
    fields.mft_lcn = read_u64_le(boot_sector + 48);
    fields.mirror_lcn = read_u64_le(boot_sector + 56);

    if ((fields.bytes_per_sector != 512U &&
         fields.bytes_per_sector != 1024U &&
         fields.bytes_per_sector != 2048U &&
         fields.bytes_per_sector != 4096U) ||
        fields.sectors_per_cluster == 0U ||
        !ntfs_power_of_two_u64(fields.sectors_per_cluster) ||
        fields.total_sectors < 1024ULL) {
        return 0;
    }

    fields.cluster_size =
        (uint64_t)fields.bytes_per_sector *
        (uint64_t)fields.sectors_per_cluster;
    if (fields.cluster_size < 512ULL ||
        fields.cluster_size > 2ULL * 1024ULL * 1024ULL ||
        fields.total_sectors > UINT64_MAX / (uint64_t)fields.bytes_per_sector) {
        return 0;
    }

    fields.volume_bytes =
        fields.total_sectors * (uint64_t)fields.bytes_per_sector;
    fields.cluster_count =
        fields.total_sectors / (uint64_t)fields.sectors_per_cluster;
    if (fields.cluster_count == 0ULL ||
        fields.mft_lcn >= fields.cluster_count ||
        fields.mirror_lcn >= fields.cluster_count) {
        return 0;
    }

    if (fields.record_size_raw == 0 ||
        fields.record_size_raw < -31 ||
        fields.record_size_raw > 127) {
        return 0;
    }

    if (out_fields != NULL) {
        *out_fields = fields;
    }
    return 1;
}

typedef struct {
    int found;
    unsigned int score;
    uint64_t boot_offset;
    uint64_t partition_start;
    uint64_t primary_mft_offset;
    uint64_t mirror_offset;
    int as_backup;
    int primary_signature;
    int mirror_signature;
    char label[64];
    unsigned char boot_sector[512];
} MftNtfsBootCandidate;

typedef struct {
    MftNtfsBootCandidate best;
    size_t plausible_count;
    size_t signature_count;
    size_t read_failures;
} MftNtfsBootCandidateSearch;

static const char *mft_record_signature_label(int signature)
{
    switch (signature) {
        case 2:
            return "FILE";
        case 1:
            return "BAAD";
        default:
            return "none";
    }
}

static int mft_record_signature_at(
    FILE *input_file,
    uint64_t source_size,
    uint64_t absolute_offset
)
{
    unsigned char signature[4];

    if (input_file == NULL ||
        absolute_offset > (uint64_t)LLONG_MAX ||
        (source_size > 0ULL &&
         (absolute_offset > source_size ||
          sizeof(signature) > source_size - absolute_offset)) ||
        !read_sector_at(
            input_file,
            (long long)absolute_offset,
            signature,
            sizeof(signature))) {
        return 0;
    }

    if (memcmp(signature, "FILE", 4) == 0) {
        return 2;
    }
    if (memcmp(signature, "BAAD", 4) == 0) {
        return 1;
    }
    return 0;
}

static int ntfs_boot_candidate_offsets(
    const MftNtfsBootFields *fields,
    uint64_t boot_offset,
    uint64_t source_size,
    int as_backup,
    uint64_t *out_partition_start,
    uint64_t *out_primary_mft_offset,
    uint64_t *out_mirror_offset
)
{
    uint64_t partition_start;
    uint64_t backup_span;

    if (fields == NULL ||
        out_partition_start == NULL ||
        out_primary_mft_offset == NULL ||
        out_mirror_offset == NULL ||
        fields->cluster_size == 0ULL ||
        boot_offset > (uint64_t)LLONG_MAX) {
        return 0;
    }

    if (as_backup) {
        if (fields->volume_bytes == 0ULL ||
            fields->total_sectors == 0ULL ||
            boot_offset > UINT64_MAX - (uint64_t)fields->bytes_per_sector ||
            boot_offset + (uint64_t)fields->bytes_per_sector < fields->volume_bytes) {
            return 0;
        }
        backup_span =
            (fields->total_sectors - 1ULL) *
            (uint64_t)fields->bytes_per_sector;
        partition_start = boot_offset - backup_span;
        if (partition_start + backup_span != boot_offset) {
            return 0;
        }
    } else {
        partition_start = boot_offset;
    }

    if (partition_start > (uint64_t)LLONG_MAX ||
        (source_size > 0ULL &&
         (partition_start >= source_size ||
          fields->volume_bytes > source_size - partition_start)) ||
        fields->mft_lcn > (UINT64_MAX - partition_start) / fields->cluster_size ||
        fields->mirror_lcn > (UINT64_MAX - partition_start) / fields->cluster_size) {
        return 0;
    }

    *out_partition_start = partition_start;
    *out_primary_mft_offset =
        partition_start + fields->mft_lcn * fields->cluster_size;
    *out_mirror_offset =
        partition_start + fields->mirror_lcn * fields->cluster_size;
    if (*out_primary_mft_offset > (uint64_t)LLONG_MAX ||
        *out_mirror_offset > (uint64_t)LLONG_MAX) {
        return 0;
    }
    return 1;
}

static unsigned int ntfs_boot_candidate_score(
    int as_backup,
    int primary_signature,
    int mirror_signature
)
{
    unsigned int score = as_backup ? 20U : 40U;

    if (primary_signature == 2) {
        score += 10000U;
    } else if (primary_signature == 1) {
        score += 6000U;
    }
    if (mirror_signature == 2) {
        score += 5000U;
    } else if (mirror_signature == 1) {
        score += 3000U;
    }
    if (primary_signature != 0 && mirror_signature != 0) {
        score += 3000U;
    }
    return score;
}

static int ntfs_boot_candidate_is_better(
    const MftNtfsBootCandidate *candidate,
    const MftNtfsBootCandidate *best
)
{
    if (candidate == NULL || best == NULL) {
        return 0;
    }
    if (!best->found) {
        return 1;
    }
    if (candidate->score != best->score) {
        return candidate->score > best->score;
    }
    if (candidate->primary_signature != best->primary_signature) {
        return candidate->primary_signature > best->primary_signature;
    }
    if (candidate->mirror_signature != best->mirror_signature) {
        return candidate->mirror_signature > best->mirror_signature;
    }
    if (candidate->as_backup != best->as_backup) {
        return candidate->as_backup < best->as_backup;
    }
    return candidate->partition_start < best->partition_start;
}

static int consider_ntfs_boot_candidate_at(
    FILE *input_file,
    uint64_t source_size,
    uint64_t candidate_offset,
    int as_backup,
    const char *label,
    MftNtfsBootCandidateSearch *search
)
{
    unsigned char sector[512];
    MftNtfsBootFields fields;
    MftNtfsBootCandidate candidate;

    if (input_file == NULL ||
        search == NULL ||
        candidate_offset > (uint64_t)LLONG_MAX ||
        (source_size > 0ULL &&
         (candidate_offset > source_size ||
          sizeof(sector) > source_size - candidate_offset))) {
        return 0;
    }
    if (!read_sector_at(
            input_file,
            (long long)candidate_offset,
            sector,
            sizeof(sector))) {
        search->read_failures++;
        return 0;
    }
    if (!ntfs_boot_sector_fields_plausible(sector, &fields)) {
        return 0;
    }

    memset(&candidate, 0, sizeof(candidate));
    if (!ntfs_boot_candidate_offsets(
            &fields,
            candidate_offset,
            source_size,
            as_backup,
            &candidate.partition_start,
            &candidate.primary_mft_offset,
            &candidate.mirror_offset)) {
        return 0;
    }

    candidate.found = 1;
    candidate.boot_offset = candidate_offset;
    candidate.as_backup = as_backup ? 1 : 0;
    candidate.primary_signature =
        mft_record_signature_at(input_file, source_size, candidate.primary_mft_offset);
    candidate.mirror_signature =
        mft_record_signature_at(input_file, source_size, candidate.mirror_offset);
    candidate.score = ntfs_boot_candidate_score(
        candidate.as_backup,
        candidate.primary_signature,
        candidate.mirror_signature
    );
    if (label != NULL && label[0] != '\0') {
        snprintf(candidate.label, sizeof(candidate.label), "%s", label);
    } else {
        snprintf(candidate.label, sizeof(candidate.label), "%s", "orphan scan");
    }
    memcpy(candidate.boot_sector, sector, sizeof(candidate.boot_sector));

    search->plausible_count++;
    if (candidate.primary_signature != 0 || candidate.mirror_signature != 0) {
        search->signature_count++;
    }
    if (ntfs_boot_candidate_is_better(&candidate, &search->best)) {
        search->best = candidate;
    }
    return 1;
}

static int apply_best_ntfs_boot_candidate(MftNtfsBootCandidateSearch *search)
{
    const MftNtfsBootCandidate *best;

    if (search == NULL || !search->best.found) {
        return 0;
    }
    best = &search->best;
    if (!configure_ntfs_geometry_from_boot_sector(
            best->boot_sector,
            (long long)best->partition_start)) {
        return 0;
    }

    log_info(
        "Recovered NTFS geometry: %s boot=%llu volume_start=%lld mft=%lld(%s) mirror=%lld(%s)",
        best->as_backup ? "backup" : "orphan",
        (unsigned long long)best->boot_offset,
        g_partition_start,
        g_expected_mft_base_offset,
        mft_record_signature_label(best->primary_signature),
        g_expected_mft_mirror_offset,
        mft_record_signature_label(best->mirror_signature)
    );
    log_verbose(
        "Recovered NTFS geometry detail: source=%s label=%s plausible=%zu signature_evidence=%zu score=%u volume_start=%lld primary_mft=%lld primary_signature=%s mirror=%lld mirror_signature=%s",
        best->as_backup ? "backup" : "orphan",
        best->label,
        search->plausible_count,
        search->signature_count,
        best->score,
        g_partition_start,
        g_expected_mft_base_offset,
        mft_record_signature_label(best->primary_signature),
        g_expected_mft_mirror_offset,
        mft_record_signature_label(best->mirror_signature)
    );
    return 1;
}

static void collect_ntfs_backup_boot_from_gpt_partition_ends(
    FILE *input_file,
    uint64_t source_size,
    MftNtfsBootCandidateSearch *search
)
{
    unsigned char gpt_header[512];
    unsigned char *partition_entry = NULL;
    uint64_t entries_lba;
    uint32_t entry_count;
    uint32_t entry_size;
    uint32_t i;

    if (input_file == NULL ||
        search == NULL ||
        !read_sector_at(input_file, 512LL, gpt_header, sizeof(gpt_header)) ||
        memcmp(gpt_header, "EFI PART", 8) != 0) {
        return;
    }

    entries_lba = read_u64_le(gpt_header + 72);
    entry_count = read_u32_le(gpt_header + 80);
    entry_size = read_u32_le(gpt_header + 84);
    if (entries_lba == 0ULL || entry_count == 0U ||
        entry_size < 128U || entry_size > 4096U) {
        return;
    }
    if (entry_count > 4096U) {
        entry_count = 4096U;
    }

    partition_entry = (unsigned char *)malloc(entry_size);
    if (partition_entry == NULL) {
        return;
    }

    for (i = 0; i < entry_count && !app_stop_requested(); i++) {
        uint64_t first_lba;
        uint64_t last_lba;
        uint64_t candidate_offset;

        if (!read_sector_at(
                input_file,
                (long long)((entries_lba * 512ULL) + ((uint64_t)i * entry_size)),
                partition_entry,
                entry_size)) {
            continue;
        }
        if (bytes_are_all_zero(partition_entry, 16)) {
            continue;
        }

        first_lba = read_u64_le(partition_entry + 32);
        last_lba = read_u64_le(partition_entry + 40);
        if (first_lba == 0ULL ||
            last_lba < first_lba ||
            last_lba > (uint64_t)LLONG_MAX / 512ULL) {
            continue;
        }

        candidate_offset = last_lba * 512ULL;
        (void)consider_ntfs_boot_candidate_at(
            input_file,
            source_size,
            candidate_offset,
            1,
            "GPT partition end",
            search
        );
    }

    free(partition_entry);
}

static void collect_ntfs_backup_boot_from_mbr_partition_ends(
    FILE *input_file,
    const unsigned char *mbr_sector,
    uint64_t source_size,
    MftNtfsBootCandidateSearch *search
)
{
    int i;

    if (input_file == NULL ||
        search == NULL ||
        mbr_sector == NULL ||
        !has_valid_sector_signature(mbr_sector, 512)) {
        return;
    }

    for (i = 0; i < 4 && !app_stop_requested(); i++) {
        const unsigned char *entry = mbr_sector + 446 + (i * 16);
        uint32_t start_lba = read_u32_le(entry + 8);
        uint32_t sector_count = read_u32_le(entry + 12);
        uint64_t last_lba;

        if (start_lba == 0U || sector_count == 0U) {
            continue;
        }
        last_lba = (uint64_t)start_lba + (uint64_t)sector_count - 1ULL;
        if (last_lba > (uint64_t)LLONG_MAX / 512ULL) {
            continue;
        }
        (void)consider_ntfs_boot_candidate_at(
            input_file,
            source_size,
            last_lba * 512ULL,
            1,
            "MBR partition end",
            search
        );
    }
}

static void scan_ntfs_boot_sector_range(
    FILE *input_file,
    uint64_t source_size,
    uint64_t start_offset,
    uint64_t end_offset,
    uint64_t step_bytes,
    int as_backup,
    const char *label,
    MftNtfsBootCandidateSearch *search
)
{
    uint64_t offset;

    if (input_file == NULL ||
        search == NULL ||
        start_offset >= end_offset ||
        step_bytes == 0ULL) {
        return;
    }
    if (step_bytes <= 512ULL) {
        start_offset -= start_offset % MFT_BACKUP_BOOT_SCAN_STEP_BYTES;
    }
    for (offset = start_offset;
         offset + 512ULL <= end_offset && !app_stop_requested();
         offset += step_bytes) {
        (void)consider_ntfs_boot_candidate_at(
            input_file,
            source_size,
            offset,
            as_backup,
            label,
            search
        );
    }
}

static int try_recover_ntfs_geometry_from_orphan_boot_sectors(
    FILE *input_file,
    const unsigned char *first_sector,
    uint64_t source_size
)
{
    uint64_t tail_start;
    uint64_t front_end;
    MftNtfsBootCandidateSearch search;

    if (input_file == NULL || source_size < 512ULL) {
        return 0;
    }

    memset(&search, 0, sizeof(search));

    collect_ntfs_backup_boot_from_gpt_partition_ends(
        input_file,
        source_size,
        &search
    );
    collect_ntfs_backup_boot_from_mbr_partition_ends(
        input_file,
        first_sector,
        source_size,
        &search
    );
    (void)consider_ntfs_boot_candidate_at(
        input_file,
        source_size,
        source_size - 512ULL,
        1,
        "source end",
        &search
    );

    tail_start = source_size > MFT_BACKUP_BOOT_TAIL_SCAN_BYTES
        ? source_size - MFT_BACKUP_BOOT_TAIL_SCAN_BYTES
        : 0ULL;
    scan_ntfs_boot_sector_range(
        input_file,
        source_size,
        tail_start,
        source_size,
        MFT_BACKUP_BOOT_SCAN_STEP_BYTES,
        1,
        "tail backup scan",
        &search
    );

    front_end = source_size < MFT_BACKUP_BOOT_FRONT_SCAN_BYTES
        ? source_size
        : MFT_BACKUP_BOOT_FRONT_SCAN_BYTES;
    scan_ntfs_boot_sector_range(
        input_file,
        source_size,
        0ULL,
        front_end,
        MFT_BACKUP_BOOT_SCAN_STEP_BYTES,
        0,
        "front sparse scan",
        &search
    );

    if (g_force_ntfs_target && !app_stop_requested()) {
        uint64_t forced_front_end =
            source_size < MFT_FORCED_BOOT_SCAN_FRONT_BYTES
                ? source_size
                : MFT_FORCED_BOOT_SCAN_FRONT_BYTES;
        uint64_t forced_tail_start =
            source_size > MFT_FORCED_BOOT_SCAN_TAIL_BYTES
                ? source_size - MFT_FORCED_BOOT_SCAN_TAIL_BYTES
                : 0ULL;

        if (forced_front_end > front_end) {
            scan_ntfs_boot_sector_range(
                input_file,
                source_size,
                front_end,
                forced_front_end,
                MFT_FORCED_BOOT_SCAN_STEP_BYTES,
                0,
                "forced front sparse scan",
                &search
            );
        }
        if (forced_tail_start < tail_start) {
            uint64_t backup_phase_start =
                forced_tail_start + MFT_FORCED_BOOT_SCAN_STEP_BYTES - 512ULL;
            if (backup_phase_start < forced_tail_start ||
                backup_phase_start >= tail_start) {
                backup_phase_start = forced_tail_start;
            }
            scan_ntfs_boot_sector_range(
                input_file,
                source_size,
                backup_phase_start,
                tail_start,
                MFT_FORCED_BOOT_SCAN_STEP_BYTES,
                1,
                "forced tail backup sparse scan",
                &search
            );
        }
    }

    return apply_best_ntfs_boot_candidate(&search);
}

static int input_path_is_direct_mft_file(const char *input_path)
{
    const char *basename;

    if (input_path == NULL) {
        return 0;
    }

    basename = strrchr(input_path, '/');
    if (basename == NULL) {
        basename = input_path;
    } else {
        basename++;
    }

    return strcmp(basename, "$MFT") == 0;
}

int mft_configure_from_source(const char *input_path)
{
    FILE *input_file;
    unsigned char boot_sector[512];
    long long gpt_partition_start = 0;
    long long mbr_partition_start = 0;
    uint64_t source_size = 0ULL;

    /*
     * Reset cached geometry first, then inspect the source to decide
     * whether we are looking at a raw NTFS volume, a partition inside a
     * larger image, or a direct `$MFT` file.
     */
    g_expected_mft_base_offset = -1;
    g_expected_mft_mirror_offset = -1;
    g_mft_base_offset = -1;
    g_mft_scan_end_offset = -1;
    g_partition_start = 0;
    clear_mft_resume_offset_delta_local();
    g_cluster_size = 4096;
    g_mft_record_size = 1024;
    g_has_ntfs_geometry = 0;
    g_ntfs_volume_serial = 0ULL;
    g_direct_mft_source = 0;
    g_partial_record_salvage = 0;
    g_catalog_first_mode = 0;
    mft_reset_record_salvage_stats();
    g_source_is_definitely_non_ntfs = 0;
    g_source_filesystem_hint[0] = '\0';
    g_mft_infer_prev_offset = 0;
    g_mft_infer_prev_record = 0;
    g_mft_infer_have_prev = 0;

    if (input_path == NULL) {
        return 0;
    }

#ifdef __APPLE__
    maybe_set_macos_non_ntfs_hint_local(input_path);
#endif

    if (input_path_is_direct_mft_file(input_path)) {
        g_expected_mft_base_offset = 0;
        g_mft_base_offset = 0;
        g_expected_mft_mirror_offset = -1;
        g_has_ntfs_geometry = 1;
        g_direct_mft_source = 1;
        mark_source_as_confirmed_ntfs_local();
        mft_stats_start_run(input_path, NULL, 0);
        mft_stats_write_geometry();
        log_info("Detected direct $MFT file source");
        return 1;
    }

    input_file = fopen(input_path, "rb");
    if (input_file == NULL) {
        if (mft_source_error_is_fatal_device_error(errno)) {
            app_request_source_reconnect("NTFS metadata bootstrap", errno);
        }
        return 0;
    }

    if (fread(boot_sector, 1, sizeof(boot_sector), input_file) != sizeof(boot_sector)) {
        if (ferror(input_file) &&
            mft_source_error_is_fatal_device_error(errno != 0 ? errno : EIO)) {
            app_request_source_reconnect(
                "NTFS metadata bootstrap",
                errno != 0 ? errno : EIO
            );
        }
        fclose(input_file);
        return 0;
    }

    mft_stats_start_run(input_path, boot_sector, sizeof(boot_sector));
    (void)get_seekable_source_size_local(input_file, &source_size);

    if (configure_ntfs_geometry_from_boot_sector(boot_sector, 0)) {
        fclose(input_file);
        mark_source_as_confirmed_ntfs_local();
        mft_stats_write_geometry();
        log_verbose("Detected NTFS source volume at offset 0");
        log_detected_mft_mirror();
        return 1;
    }

#ifdef __APPLE__
    if (configure_ntfs_geometry_from_macos_diskutil(input_path, input_file)) {
        fclose(input_file);
        mark_source_as_confirmed_ntfs_local();
        mft_stats_write_geometry();
        log_info("Detected macOS NTFS partition at offset %lld", g_partition_start);
        log_detected_mft_mirror();
        return 1;
    }
#endif

    if (find_gpt_ntfs_partition_start(input_file, &gpt_partition_start)) {
        if (!read_sector_at(
                input_file,
                gpt_partition_start,
                boot_sector,
                sizeof(boot_sector))) {
            goto try_orphan_ntfs_boot;
        }

        if (!configure_ntfs_geometry_from_boot_sector(
                boot_sector,
                gpt_partition_start)) {
            goto try_orphan_ntfs_boot;
        }

        fclose(input_file);
        mark_source_as_confirmed_ntfs_local();
        mft_stats_write_geometry();
        log_info("Detected GPT NTFS partition at offset %lld", gpt_partition_start);
        log_detected_mft_mirror();
        return 1;
    }

    if (!find_mbr_ntfs_partition_start(boot_sector, &mbr_partition_start)) {
        goto try_orphan_ntfs_boot;
    }

    if (!read_sector_at(
            input_file,
            mbr_partition_start,
            boot_sector,
            sizeof(boot_sector))) {
        goto try_orphan_ntfs_boot;
    }

    if (!configure_ntfs_geometry_from_boot_sector(
            boot_sector,
            mbr_partition_start)) {
        goto try_orphan_ntfs_boot;
    }

    fclose(input_file);
    mark_source_as_confirmed_ntfs_local();
    mft_stats_write_geometry();
    //log_info("Detected MBR NTFS partition at offset %lld", mbr_partition_start);
    log_detected_mft_mirror();
    return 1;

try_orphan_ntfs_boot:
    if (try_recover_ntfs_geometry_from_orphan_boot_sectors(
            input_file,
            boot_sector,
            source_size)) {
        fclose(input_file);
        mark_source_as_confirmed_ntfs_local();
        mft_stats_write_geometry();
        log_detected_mft_mirror();
        return 1;
    }

#ifdef __APPLE__
    maybe_set_macos_non_ntfs_hint_local(input_path);
    commit_macos_non_ntfs_hint_local();
#endif

    fclose(input_file);
    return 0;
}

int mft_has_ntfs_geometry(void)
{
    return g_has_ntfs_geometry;
}

int mft_source_is_definitely_non_ntfs(void)
{
    return g_source_is_definitely_non_ntfs;
}

const char *mft_source_filesystem_hint(void)
{
    return g_source_filesystem_hint;
}

uint64_t mft_get_ntfs_volume_serial(void)
{
    return g_ntfs_volume_serial;
}

size_t mft_get_record_size(void)
{
    return (g_mft_record_size == 0) ? 1024U : (size_t)g_mft_record_size;
}

long long mft_get_partition_start(void)
{
    return g_partition_start;
}

uint32_t mft_get_cluster_size(void)
{
    return g_cluster_size;
}

int mft_is_record_candidate_offset(size_t absolute_offset)
{
    long long base_offset;
    long long delta;

    if (!g_has_ntfs_geometry || g_mft_record_size == 0) {
        return 1;
    }

    base_offset = g_mft_base_offset;
    if (base_offset < 0) {
        base_offset = g_expected_mft_base_offset;
    }
    if (base_offset < 0) {
        return 1;
    }

    if ((long long)absolute_offset < base_offset) {
        return 0;
    }

    delta = (long long)absolute_offset - base_offset;
    return (delta % (long long)g_mft_record_size) == 0;
}

size_t mft_next_candidate_offset(size_t absolute_offset)
{
    long long base_offset;
    long long delta;
    long long remainder;

    if (!g_has_ntfs_geometry || g_mft_record_size == 0) {
        return absolute_offset + 1;
    }

    base_offset = g_mft_base_offset;
    if (base_offset < 0) {
        base_offset = g_expected_mft_base_offset;
    }
    if (base_offset < 0) {
        return absolute_offset + 1;
    }

    if ((long long)absolute_offset < base_offset) {
        return (size_t)base_offset;
    }

    delta = (long long)absolute_offset - base_offset;
    remainder = delta % (long long)g_mft_record_size;

    if (remainder == 0) {
        return absolute_offset;
    }

    return absolute_offset +
           ((size_t)g_mft_record_size - (size_t)remainder);
}

long long mft_get_scan_end_offset(void)
{
    return g_mft_scan_end_offset;
}

long long mft_get_primary_scan_start_offset(void)
{
    if (g_expected_mft_base_offset >= 0) {
        return g_expected_mft_base_offset;
    }

    if (g_mft_base_offset >= 0) {
        return g_mft_base_offset;
    }

    return 0;
}

long long mft_get_expected_mft_mirror_offset(void)
{
    return g_expected_mft_mirror_offset;
}

static MftEntry *find_primary_mft_entry(void)
{
    size_t i;

    for (i = 0; i < g_mft_entry_count; i++) {
        MftEntry *entry = &g_mft_entries[i];

        if (entry->source_kind == MFT_ENTRY_SOURCE_PRIMARY &&
            entry->record_number == 0 &&
            entry->has_name &&
            strcmp(entry->name, "$MFT") == 0 &&
            entry->run_extents != NULL &&
            entry->run_extent_count > 0) {
            return entry;
        }
    }

    return NULL;
}

size_t mft_get_primary_mft_run_count(void)
{
    MftEntry *entry = find_primary_mft_entry();

    return (entry == NULL) ? 0 : entry->run_extent_count;
}

uint64_t mft_get_primary_mft_total_bytes(void)
{
    MftEntry *entry = find_primary_mft_entry();
    uint64_t total = 0ULL;
    size_t i;

    if (entry == NULL || entry->run_extents == NULL) {
        return 0ULL;
    }

    for (i = 0; i < entry->run_extent_count; i++) {
        uint64_t extent_bytes =
            entry->run_extents[i].cluster_count * (uint64_t)g_cluster_size;

        if (UINT64_MAX - total < extent_bytes) {
            return UINT64_MAX;
        }
        total += extent_bytes;
    }

    return total;
}

uint64_t mft_get_estimated_mft_mirror_bytes(void)
{
    uint64_t record_size;

    if (g_expected_mft_mirror_offset < 0) {
        return 0ULL;
    }

    /*
     * NTFS keeps $MFTMirr as a backup copy of the first four MFT records.
     * We only need a compact estimate here for progress/state reporting.
     */
    record_size = g_mft_record_size > 0U ? (uint64_t)g_mft_record_size : 1024ULL;
    if (record_size > UINT64_MAX / 4ULL) {
        return UINT64_MAX;
    }

    return record_size * 4ULL;
}

int mft_get_primary_mft_run(
    size_t index,
    uint64_t *out_abs_offset,
    uint64_t *out_byte_length
)
{
    MftEntry *entry = find_primary_mft_entry();
    MftRunExtent *extent;

    if (entry == NULL ||
        index >= entry->run_extent_count ||
        out_abs_offset == NULL ||
        out_byte_length == NULL) {
        return 0;
    }

    extent = &entry->run_extents[index];
    *out_abs_offset =
        (uint64_t)g_partition_start +
        (extent->start_lcn * (uint64_t)g_cluster_size);
    *out_byte_length = extent->cluster_count * (uint64_t)g_cluster_size;
    return *out_byte_length > 0;
}

int mft_has_primary_users_root(void)
{
    size_t i;

    for (i = 0; i < g_mft_entry_count; i++) {
        const MftEntry *entry = &g_mft_entries[i];

        if (entry->source_kind == MFT_ENTRY_SOURCE_PRIMARY &&
            entry->has_name &&
            (entry->flags & 0x0002) != 0 &&
            entry->parent_record == 5U &&
            name_is_user_root(entry->name)) {
            return 1;
        }
    }

    return 0;
}

/* ========================= FS HELPERS ========================= */

static int parse_owner_id_from_env(const char *name, unsigned long *out_value)
{
    const char *raw_value;
    char *end = NULL;
    unsigned long parsed_value;

    if (name == NULL || out_value == NULL) {
        return 0;
    }

    raw_value = getenv(name);
    if (raw_value == NULL || *raw_value == '\0') {
        return 0;
    }

    errno = 0;
    parsed_value = strtoul(raw_value, &end, 10);
    if (errno != 0 || end == NULL || *end != '\0') {
        return 0;
    }

    *out_value = parsed_value;
    return 1;
}

static int resolve_output_owner(uid_t *out_uid, gid_t *out_gid)
{
    struct stat current_dir_stat;
    unsigned long sudo_uid;
    unsigned long sudo_gid;

    if (out_uid == NULL || out_gid == NULL) {
        return 0;
    }

    if (geteuid() != 0) {
        return 0;
    }

    if (parse_owner_id_from_env("SUDO_UID", &sudo_uid) &&
        parse_owner_id_from_env("SUDO_GID", &sudo_gid)) {
        *out_uid = (uid_t)sudo_uid;
        *out_gid = (gid_t)sudo_gid;
        return 1;
    }

    if (stat(".", &current_dir_stat) == 0 && current_dir_stat.st_uid != 0) {
        *out_uid = current_dir_stat.st_uid;
        *out_gid = current_dir_stat.st_gid;
        return 1;
    }

    return 0;
}

static int apply_output_monitor_access_mode(const char *path)
{
    struct stat st;
    mode_t desired_mode;

    if (path == NULL || stat(path, &st) != 0) {
        return 0;
    }
    if (S_ISDIR(st.st_mode)) {
        desired_mode = st.st_mode |
            S_IRUSR | S_IWUSR | S_IXUSR |
            S_IRGRP | S_IXGRP |
            S_IROTH | S_IXOTH;
    } else if (S_ISREG(st.st_mode)) {
        desired_mode = st.st_mode |
            S_IRUSR | S_IWUSR |
            S_IRGRP |
            S_IROTH;
    } else {
        return 1;
    }

    return chmod(path, desired_mode & 07777) == 0;
}

int mft_apply_output_owner_to_path(const char *path)
{
    uid_t target_uid;
    gid_t target_gid;
    int access_mode_ok;

    if (path == NULL) {
        return 0;
    }

    access_mode_ok = apply_output_monitor_access_mode(path);
    if (!resolve_output_owner(&target_uid, &target_gid)) {
        return access_mode_ok || geteuid() != 0;
    }

    if (chown(path, target_uid, target_gid) != 0) {
        return access_mode_ok;
    }

    return 1;
}

static int mft_text_present_local(const char *text)
{
    return text != NULL && text[0] != '\0';
}

static int mft_output_mount_root_from_path_local(
    const char *path,
    char *out_root,
    size_t out_root_size
)
{
    if (out_root != NULL && out_root_size > 0U) {
        out_root[0] = '\0';
    }
    if (!mft_text_present_local(path) || out_root == NULL || out_root_size == 0U) {
        return 0;
    }

    if (strncmp(path, "/media/", 7U) == 0) {
        const char *rest = path + 7U;
        const char *user_slash = strchr(rest, '/');
        const char *leaf_start;
        const char *leaf_slash;
        size_t root_len;

        if (user_slash == NULL || user_slash == rest || user_slash[1] == '\0') {
            return 0;
        }
        leaf_start = user_slash + 1;
        leaf_slash = strchr(leaf_start, '/');
        root_len = leaf_slash != NULL ? (size_t)(leaf_slash - path) : strlen(path);
        if (root_len == 0U || root_len >= out_root_size) {
            return 0;
        }
        memcpy(out_root, path, root_len);
        out_root[root_len] = '\0';
        return 1;
    }

    if (strncmp(path, "/Volumes/", 9U) == 0) {
        const char *leaf_start = path + 9U;
        const char *leaf_slash;
        size_t root_len;

        if (*leaf_start == '\0') {
            return 0;
        }
        leaf_slash = strchr(leaf_start, '/');
        root_len = leaf_slash != NULL ? (size_t)(leaf_slash - path) : strlen(path);
        if (root_len == 0U || root_len >= out_root_size) {
            return 0;
        }
        memcpy(out_root, path, root_len);
        out_root[root_len] = '\0';
        return 1;
    }

    return 0;
}

static int mft_parent_path_local(
    const char *path,
    char *out_parent,
    size_t out_parent_size
)
{
    const char *last_slash;
    size_t parent_len;

    if (out_parent != NULL && out_parent_size > 0U) {
        out_parent[0] = '\0';
    }
    if (!mft_text_present_local(path) || out_parent == NULL || out_parent_size == 0U) {
        return 0;
    }

    last_slash = strrchr(path, '/');
    if (last_slash == NULL) {
        return 0;
    }
    if (last_slash == path) {
        return snprintf(out_parent, out_parent_size, "/") < (int)out_parent_size;
    }
    parent_len = (size_t)(last_slash - path);
    if (parent_len == 0U || parent_len >= out_parent_size) {
        return 0;
    }
    memcpy(out_parent, path, parent_len);
    out_parent[parent_len] = '\0';
    return 1;
}

static int mft_output_mount_root_is_live_local(const char *mount_root)
{
    char parent[PATH_MAX];
    struct stat mount_st;
    struct stat parent_st;

    if (!mft_text_present_local(mount_root) ||
        stat(mount_root, &mount_st) != 0 ||
        !S_ISDIR(mount_st.st_mode) ||
        !mft_parent_path_local(mount_root, parent, sizeof(parent)) ||
        stat(parent, &parent_st) != 0) {
        return 0;
    }

    return mount_st.st_dev != parent_st.st_dev;
}

static int mft_output_path_write_guard_allows(
    const char *path,
    const char *operation
)
{
    char mount_root[PATH_MAX];
    unsigned int waited_seconds;
    static int warned = 0;

    if (!mft_output_mount_root_from_path_local(path, mount_root, sizeof(mount_root))) {
        return 1;
    }
    if (mft_output_mount_root_is_live_local(mount_root)) {
        return 1;
    }
    for (waited_seconds = 0U;
         waited_seconds < MFT_OUTPUT_MOUNT_GRACE_SECONDS;
         waited_seconds++) {
        sleep(1);
        if (mft_output_mount_root_is_live_local(mount_root)) {
            return 1;
        }
    }

    if (!warned) {
        warned = 1;
        log_error(
            "Refusing to %s under %s because %s is not a live mounted output volume; reconnect the output disk or resume using its new mount path before writing.",
            mft_text_present_local(operation) ? operation : "write NTFS metadata",
            path,
            mount_root
        );
    }
    return 0;
}

static int ensure_log_directory(void)
{
    const char *output_dir = mft_get_output_dir();
    char state_dir[1024];

    if (output_dir == NULL || output_dir[0] == '\0') {
        return 0;
    }
    if (!mft_output_path_write_guard_allows(output_dir, "create NTFS output directory")) {
        return 0;
    }

    if (!ensure_directory_recursive(output_dir) ||
        !mft_apply_output_owner_to_path(output_dir)) {
        return 0;
    }

    if (!mft_build_output_path(state_dir, sizeof(state_dir), APP_STATE_DIR_NAME)) {
        return 0;
    }
    if (!ensure_directory_recursive(state_dir)) {
        return 0;
    }
    return mft_apply_output_owner_to_path(state_dir);
}

static void mft_i30_probe_state_reset(void)
{
    memset(&g_mft_i30_probe_stats, 0, sizeof(g_mft_i30_probe_stats));
    g_mft_i30_probe_state_last_write_at = 0.0;
    g_mft_i30_probe_state_last_dirty_events = 0U;
    g_mft_i30_probe_state_write_failure_logged = 0;
    g_mft_i30_name_log_write_failure_logged = 0;
}

static void mft_state_write_metric(
    FILE *file,
    const char *name,
    uint64_t value
)
{
    if (file == NULL || name == NULL) {
        return;
    }
    fprintf(file, "%s\t%llu\n", name, (unsigned long long)value);
}

static void mft_state_write_text_metric(
    FILE *file,
    const char *name,
    const char *value
)
{
    const char *cursor;

    if (file == NULL || name == NULL) {
        return;
    }
    fprintf(file, "%s\t", name);
    cursor = value != NULL && value[0] != '\0' ? value : "-";
    while (*cursor != '\0') {
        unsigned char ch = (unsigned char)*cursor;

        fputc(
            ch == '\t' || ch == '\r' || ch == '\n' ? ' ' : (int)ch,
            file
        );
        cursor++;
    }
    fputc('\n', file);
}

static void mft_state_write_run_identity_metrics(FILE *file)
{
    mft_state_write_metric(
        file,
        "supervisor_generation",
        carv_run_supervisor_generation_inline()
    );
    mft_state_write_text_metric(
        file,
        "pass_id",
        carv_run_pass_id_inline()
    );
}

static int mft_state_snapshot_should_skip(
    int force,
    uint64_t dirty_events,
    uint64_t last_dirty_events,
    double last_write_at,
    uint64_t dirty_interval,
    double now
)
{
    if (g_mft_state_writes_suppressed) {
        return 1;
    }
    if (!force && dirty_events == last_dirty_events) {
        return 1;
    }
    if (!force &&
        last_write_at > 0.0 &&
        now - last_write_at < MFT_I30_PROBE_STATE_WRITE_MIN_SECONDS &&
        dirty_events - last_dirty_events < dirty_interval) {
        return 1;
    }
    return 0;
}

static void mft_state_log_write_failure_once(
    int *logged,
    const char *counter_label,
    const char *path,
    const char *reason
)
{
    if (logged == NULL || *logged) {
        return;
    }
    *logged = 1;
    log_error(
        "Failed to write %s%s%s%s",
        counter_label != NULL && counter_label[0] != '\0'
            ? counter_label
            : "NTFS state counter",
        path != NULL && path[0] != '\0' ? " to " : "",
        path != NULL && path[0] != '\0' ? path : "",
        reason != NULL && reason[0] != '\0' ? reason : ""
    );
}

static FILE *mft_state_snapshot_open(
    char *path,
    size_t path_size,
    const char *fixed_name,
    const char *counter_label,
    int *failure_logged,
    uint64_t *write_failures
)
{
    FILE *file;

    if (path == NULL || path_size == 0U) {
        return NULL;
    }
    path[0] = '\0';
    if (!build_fixed_mft_output_path(path, path_size, fixed_name) ||
        !ensure_log_directory()) {
        if (write_failures != NULL) {
            (*write_failures)++;
        }
        mft_state_log_write_failure_once(
            failure_logged,
            counter_label,
            path,
            " (path/state directory unavailable)"
        );
        return NULL;
    }

    file = fopen(path, "w");
    if (file == NULL) {
        if (write_failures != NULL) {
            (*write_failures)++;
        }
        mft_state_log_write_failure_once(
            failure_logged,
            counter_label,
            path,
            ": fopen failed"
        );
        return NULL;
    }

    return file;
}

static int mft_state_snapshot_close(
    FILE *file,
    const char *path,
    const char *counter_label,
    int *failure_logged,
    uint64_t *write_failures
)
{
    if (file == NULL) {
        return 0;
    }
    if (fclose(file) != 0) {
        if (write_failures != NULL) {
            (*write_failures)++;
        }
        mft_state_log_write_failure_once(
            failure_logged,
            counter_label,
            path,
            ": fclose failed"
        );
        return 0;
    }
    (void)mft_apply_output_owner_to_path(path);
    return 1;
}

static void mft_i30_probe_state_write_snapshot(int force)
{
    char path[1024] = "";
    FILE *file;
    double now = monotonic_seconds_local();
    uint64_t name_catalog_i30_backed = 0ULL;
    uint64_t name_catalog_usn_backed = 0ULL;
    uint64_t name_catalog_usn_only = 0ULL;
    size_t slot;

    if (mft_state_snapshot_should_skip(
            force,
            g_mft_i30_probe_stats.dirty_events,
            g_mft_i30_probe_state_last_dirty_events,
            g_mft_i30_probe_state_last_write_at,
            MFT_I30_PROBE_STATE_WRITE_DIRTY_INTERVAL,
            now)) {
        return;
    }

    g_mft_i30_probe_stats.write_attempts++;
    g_mft_i30_probe_state_last_write_at = now;

    file = mft_state_snapshot_open(
        path,
        sizeof(path),
        MFT_I30_PROBE_STATE_FILE_NAME,
        "NTFS $I30 probe counter",
        &g_mft_i30_probe_state_write_failure_logged,
        &g_mft_i30_probe_stats.write_failures
    );
    if (file == NULL) {
        return;
    }

    g_mft_i30_probe_stats.last_write_unix = (uint64_t)time(NULL);
    for (slot = 0U; slot < g_mft_i30_name_index_capacity; slot++) {
        const MftI30NameEntry *entry = &g_mft_i30_name_index[slot];

        if (!entry->in_use || entry->name[0] == '\0') {
            continue;
        }
        if ((entry->source_flags & MFT_NAME_CATALOG_SOURCE_I30) != 0U) {
            name_catalog_i30_backed++;
        }
        if ((entry->source_flags & MFT_NAME_CATALOG_SOURCE_USN) != 0U) {
            name_catalog_usn_backed++;
            if ((entry->source_flags & MFT_NAME_CATALOG_SOURCE_I30) == 0U) {
                name_catalog_usn_only++;
            }
        }
    }
    fprintf(file, "metric\tvalue\n");
    mft_state_write_metric(file, "schema_version", 1U);
    mft_state_write_metric(file, "updated_unix", g_mft_i30_probe_stats.last_write_unix);
    mft_state_write_run_identity_metrics(file);
    mft_state_write_metric(file, "i30_names_current", (uint64_t)g_mft_i30_name_index_count);
    mft_state_write_metric(file, "name_catalog_i30_backed", name_catalog_i30_backed);
    mft_state_write_metric(file, "name_catalog_usn_backed", name_catalog_usn_backed);
    mft_state_write_metric(file, "name_catalog_usn_only", name_catalog_usn_only);
    mft_state_write_metric(file, "parsed_mft_records", g_mft_i30_probe_stats.parsed_mft_records);
    mft_state_write_metric(file, "tracked_mft_records", g_mft_i30_probe_stats.tracked_mft_records);
    mft_state_write_metric(file, "mft_directory_records", g_mft_i30_probe_stats.mft_directory_records);
    mft_state_write_metric(file, "mft_directory_records_with_i30_children", g_mft_i30_probe_stats.mft_directory_records_with_i30_children);
    mft_state_write_metric(file, "mft_directory_records_with_i30_allocation", g_mft_i30_probe_stats.mft_directory_records_with_i30_allocation);
    mft_state_write_metric(file, "index_root_children_seen", g_mft_i30_probe_stats.index_root_children_seen);
    mft_state_write_metric(file, "index_root_children_rejected_empty", g_mft_i30_probe_stats.index_root_children_rejected_empty);
    mft_state_write_metric(file, "index_root_children_rejected_by_format", g_mft_i30_probe_stats.index_root_children_rejected_by_format);
    mft_state_write_metric(file, "index_root_children_accepted", g_mft_i30_probe_stats.index_root_children_accepted);
    mft_state_write_metric(file, "index_root_children_put_failed", g_mft_i30_probe_stats.index_root_children_put_failed);
    mft_state_write_metric(file, "i30_target_collect_calls", g_mft_i30_probe_stats.i30_target_collect_calls);
    mft_state_write_metric(file, "i30_target_probe_calls", g_mft_i30_probe_stats.i30_target_probe_calls);
    mft_state_write_metric(file, "i30_target_fill_calls", g_mft_i30_probe_stats.i30_target_fill_calls);
    mft_state_write_metric(file, "i30_target_directory_records_seen", g_mft_i30_probe_stats.i30_target_directory_records_seen);
    mft_state_write_metric(file, "i30_target_runs_seen", g_mft_i30_probe_stats.i30_target_runs_seen);
    mft_state_write_metric(file, "i30_target_runs_returned_total", g_mft_i30_probe_stats.i30_target_runs_returned_total);
    mft_state_write_metric(file, "i30_target_count_last", g_mft_i30_probe_stats.i30_target_count_last);
    mft_state_write_metric(file, "i30_target_count_max", g_mft_i30_probe_stats.i30_target_count_max);
    mft_state_write_metric(file, "i30_target_prioritized_entries_last", g_mft_i30_probe_stats.i30_target_prioritized_entries_last);
    mft_state_write_metric(file, "i30_target_prioritized_entries_max", g_mft_i30_probe_stats.i30_target_prioritized_entries_max);
    mft_state_write_metric(file, "i30_absorb_calls", g_mft_i30_probe_stats.i30_absorb_calls);
    mft_state_write_metric(file, "i30_absorb_invalid_calls", g_mft_i30_probe_stats.i30_absorb_invalid_calls);
    mft_state_write_metric(file, "i30_absorb_known_target_calls", g_mft_i30_probe_stats.i30_absorb_known_target_calls);
    mft_state_write_metric(file, "i30_absorb_unanchored_calls", g_mft_i30_probe_stats.i30_absorb_unanchored_calls);
    mft_state_write_metric(file, "i30_blocks_checked", g_mft_i30_probe_stats.i30_blocks_checked);
    mft_state_write_metric(file, "i30_blocks_without_signature", g_mft_i30_probe_stats.i30_blocks_without_signature);
    mft_state_write_metric(file, "i30_blocks_fixup_failed", g_mft_i30_probe_stats.i30_blocks_fixup_failed);
    mft_state_write_metric(file, "i30_blocks_header_invalid", g_mft_i30_probe_stats.i30_blocks_header_invalid);
    mft_state_write_metric(file, "i30_header_invalid_entries_offset_too_small", g_mft_i30_probe_stats.i30_header_invalid_entries_offset_too_small);
    mft_state_write_metric(file, "i30_header_invalid_entries_offset_too_large", g_mft_i30_probe_stats.i30_header_invalid_entries_offset_too_large);
    mft_state_write_metric(file, "i30_header_invalid_entries_size_zero", g_mft_i30_probe_stats.i30_header_invalid_entries_size_zero);
    mft_state_write_metric(file, "i30_header_invalid_entries_size_before_entries_offset", g_mft_i30_probe_stats.i30_header_invalid_entries_size_before_entries_offset);
    mft_state_write_metric(file, "i30_header_invalid_allocated_size_lt_entries_size", g_mft_i30_probe_stats.i30_header_invalid_allocated_size_lt_entries_size);
    mft_state_write_metric(file, "i30_header_invalid_allocated_size_too_large", g_mft_i30_probe_stats.i30_header_invalid_allocated_size_too_large);
    mft_state_write_metric(file, "i30_header_invalid_entries_end_out_of_block", g_mft_i30_probe_stats.i30_header_invalid_entries_end_out_of_block);
    mft_state_write_metric(file, "i30_header_invalid_allocated_end_out_of_block", g_mft_i30_probe_stats.i30_header_invalid_allocated_end_out_of_block);
    mft_state_write_metric(file, "i30_header_invalid_samples_written", g_mft_i30_probe_stats.i30_header_invalid_samples_written);
    mft_state_write_metric(file, "i30_header_invalid_samples_suppressed", g_mft_i30_probe_stats.i30_header_invalid_samples_suppressed);
    mft_state_write_metric(file, "i30_header_invalid_sample_write_failures", g_mft_i30_probe_stats.i30_header_invalid_sample_write_failures);
    mft_state_write_metric(file, "i30_blocks_parsed", g_mft_i30_probe_stats.i30_blocks_parsed);
    mft_state_write_metric(file, "i30_active_entries_seen", g_mft_i30_probe_stats.i30_active_entries_seen);
    mft_state_write_metric(file, "i30_active_entries_malformed", g_mft_i30_probe_stats.i30_active_entries_malformed);
    mft_state_write_metric(file, "i30_active_entries_rejected_by_format", g_mft_i30_probe_stats.i30_active_entries_rejected_by_format);
    mft_state_write_metric(file, "i30_active_entries_accepted", g_mft_i30_probe_stats.i30_active_entries_accepted);
    mft_state_write_metric(file, "i30_active_entries_put_failed", g_mft_i30_probe_stats.i30_active_entries_put_failed);
    mft_state_write_metric(file, "i30_slack_entries_seen", g_mft_i30_probe_stats.i30_slack_entries_seen);
    mft_state_write_metric(file, "i30_slack_entries_rejected_by_format", g_mft_i30_probe_stats.i30_slack_entries_rejected_by_format);
    mft_state_write_metric(file, "i30_slack_entries_accepted", g_mft_i30_probe_stats.i30_slack_entries_accepted);
    mft_state_write_metric(file, "i30_slack_entries_put_failed", g_mft_i30_probe_stats.i30_slack_entries_put_failed);
    mft_state_write_metric(file, "i30_name_put_attempts", g_mft_i30_probe_stats.i30_name_put_attempts);
    mft_state_write_metric(file, "i30_name_put_rejected_invalid", g_mft_i30_probe_stats.i30_name_put_rejected_invalid);
    mft_state_write_metric(file, "i30_name_put_failed_capacity", g_mft_i30_probe_stats.i30_name_put_failed_capacity);
    mft_state_write_metric(file, "i30_name_put_new", g_mft_i30_probe_stats.i30_name_put_new);
    mft_state_write_metric(file, "i30_name_put_updated", g_mft_i30_probe_stats.i30_name_put_updated);
    mft_state_write_metric(file, "i30_name_put_unchanged", g_mft_i30_probe_stats.i30_name_put_unchanged);
    mft_state_write_metric(file, "i30_name_log_append_attempts", g_mft_i30_probe_stats.i30_name_log_append_attempts);
    mft_state_write_metric(file, "i30_name_log_append_ok", g_mft_i30_probe_stats.i30_name_log_append_ok);
    mft_state_write_metric(file, "i30_name_log_append_failed", g_mft_i30_probe_stats.i30_name_log_append_failed);
    mft_state_write_metric(file, "write_attempts", g_mft_i30_probe_stats.write_attempts);
    mft_state_write_metric(file, "write_failures", g_mft_i30_probe_stats.write_failures);
    mft_state_write_metric(file, "dirty_events", g_mft_i30_probe_stats.dirty_events);

    if (!mft_state_snapshot_close(
            file,
            path,
            "NTFS $I30 probe counter",
            &g_mft_i30_probe_state_write_failure_logged,
            &g_mft_i30_probe_stats.write_failures)) {
        return;
    }

    g_mft_i30_probe_state_last_dirty_events =
        g_mft_i30_probe_stats.dirty_events;
}

static void mft_i30_probe_state_mark_dirty(void)
{
    g_mft_i30_probe_stats.dirty_events++;
    mft_i30_probe_state_write_snapshot(0);
}

