static void mft_catalog_chain_eval_reset(MftCatalogChainEval *eval)
{
    if (eval != NULL) {
        memset(eval, 0, sizeof(*eval));
    }
}

static void mft_catalog_chain_eval_note_parent_seq(
    uint16_t expected_seq,
    uint16_t actual_seq,
    MftCatalogChainEval *eval
)
{
    if (eval == NULL) {
        return;
    }
    if (expected_seq == 0U || actual_seq == 0U) {
        return;
    }
    eval->seq_checked = 1;
    if (expected_seq != actual_seq) {
        eval->seq_conflict = 1;
    }
}

static void mft_catalog_eval_entry_chain(
    const MftEntry *entry,
    MftCatalogChainEval *eval
)
{
    uint64_t chain_records[256];
    uint64_t current_record;
    uint64_t parent_record;
    uint16_t parent_seq;
    long long family_base_offset;
    int chain_count = 0;
    int i;

    mft_catalog_chain_eval_reset(eval);
    if (eval == NULL ||
        entry == NULL ||
        !entry->has_name ||
        entry->name[0] == '\0') {
        return;
    }

    family_base_offset = entry->family_base_offset;
    current_record = (uint64_t)entry->record_number;
    parent_record = entry->parent_record;
    parent_seq = entry->parent_seq;
    chain_records[chain_count++] = current_record;

    while (chain_count < 256) {
        MftEntry *parent_entry = NULL;
        const MftI30NameEntry *parent_i30_entry = NULL;

        eval->depth = chain_count;
        if (current_record == 5U || parent_record == 5U) {
            eval->complete = 1;
            return;
        }

        if (parent_record == 0ULL ||
            parent_record == current_record ||
            parent_record > (uint64_t)INT_MAX) {
            eval->missing_parent = 1;
            eval->missing_parent_record = parent_record;
            if (parent_record == current_record ||
                parent_record > (uint64_t)INT_MAX) {
                eval->cycle = 1;
            }
            return;
        }

        for (i = 0; i < chain_count; i++) {
            if (chain_records[i] == parent_record) {
                eval->cycle = 1;
                eval->missing_parent_record = parent_record;
                return;
            }
        }

        parent_entry = find_entry_by_family_and_record(
            family_base_offset,
            (int)parent_record
        );
        if (parent_entry != NULL &&
            parent_entry->has_name &&
            parent_entry->name[0] != '\0') {
            mft_catalog_chain_eval_note_parent_seq(
                parent_seq,
                parent_entry->record_seq,
                eval
            );
            current_record = (uint64_t)parent_entry->record_number;
            parent_record = parent_entry->parent_record;
            parent_seq = parent_entry->parent_seq;
            chain_records[chain_count++] = current_record;
            continue;
        }

        if (i30_name_index_lookup(
                family_base_offset,
                (int)parent_record,
                &parent_i30_entry) &&
            parent_i30_entry != NULL &&
            parent_i30_entry->name[0] != '\0') {
            mft_catalog_chain_eval_note_parent_seq(
                parent_seq,
                parent_i30_entry->record_seq,
                eval
            );
            eval->used_i30_parent = 1;
            current_record = (uint64_t)parent_i30_entry->record_number;
            parent_record = parent_i30_entry->parent_record;
            parent_seq = parent_i30_entry->parent_seq;
            chain_records[chain_count++] = current_record;
            continue;
        }

        {
            MftParentBridgeRef bridge = {0};

            if (mft_find_sequence_checked_cross_family_parent(
                    family_base_offset,
                    parent_record,
                    parent_seq,
                    &bridge)) {
                eval->used_cross_family_parent = 1;
                if (bridge.kind == MFT_PARENT_BRIDGE_MFT &&
                    bridge.entry != NULL &&
                    bridge.entry->has_name &&
                    bridge.entry->name[0] != '\0') {
                    parent_entry = (MftEntry *)bridge.entry;
                    mft_catalog_chain_eval_note_parent_seq(
                        parent_seq,
                        parent_entry->record_seq,
                        eval
                    );
                    family_base_offset = parent_entry->family_base_offset;
                    current_record = (uint64_t)parent_entry->record_number;
                    parent_record = parent_entry->parent_record;
                    parent_seq = parent_entry->parent_seq;
                    chain_records[chain_count++] = current_record;
                    continue;
                }
                if (bridge.kind == MFT_PARENT_BRIDGE_I30 &&
                    bridge.i30_entry != NULL &&
                    bridge.i30_entry->name[0] != '\0') {
                    parent_i30_entry = bridge.i30_entry;
                    mft_catalog_chain_eval_note_parent_seq(
                        parent_seq,
                        parent_i30_entry->record_seq,
                        eval
                    );
                    eval->used_i30_parent = 1;
                    family_base_offset = parent_i30_entry->family_base_offset;
                    current_record = (uint64_t)parent_i30_entry->record_number;
                    parent_record = parent_i30_entry->parent_record;
                    parent_seq = parent_i30_entry->parent_seq;
                    chain_records[chain_count++] = current_record;
                    continue;
                }
            } else if (bridge.ambiguous) {
                eval->cross_family_parent_ambiguous = 1;
            }
        }

        eval->missing_parent = 1;
        eval->missing_parent_record = parent_record;
        return;
    }

    eval->too_deep = 1;
}

static void mft_catalog_eval_i30_chain(
    const MftI30NameEntry *entry,
    MftCatalogChainEval *eval
)
{
    uint64_t chain_records[256];
    uint64_t current_record;
    uint64_t parent_record;
    uint16_t parent_seq;
    long long family_base_offset;
    int chain_count = 0;
    int i;

    mft_catalog_chain_eval_reset(eval);
    if (eval == NULL ||
        entry == NULL ||
        !entry->in_use ||
        entry->name[0] == '\0') {
        return;
    }

    family_base_offset = entry->family_base_offset;
    current_record = (uint64_t)entry->record_number;
    parent_record = entry->parent_record;
    parent_seq = entry->parent_seq;
    chain_records[chain_count++] = current_record;

    while (chain_count < 256) {
        const MftI30NameEntry *parent_i30_entry = NULL;
        MftEntry *parent_entry = NULL;

        eval->depth = chain_count;
        if (current_record == 5U || parent_record == 5U) {
            eval->complete = 1;
            return;
        }

        if (parent_record == 0ULL ||
            parent_record == current_record ||
            parent_record > (uint64_t)INT_MAX) {
            eval->missing_parent = 1;
            eval->missing_parent_record = parent_record;
            if (parent_record == current_record ||
                parent_record > (uint64_t)INT_MAX) {
                eval->cycle = 1;
            }
            return;
        }

        for (i = 0; i < chain_count; i++) {
            if (chain_records[i] == parent_record) {
                eval->cycle = 1;
                eval->missing_parent_record = parent_record;
                return;
            }
        }

        if (i30_name_index_lookup(
                family_base_offset,
                (int)parent_record,
                &parent_i30_entry) &&
            parent_i30_entry != NULL &&
            parent_i30_entry->name[0] != '\0') {
            mft_catalog_chain_eval_note_parent_seq(
                parent_seq,
                parent_i30_entry->record_seq,
                eval
            );
            eval->used_i30_parent = 1;
            current_record = (uint64_t)parent_i30_entry->record_number;
            parent_record = parent_i30_entry->parent_record;
            parent_seq = parent_i30_entry->parent_seq;
            chain_records[chain_count++] = current_record;
            continue;
        }

        parent_entry = find_entry_by_family_and_record(
            family_base_offset,
            (int)parent_record
        );
        if (parent_entry != NULL &&
            parent_entry->has_name &&
            parent_entry->name[0] != '\0') {
            mft_catalog_chain_eval_note_parent_seq(
                parent_seq,
                parent_entry->record_seq,
                eval
            );
            current_record = (uint64_t)parent_entry->record_number;
            parent_record = parent_entry->parent_record;
            parent_seq = parent_entry->parent_seq;
            chain_records[chain_count++] = current_record;
            continue;
        }

        {
            MftParentBridgeRef bridge = {0};

            if (mft_find_sequence_checked_cross_family_parent(
                    family_base_offset,
                    parent_record,
                    parent_seq,
                    &bridge)) {
                eval->used_cross_family_parent = 1;
                if (bridge.kind == MFT_PARENT_BRIDGE_I30 &&
                    bridge.i30_entry != NULL &&
                    bridge.i30_entry->name[0] != '\0') {
                    parent_i30_entry = bridge.i30_entry;
                    mft_catalog_chain_eval_note_parent_seq(
                        parent_seq,
                        parent_i30_entry->record_seq,
                        eval
                    );
                    eval->used_i30_parent = 1;
                    family_base_offset = parent_i30_entry->family_base_offset;
                    current_record = (uint64_t)parent_i30_entry->record_number;
                    parent_record = parent_i30_entry->parent_record;
                    parent_seq = parent_i30_entry->parent_seq;
                    chain_records[chain_count++] = current_record;
                    continue;
                }
                if (bridge.kind == MFT_PARENT_BRIDGE_MFT &&
                    bridge.entry != NULL &&
                    bridge.entry->has_name &&
                    bridge.entry->name[0] != '\0') {
                    parent_entry = (MftEntry *)bridge.entry;
                    mft_catalog_chain_eval_note_parent_seq(
                        parent_seq,
                        parent_entry->record_seq,
                        eval
                    );
                    family_base_offset = parent_entry->family_base_offset;
                    current_record = (uint64_t)parent_entry->record_number;
                    parent_record = parent_entry->parent_record;
                    parent_seq = parent_entry->parent_seq;
                    chain_records[chain_count++] = current_record;
                    continue;
                }
            } else if (bridge.ambiguous) {
                eval->cross_family_parent_ambiguous = 1;
            }
        }

        eval->missing_parent = 1;
        eval->missing_parent_record = parent_record;
        return;
    }

    eval->too_deep = 1;
}

static const MftEntry *mft_catalog_find_entry_by_source_and_record(
    MftEntrySource source_kind,
    int record_number
)
{
    const MftEntry *fallback = NULL;
    size_t i;

    for (i = 0U; i < g_mft_entry_count; i++) {
        const MftEntry *entry = &g_mft_entries[i];

        if (entry->source_kind != source_kind ||
            entry->record_number != record_number) {
            continue;
        }
        if (entry->has_name && entry->name[0] != '\0') {
            return entry;
        }
        if (fallback == NULL) {
            fallback = entry;
        }
    }

    return fallback;
}

static int mft_catalog_core_records_match(
    const MftEntry *primary,
    const MftEntry *mirror
)
{
    if (primary == NULL || mirror == NULL) {
        return 0;
    }
    if (primary->record_seq != 0U &&
        mirror->record_seq != 0U &&
        primary->record_seq != mirror->record_seq) {
        return 0;
    }
    if (primary->parent_record != 0ULL &&
        mirror->parent_record != 0ULL &&
        primary->parent_record != mirror->parent_record) {
        return 0;
    }
    if (primary->has_name &&
        mirror->has_name &&
        primary->name[0] != '\0' &&
        mirror->name[0] != '\0' &&
        strcasecmp(primary->name, mirror->name) != 0) {
        return 0;
    }
    if (primary->flags != 0U &&
        mirror->flags != 0U &&
        (primary->flags & 0x0003U) != (mirror->flags & 0x0003U)) {
        return 0;
    }
    return 1;
}

static void mft_catalog_compare_primary_and_mirror(
    MftCatalogQualityStats *stats
)
{
    int record_number;

    if (stats == NULL) {
        return;
    }

    for (record_number = 0; record_number < 4; record_number++) {
        const MftEntry *primary =
            mft_catalog_find_entry_by_source_and_record(
                MFT_ENTRY_SOURCE_PRIMARY,
                record_number
            );
        const MftEntry *mirror =
            mft_catalog_find_entry_by_source_and_record(
                MFT_ENTRY_SOURCE_MIRROR,
                record_number
            );

        if (primary != NULL) {
            stats->mirror_critical_primary_seen++;
        } else {
            stats->mirror_critical_missing_primary++;
        }
        if (mirror != NULL) {
            stats->mirror_critical_mirror_seen++;
        } else {
            stats->mirror_critical_missing_mirror++;
        }
        if (primary == NULL || mirror == NULL) {
            continue;
        }

        stats->mirror_critical_compared++;
        if (mft_catalog_core_records_match(primary, mirror)) {
            stats->mirror_critical_agree++;
        } else {
            stats->mirror_critical_mismatch++;
        }
    }
}

static uint64_t mft_catalog_score_add(
    uint64_t current,
    size_t count,
    uint64_t weight
)
{
    uint64_t add;

    if (count == 0U || weight == 0ULL) {
        return current;
    }
    if ((uint64_t)count > UINT64_MAX / weight) {
        return UINT64_MAX;
    }
    add = (uint64_t)count * weight;
    if (current > UINT64_MAX - add) {
        return UINT64_MAX;
    }
    return current + add;
}

static const char *mft_catalog_quality_grade(
    const MftCatalogQualityStats *stats
)
{
    if (stats == NULL || stats->entries == 0U) {
        return "empty";
    }
    if (stats->complete_chains >= 1000U &&
        stats->root_record_present > 0U &&
        stats->users_roots > 0U &&
        stats->mirror_critical_mismatch == 0U) {
        return "strong";
    }
    if (stats->complete_chains >= 100U &&
        stats->root_record_present > 0U) {
        return "usable";
    }
    if (stats->complete_chains > 0U ||
        stats->i30_complete_chains > 0U) {
        return "thin";
    }
    return "weak";
}

static void mft_catalog_quality_finalize_scores(MftCatalogQualityStats *stats)
{
    if (stats == NULL) {
        return;
    }

    stats->primary_tree_score = 0ULL;
    stats->primary_tree_score =
        mft_catalog_score_add(stats->primary_tree_score, stats->root_record_present, 1000ULL);
    stats->primary_tree_score =
        mft_catalog_score_add(stats->primary_tree_score, stats->users_roots, 700ULL);
    stats->primary_tree_score =
        mft_catalog_score_add(stats->primary_tree_score, stats->root_children_named, 80ULL);
    stats->primary_tree_score =
        mft_catalog_score_add(stats->primary_tree_score, stats->complete_chains, 10ULL);
    stats->primary_tree_score =
        mft_catalog_score_add(stats->primary_tree_score, stats->complete_chains_seq_checked, 3ULL);
    stats->primary_tree_score =
        mft_catalog_score_add(stats->primary_tree_score, stats->i30_complete_chains, 3ULL);

    stats->mirror_check_score = 0ULL;
    stats->mirror_check_score =
        mft_catalog_score_add(stats->mirror_check_score, stats->mirror_critical_agree, 300ULL);
    stats->mirror_check_score =
        mft_catalog_score_add(stats->mirror_check_score, stats->mirror_critical_mirror_seen, 100ULL);
    if (stats->mirror_critical_mismatch > 0U) {
        uint64_t penalty =
            (uint64_t)stats->mirror_critical_mismatch * 500ULL;
        if (stats->mirror_check_score > penalty) {
            stats->mirror_check_score -= penalty;
        } else {
            stats->mirror_check_score = 0ULL;
        }
    }

    stats->combined_score = stats->primary_tree_score;
    if (stats->combined_score <= UINT64_MAX - stats->mirror_check_score) {
        stats->combined_score += stats->mirror_check_score;
    } else {
        stats->combined_score = UINT64_MAX;
    }
    stats->grade = mft_catalog_quality_grade(stats);
}

static int mft_catalog_quality_write_snapshot(
    const char *phase_label,
    const MftCatalogQualityStats *stats
)
{
    char path[1024];
    FILE *file;
    const char *phase =
        (phase_label != NULL && phase_label[0] != '\0')
            ? phase_label
            : "mft_catalog";

    if (stats == NULL) {
        return 0;
    }

    file = mft_open_append_log(
        path,
        sizeof(path),
        MFT_TREE_QUALITY_FILE_NAME,
        "updated_unix\tphase\tgrade\tcombined_score\tprimary_tree_score\tmirror_check_score\tentries\tnamed_entries\tdirectory_entries\tfile_entries\tntfs_metadata_entries\tprimary_entries\tmirror_entries\tsupplemental_entries\troot_record_present\troot_record_named\tmft_record_present\tmftmirr_record_present\troot_children_named\tusers_roots\tdirectories_with_i30_runs\trecord_seq_present\trecord_seq_missing\tcomplete_chains\tcomplete_chains_seq_checked\tpartial_chains\tmissing_parent_chains\tcycle_chains\ttoo_deep_chains\tseq_conflict_chains\tchains_using_i30_parent\tchains_using_cross_family_parent\tcross_family_parent_bridge_ambiguous\tprimary_complete_chains\tmirror_complete_chains\tsupplemental_complete_chains\ti30_names\ti30_complete_chains\ti30_partial_chains\ti30_seq_conflict_chains\tmirror_critical_primary_seen\tmirror_critical_mirror_seen\tmirror_critical_compared\tmirror_critical_agree\tmirror_critical_mismatch\tmirror_critical_missing_primary\tmirror_critical_missing_mirror\n",
        NULL,
        NULL
    );
    if (file == NULL) {
        return 0;
    }

    fprintf(
        file,
        "%llu\t%s\t%s\t%llu\t%llu\t%llu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\t%zu\n",
        (unsigned long long)time(NULL),
        phase,
        stats->grade != NULL ? stats->grade : "unknown",
        (unsigned long long)stats->combined_score,
        (unsigned long long)stats->primary_tree_score,
        (unsigned long long)stats->mirror_check_score,
        stats->entries,
        stats->named_entries,
        stats->directory_entries,
        stats->file_entries,
        stats->ntfs_metadata_entries,
        stats->primary_entries,
        stats->mirror_entries,
        stats->supplemental_entries,
        stats->root_record_present,
        stats->root_record_named,
        stats->mft_record_present,
        stats->mftmirr_record_present,
        stats->root_children_named,
        stats->users_roots,
        stats->directories_with_i30_runs,
        stats->record_seq_present,
        stats->record_seq_missing,
        stats->complete_chains,
        stats->complete_chains_seq_checked,
        stats->partial_chains,
        stats->missing_parent_chains,
        stats->cycle_chains,
        stats->too_deep_chains,
        stats->seq_conflict_chains,
        stats->chains_using_i30_parent,
        stats->chains_using_cross_family_parent,
        stats->cross_family_parent_bridge_ambiguous,
        stats->primary_complete_chains,
        stats->mirror_complete_chains,
        stats->supplemental_complete_chains,
        stats->i30_names,
        stats->i30_complete_chains,
        stats->i30_partial_chains,
        stats->i30_seq_conflict_chains,
        stats->mirror_critical_primary_seen,
        stats->mirror_critical_mirror_seen,
        stats->mirror_critical_compared,
        stats->mirror_critical_agree,
        stats->mirror_critical_mismatch,
        stats->mirror_critical_missing_primary,
        stats->mirror_critical_missing_mirror
    );

    if (fclose(file) != 0) {
        return 0;
    }
    return mft_apply_output_owner_to_path(path);
}

static void mft_current_view_collect(MftCurrentViewStats *stats)
{
    size_t i;

    if (stats == NULL) {
        return;
    }
    memset(stats, 0, sizeof(*stats));

    for (i = 0U; i < g_mft_entry_count; i++) {
        const MftEntry *entry = &g_mft_entries[i];
        MftCurrentViewChainEval eval;
        int supported_file = 0;

        if (mft_long_pass_interrupted(i)) {
            return;
        }

        stats->entries++;
        if (entry->source_kind != MFT_ENTRY_SOURCE_PRIMARY ||
            !entry_has_live_mft_record_flag(entry) ||
            entry_is_deleted_like(entry)) {
            continue;
        }

        stats->primary_live_entries++;
        if (entry->has_name && entry->name[0] != '\0') {
            stats->primary_live_named_entries++;
        }
        if (entry->flags & 0x0002U) {
            stats->primary_live_directories++;
        } else {
            stats->primary_live_files++;
            supported_file = extension_matches_requested_formats_local(
                entry_extension(entry)
            );
            if (supported_file) {
                stats->primary_live_supported_files++;
            }
        }

        if (!build_current_view_full_path_details_from_entry(
                entry,
                NULL,
                0U,
                &eval)) {
            if (eval.seq_conflict) {
                stats->seq_conflict_paths++;
            }
            if (eval.missing_parent) {
                stats->missing_parent_paths++;
            }
            if (eval.non_live_parent) {
                stats->non_live_parent_paths++;
            }
            if (eval.cycle) {
                stats->cycle_paths++;
            }
            if (eval.too_deep) {
                stats->too_deep_paths++;
            }
            continue;
        }

        stats->complete_paths++;
        if (eval.seq_checked) {
            stats->complete_paths_seq_checked++;
        } else {
            stats->complete_paths_seq_unknown++;
        }
        if (supported_file) {
            stats->supported_files_with_complete_path++;
        }
    }
}

static void mft_catalog_quality_collect(MftCatalogQualityStats *stats)
{
    size_t i;

    if (stats == NULL) {
        return;
    }
    memset(stats, 0, sizeof(*stats));

    for (i = 0U; i < g_mft_entry_count; i++) {
        const MftEntry *entry = &g_mft_entries[i];
        MftCatalogChainEval eval;

        if (mft_long_pass_interrupted(i)) {
            return;
        }

        stats->entries++;
        if (entry->has_name && entry->name[0] != '\0') {
            stats->named_entries++;
        }
        if (entry->flags & 0x0002U) {
            stats->directory_entries++;
        } else {
            stats->file_entries++;
        }
        if (entry_is_ntfs_metadata(entry)) {
            stats->ntfs_metadata_entries++;
        }
        switch (entry->source_kind) {
            case MFT_ENTRY_SOURCE_PRIMARY:
                stats->primary_entries++;
                break;
            case MFT_ENTRY_SOURCE_MIRROR:
                stats->mirror_entries++;
                break;
            case MFT_ENTRY_SOURCE_SUPPLEMENTAL:
                stats->supplemental_entries++;
                break;
            default:
                break;
        }
        if (entry->record_seq != 0U) {
            stats->record_seq_present++;
        } else {
            stats->record_seq_missing++;
        }
        if (entry->record_number == 0) {
            stats->mft_record_present = 1U;
        } else if (entry->record_number == 1) {
            stats->mftmirr_record_present = 1U;
        } else if (entry->record_number == 5) {
            stats->root_record_present = 1U;
            if (entry->has_name && entry->name[0] != '\0') {
                stats->root_record_named = 1U;
            }
        }
        if (entry->parent_record == 5ULL &&
            entry->has_name &&
            entry->name[0] != '\0') {
            stats->root_children_named++;
            if ((entry->flags & 0x0002U) &&
                name_is_user_root(entry->name)) {
                stats->users_roots++;
            }
        }
        if ((entry->flags & 0x0002U) &&
            entry->i30_run_extent_count > 0U) {
            stats->directories_with_i30_runs++;
        }

        mft_catalog_eval_entry_chain(entry, &eval);
        if (eval.complete) {
            stats->complete_chains++;
            if (eval.seq_checked && !eval.seq_conflict) {
                stats->complete_chains_seq_checked++;
            }
            switch (entry->source_kind) {
                case MFT_ENTRY_SOURCE_PRIMARY:
                    stats->primary_complete_chains++;
                    break;
                case MFT_ENTRY_SOURCE_MIRROR:
                    stats->mirror_complete_chains++;
                    break;
                case MFT_ENTRY_SOURCE_SUPPLEMENTAL:
                    stats->supplemental_complete_chains++;
                    break;
                default:
                    break;
            }
        } else if (entry->has_name && entry->name[0] != '\0') {
            stats->partial_chains++;
        }
        if (eval.missing_parent) {
            stats->missing_parent_chains++;
        }
        if (eval.cycle) {
            stats->cycle_chains++;
        }
        if (eval.too_deep) {
            stats->too_deep_chains++;
        }
        if (eval.seq_conflict) {
            stats->seq_conflict_chains++;
        }
        if (eval.used_i30_parent) {
            stats->chains_using_i30_parent++;
        }
        if (eval.used_cross_family_parent) {
            stats->chains_using_cross_family_parent++;
        }
        if (eval.cross_family_parent_ambiguous) {
            stats->cross_family_parent_bridge_ambiguous++;
        }
    }

    for (i = 0U; i < g_mft_i30_name_index_capacity; i++) {
        const MftI30NameEntry *entry = &g_mft_i30_name_index[i];
        MftCatalogChainEval eval;

        if (!entry->in_use || entry->name[0] == '\0') {
            continue;
        }
        stats->i30_names++;
        mft_catalog_eval_i30_chain(entry, &eval);
        if (eval.complete) {
            stats->i30_complete_chains++;
        } else {
            stats->i30_partial_chains++;
        }
        if (eval.seq_conflict) {
            stats->i30_seq_conflict_chains++;
        }
        if (eval.used_cross_family_parent) {
            stats->chains_using_cross_family_parent++;
        }
        if (eval.cross_family_parent_ambiguous) {
            stats->cross_family_parent_bridge_ambiguous++;
        }
    }

    mft_catalog_compare_primary_and_mirror(stats);
    mft_catalog_quality_finalize_scores(stats);
}

static int mft_catalog_quality_prepare_for_naming(
    const char *phase_label,
    int resolve_tree
)
{
    MftCatalogQualityStats stats;
    MftCurrentViewStats current_stats;
    const char *label =
        (phase_label != NULL && phase_label[0] != '\0')
            ? phase_label
            : "NTFS naming";
    double started_at = monotonic_seconds_local();

    if (g_mft_entry_count == 0U && g_mft_i30_name_index_count == 0U) {
        log_info(
            "%s MFT catalog quality check skipped because no MFT/I30 catalog is loaded yet",
            label
        );
        return 1;
    }

    log_set_working_activity("checking MFT tree quality");
    if (resolve_tree) {
        resolve_pending_tree_classes_and_log_relevant(1);
        if (app_stop_requested() || g_mft_memory_guard_tripped) {
            log_mft_abort_reason("MFT tree quality check");
            return 0;
        }
    }

    mft_catalog_quality_collect(&stats);
    if (app_stop_requested() || g_mft_memory_guard_tripped) {
        log_mft_abort_reason("MFT tree quality check");
        return 0;
    }
    (void)mft_catalog_quality_write_snapshot(label, &stats);
    mft_current_view_collect(&current_stats);
    if (app_stop_requested() || g_mft_memory_guard_tripped) {
        log_mft_abort_reason("MFT current-view check");
        return 0;
    }

    log_verbose(
        "%s MFT tree quality: grade=%s score=%llu entries=%zu named=%zu complete=%zu partial=%zu root=%zu users_roots=%zu i30=%zu i30_complete=%zu seq_ok_complete=%zu seq_conflict=%zu cross_family_bridges=%zu cross_family_ambiguous=%zu sources(primary=%zu mirror=%zu supplemental=%zu) mirror_check(compared=%zu agree=%zu mismatch=%zu missing_primary=%zu missing_mirror=%zu) time=%.2fs",
        label,
        stats.grade != NULL ? stats.grade : "unknown",
        (unsigned long long)stats.combined_score,
        stats.entries,
        stats.named_entries,
        stats.complete_chains,
        stats.partial_chains,
        stats.root_record_present,
        stats.users_roots,
        stats.i30_names,
        stats.i30_complete_chains,
        stats.complete_chains_seq_checked,
        stats.seq_conflict_chains + stats.i30_seq_conflict_chains,
        stats.chains_using_cross_family_parent,
        stats.cross_family_parent_bridge_ambiguous,
        stats.primary_entries,
        stats.mirror_entries,
        stats.supplemental_entries,
        stats.mirror_critical_compared,
        stats.mirror_critical_agree,
        stats.mirror_critical_mismatch,
        stats.mirror_critical_missing_primary,
        stats.mirror_critical_missing_mirror,
        monotonic_seconds_local() - started_at
    );

    log_verbose(
        "%s NTFS current-view anchors: primary_live=%zu files=%zu dirs=%zu supported_files=%zu complete=%zu supported_complete=%zu seq_checked=%zu seq_unknown=%zu blocked(seq=%zu missing=%zu non_live=%zu cycle=%zu deep=%zu)",
        label,
        current_stats.primary_live_entries,
        current_stats.primary_live_files,
        current_stats.primary_live_directories,
        current_stats.primary_live_supported_files,
        current_stats.complete_paths,
        current_stats.supported_files_with_complete_path,
        current_stats.complete_paths_seq_checked,
        current_stats.complete_paths_seq_unknown,
        current_stats.seq_conflict_paths,
        current_stats.missing_parent_paths,
        current_stats.non_live_parent_paths,
        current_stats.cycle_paths,
        current_stats.too_deep_paths
    );

    if (strcmp(stats.grade, "weak") == 0 ||
        strcmp(stats.grade, "empty") == 0) {
        log_info(
            "%s MFT tree quality is %s; naming will remain conservative and prefer exact/complete evidence over broad partial-tree guesses",
            label,
            stats.grade
        );
    }
    return 1;
}

static void build_full_path_from_entry(
    const MftEntry *entry,
    char *out,
    size_t out_size
)
{
    build_full_path_details_from_entry(entry, out, out_size, NULL, NULL);
}

static void mft_current_view_chain_eval_reset(MftCurrentViewChainEval *eval)
{
    if (eval != NULL) {
        memset(eval, 0, sizeof(*eval));
    }
}

static int entry_has_live_mft_record_flag(const MftEntry *entry)
{
    return entry != NULL && (entry->flags & 0x0001U) != 0U;
}

static int entry_is_primary_live_current_view_candidate(const MftEntry *entry)
{
    return entry != NULL &&
           entry->source_kind == MFT_ENTRY_SOURCE_PRIMARY &&
           entry_has_live_mft_record_flag(entry) &&
           entry->has_name &&
           entry->name[0] != '\0' &&
           !entry_is_ntfs_metadata(entry) &&
           !entry_is_deleted_like(entry);
}

static int current_view_parent_sequence_compatible(
    uint16_t expected_seq,
    uint16_t actual_seq,
    MftCurrentViewChainEval *eval
)
{
    if (expected_seq == 0U || actual_seq == 0U) {
        return 1;
    }
    if (eval != NULL) {
        eval->seq_checked = 1;
    }
    if (expected_seq != actual_seq) {
        if (eval != NULL) {
            eval->seq_conflict = 1;
        }
        return 0;
    }
    return 1;
}

static int build_current_view_full_path_details_from_entry(
    const MftEntry *entry,
    char *out,
    size_t out_size,
    MftCurrentViewChainEval *out_eval
)
{
    const char *chain_names[256];
    uint64_t chain_records[256];
    uint64_t current_record;
    uint64_t parent_record;
    uint16_t parent_seq;
    long long family_base_offset;
    int chain_count = 0;
    int complete = 0;
    int i;
    char temp[MFT_PATH_MAX] = {0};
    MftCurrentViewChainEval eval;

    mft_current_view_chain_eval_reset(&eval);
    if (out != NULL && out_size > 0U) {
        out[0] = '\0';
    }
    if (entry == NULL ||
        !entry_is_primary_live_current_view_candidate(entry)) {
        if (out_eval != NULL) {
            *out_eval = eval;
        }
        return 0;
    }

    family_base_offset = entry->family_base_offset;
    current_record = (uint64_t)entry->record_number;
    parent_record = entry->parent_record;
    parent_seq = entry->parent_seq;

    chain_names[chain_count] = entry->name;
    chain_records[chain_count] = current_record;
    chain_count++;

    while (chain_count < 256) {
        MftEntry *parent_entry = NULL;

        eval.depth = chain_count;
        if (current_record == 5U) {
            complete = 1;
            break;
        }

        if (parent_record == 5ULL) {
            parent_entry = find_entry_by_family_and_record(family_base_offset, 5);
            if (parent_entry != NULL &&
                !current_view_parent_sequence_compatible(
                    parent_seq,
                    parent_entry->record_seq,
                    &eval)) {
                break;
            }
            complete = 1;
            break;
        }

        if (parent_record == 0ULL ||
            parent_record == current_record ||
            parent_record > (uint64_t)INT_MAX) {
            eval.missing_parent = 1;
            eval.missing_parent_record = parent_record;
            if (parent_record == current_record ||
                parent_record > (uint64_t)INT_MAX) {
                eval.cycle = 1;
            }
            break;
        }

        for (i = 0; i < chain_count; i++) {
            if (chain_records[i] == parent_record) {
                eval.cycle = 1;
                eval.missing_parent_record = parent_record;
                break;
            }
        }
        if (eval.cycle) {
            break;
        }

        parent_entry = find_entry_by_family_and_record(
            family_base_offset,
            (int)parent_record
        );
        if (parent_entry == NULL ||
            !entry_is_primary_live_current_view_candidate(parent_entry) ||
            (parent_entry->flags & 0x0002U) == 0U) {
            if (parent_entry == NULL) {
                eval.missing_parent = 1;
                eval.missing_parent_record = parent_record;
            } else {
                eval.non_live_parent = 1;
                eval.missing_parent_record = parent_record;
            }
            break;
        }

        if (!current_view_parent_sequence_compatible(
                parent_seq,
                parent_entry->record_seq,
                &eval)) {
            eval.missing_parent_record = parent_record;
            break;
        }

        chain_names[chain_count] = parent_entry->name;
        current_record = (uint64_t)parent_entry->record_number;
        parent_record = parent_entry->parent_record;
        parent_seq = parent_entry->parent_seq;
        chain_records[chain_count] = current_record;
        chain_count++;
    }

    if (chain_count >= 256 && !complete) {
        eval.too_deep = 1;
    }
    eval.complete = complete;

    if (complete) {
        snprintf(temp, sizeof(temp), "\\");
        for (i = chain_count - 1; i >= 0; i--) {
            if (chain_names[i] == NULL ||
                chain_names[i][0] == '\0' ||
                chain_records[i] == 5U) {
                continue;
            }
            if (strlen(temp) > 1U) {
                strncat(temp, "\\", sizeof(temp) - strlen(temp) - 1U);
            }
            strncat(temp, chain_names[i], sizeof(temp) - strlen(temp) - 1U);
        }
        if (out != NULL && out_size > 0U) {
            snprintf(out, out_size, "%s", temp);
        }
    }

    if (out_eval != NULL) {
        *out_eval = eval;
    }
    return complete;
}

static int build_full_tree_contextual_path_from_entry_with_status(
    const MftEntry *entry,
    char *out,
    size_t out_size,
    int *out_complete
)
{
    char full_path[MFT_PATH_MAX];
    int complete = 0;

    if (out_complete != NULL) {
        *out_complete = 0;
    }

    if (entry == NULL || out == NULL || out_size == 0) {
        return 0;
    }

    if (build_current_view_full_path_details_from_entry(
            entry,
            full_path,
            sizeof(full_path),
            NULL)) {
        complete = 1;
    } else {
        build_full_path_details_from_entry(
            entry,
            full_path,
            sizeof(full_path),
            &complete,
            NULL
        );
    }
    if (full_path[0] == '\0') {
        return 0;
    }

    if (!resolve_full_tree_path_from_mft(out, out_size, full_path)) {
        return 0;
    }

    if (out_complete != NULL) {
        *out_complete = complete;
    }

    return 1;
}

static int entry_resolves_contextual_output_path_for_naming_with_status(
    const MftEntry *entry,
    char *out,
    size_t out_size,
    int *out_complete
)
{
    if (out_complete != NULL) {
        *out_complete = 0;
    }
    if (entry == NULL || out == NULL || out_size == 0U) {
        return 0;
    }

    if (g_contextual_output_mode == MFT_CONTEXTUAL_OUTPUT_FULL_TREE) {
        return build_full_tree_contextual_path_from_entry_with_status(
            entry,
            out,
            out_size,
            out_complete
        );
    }

    return entry_resolves_contextual_output_path_with_status(
        entry,
        out,
        out_size,
        out_complete
    );
}

static int build_full_tree_contextual_path_from_i30_entry_with_status(
    const MftI30NameEntry *entry,
    char *out,
    size_t out_size,
    int *out_complete
)
{
    char full_path[MFT_PATH_MAX];
    int complete = 0;

    if (out_complete != NULL) {
        *out_complete = 0;
    }

    if (entry == NULL || out == NULL || out_size == 0U) {
        return 0;
    }

    build_full_path_details_from_i30_entry(
        entry,
        full_path,
        sizeof(full_path),
        &complete,
        NULL
    );
    if (full_path[0] == '\0') {
        return 0;
    }

    if (!resolve_full_tree_path_from_mft(out, out_size, full_path)) {
        return 0;
    }

    if (out_complete != NULL) {
        *out_complete = complete;
    }

    return 1;
}

typedef struct {
    int found;
    int ambiguous;
    int score;
    char path[MFT_PATH_MAX];
} MftExactPartialPromotionChoice;

typedef struct {
    int valid;
    const char *name;
    uint8_t name_namespace;
    uint64_t parent_record;
    uint16_t parent_seq;
    long long family_base_offset;
} MftExactPartialWalkParent;

static int record_seq_matches_exact_parent_ref(
    uint16_t expected_seq,
    uint16_t actual_seq
)
{
    return mft_parent_seq_exact_match(expected_seq, actual_seq);
}

static int exact_partial_promotion_path_score(
    const char *path,
    int source_is_i30
)
{
    int score = 1000 + contextual_path_depth_local(path) * 30;

    if (path_looks_userish_ci(path)) {
        score += g_contextual_output_mode == MFT_CONTEXTUAL_OUTPUT_FULL_TREE
            ? 120
            : 300;
    }
    if (g_contextual_output_mode != MFT_CONTEXTUAL_OUTPUT_FULL_TREE &&
        path_looks_systemish_ci(path)) {
        score -= 500;
    }
    if (source_is_i30) {
        score += 20;
    }

    return score;
}

static void exact_partial_promotion_consider_path(
    MftExactPartialPromotionChoice *choice,
    const char *path,
    int source_is_i30
)
{
    const int score_margin = 80;
    int score;

    if (choice == NULL || path == NULL || path[0] == '\0') {
        return;
    }

    score = exact_partial_promotion_path_score(path, source_is_i30);
    if (!choice->found) {
        choice->found = 1;
        choice->ambiguous = 0;
        choice->score = score;
        snprintf(choice->path, sizeof(choice->path), "%s", path);
        return;
    }

    if (strcasecmp(choice->path, path) == 0) {
        if (score > choice->score) {
            choice->score = score;
            snprintf(choice->path, sizeof(choice->path), "%s", path);
        }
        return;
    }

    if (score > choice->score + score_margin) {
        choice->ambiguous = 0;
        choice->score = score;
        snprintf(choice->path, sizeof(choice->path), "%s", path);
        return;
    }

    if (choice->score > score + score_margin) {
        return;
    }

    choice->ambiguous = 1;
}

static void exact_partial_promotion_collect_parent_paths(
    long long family_base_offset,
    uint64_t parent_record,
    uint16_t expected_parent_seq,
    MftExactPartialPromotionChoice *choice,
    int *out_seq_blocked
)
{
    MftEntry *parent_entry = NULL;
    const MftI30NameEntry *parent_i30 = NULL;
    char contextual_path[MFT_PATH_MAX];
    int complete = 0;

    if (out_seq_blocked != NULL) {
        *out_seq_blocked = 0;
    }
    if (choice == NULL ||
        !directory_key_is_usable(family_base_offset, parent_record) ||
        expected_parent_seq == 0U) {
        if (out_seq_blocked != NULL) {
            *out_seq_blocked = 1;
        }
        return;
    }

    parent_entry = find_entry_by_family_and_record(
        family_base_offset,
        (int)parent_record
    );
    if (parent_entry != NULL &&
        parent_entry->has_name &&
        parent_entry->name[0] != '\0' &&
        !entry_is_ntfs_metadata(parent_entry)) {
        if (record_seq_matches_exact_parent_ref(
                expected_parent_seq,
                parent_entry->record_seq)) {
            if (build_full_tree_contextual_path_from_entry_with_status(
                    parent_entry,
                    contextual_path,
                    sizeof(contextual_path),
                    &complete) &&
                complete) {
                exact_partial_promotion_consider_path(choice, contextual_path, 0);
            }
        } else if (out_seq_blocked != NULL) {
            *out_seq_blocked = 1;
        }
    }

    if (i30_name_index_lookup(
            family_base_offset,
            (int)parent_record,
            &parent_i30) &&
        parent_i30 != NULL &&
        parent_i30->name[0] != '\0') {
        if (record_seq_matches_exact_parent_ref(
                expected_parent_seq,
                parent_i30->record_seq)) {
            if (build_full_tree_contextual_path_from_i30_entry_with_status(
                    parent_i30,
                    contextual_path,
                    sizeof(contextual_path),
                    &complete) &&
                complete) {
                exact_partial_promotion_consider_path(choice, contextual_path, 1);
            }
        } else if (out_seq_blocked != NULL) {
            *out_seq_blocked = 1;
        }
    }

    {
        MftParentBridgeRef bridge = {0};

        if (mft_find_sequence_checked_cross_family_parent(
                family_base_offset,
                parent_record,
                expected_parent_seq,
                &bridge)) {
            if (bridge.kind == MFT_PARENT_BRIDGE_MFT &&
                bridge.entry != NULL &&
                bridge.entry->has_name &&
                bridge.entry->name[0] != '\0' &&
                !entry_is_ntfs_metadata(bridge.entry)) {
                if (build_full_tree_contextual_path_from_entry_with_status(
                        bridge.entry,
                        contextual_path,
                        sizeof(contextual_path),
                        &complete) &&
                    complete) {
                    exact_partial_promotion_consider_path(choice, contextual_path, 0);
                }
            } else if (bridge.kind == MFT_PARENT_BRIDGE_I30 &&
                       bridge.i30_entry != NULL &&
                       bridge.i30_entry->name[0] != '\0') {
                if (build_full_tree_contextual_path_from_i30_entry_with_status(
                        bridge.i30_entry,
                        contextual_path,
                        sizeof(contextual_path),
                        &complete) &&
                    complete) {
                    exact_partial_promotion_consider_path(choice, contextual_path, 1);
                }
            }
        } else if (bridge.ambiguous && out_seq_blocked != NULL) {
            *out_seq_blocked = 1;
        }
    }
}

static int exact_partial_promotion_choose_walk_parent(
    long long family_base_offset,
    uint64_t parent_record,
    uint16_t expected_parent_seq,
    MftExactPartialWalkParent *out_parent,
    int *out_seq_blocked
)
{
    MftEntry *parent_entry = NULL;
    const MftI30NameEntry *parent_i30 = NULL;
    int mft_ok = 0;
    int i30_ok = 0;

    if (out_parent != NULL) {
        memset(out_parent, 0, sizeof(*out_parent));
    }
    if (out_seq_blocked != NULL) {
        *out_seq_blocked = 0;
    }
    if (out_parent == NULL ||
        !directory_key_is_usable(family_base_offset, parent_record) ||
        expected_parent_seq == 0U) {
        if (out_seq_blocked != NULL) {
            *out_seq_blocked = 1;
        }
        return 0;
    }

    parent_entry = find_entry_by_family_and_record(
        family_base_offset,
        (int)parent_record
    );
    if (parent_entry != NULL &&
        parent_entry->has_name &&
        parent_entry->name[0] != '\0' &&
        !entry_is_ntfs_metadata(parent_entry)) {
        if (record_seq_matches_exact_parent_ref(
                expected_parent_seq,
                parent_entry->record_seq)) {
            mft_ok = 1;
        } else if (out_seq_blocked != NULL) {
            *out_seq_blocked = 1;
        }
    }

    if (i30_name_index_lookup(
            family_base_offset,
            (int)parent_record,
            &parent_i30) &&
        parent_i30 != NULL &&
        parent_i30->name[0] != '\0') {
        if (record_seq_matches_exact_parent_ref(
                expected_parent_seq,
                parent_i30->record_seq)) {
            i30_ok = 1;
        } else if (out_seq_blocked != NULL) {
            *out_seq_blocked = 1;
        }
    }

    if (!mft_ok && !i30_ok) {
        MftParentBridgeRef bridge = {0};

        if (mft_find_sequence_checked_cross_family_parent(
                family_base_offset,
                parent_record,
                expected_parent_seq,
                &bridge)) {
            if (bridge.kind == MFT_PARENT_BRIDGE_MFT &&
                bridge.entry != NULL &&
                bridge.entry->has_name &&
                bridge.entry->name[0] != '\0' &&
                !entry_is_ntfs_metadata(bridge.entry)) {
                out_parent->valid = 1;
                out_parent->name = bridge.entry->name;
                out_parent->name_namespace = bridge.entry->name_namespace;
                out_parent->parent_record = bridge.entry->parent_record;
                out_parent->parent_seq = bridge.entry->parent_seq;
                out_parent->family_base_offset = bridge.entry->family_base_offset;
                if (out_seq_blocked != NULL) {
                    *out_seq_blocked = 0;
                }
                return 1;
            }
            if (bridge.kind == MFT_PARENT_BRIDGE_I30 &&
                bridge.i30_entry != NULL &&
                bridge.i30_entry->name[0] != '\0') {
                out_parent->valid = 1;
                out_parent->name = bridge.i30_entry->name;
                out_parent->name_namespace = bridge.i30_entry->name_namespace;
                out_parent->parent_record = bridge.i30_entry->parent_record;
                out_parent->parent_seq = bridge.i30_entry->parent_seq;
                out_parent->family_base_offset = bridge.i30_entry->family_base_offset;
                if (out_seq_blocked != NULL) {
                    *out_seq_blocked = 0;
                }
                return 1;
            }
        }
        return 0;
    }

    if (i30_ok &&
        (!mft_ok ||
         mft_compare_name_preference(
             parent_i30->name,
             parent_i30->name_namespace,
             parent_entry->name,
             parent_entry->name_namespace) > 0)) {
        out_parent->valid = 1;
        out_parent->name = parent_i30->name;
        out_parent->name_namespace = parent_i30->name_namespace;
        out_parent->parent_record = parent_i30->parent_record;
        out_parent->parent_seq = parent_i30->parent_seq;
        out_parent->family_base_offset = parent_i30->family_base_offset;
        return 1;
    }

    out_parent->valid = 1;
    out_parent->name = parent_entry->name;
    out_parent->name_namespace = parent_entry->name_namespace;
    out_parent->parent_record = parent_entry->parent_record;
    out_parent->parent_seq = parent_entry->parent_seq;
    out_parent->family_base_offset = parent_entry->family_base_offset;
    return 1;
}

static int build_promoted_exact_partial_joined_path(
    const char *parent_path,
    const char *const *suffix_names,
    int suffix_count,
    char *out,
    size_t out_size
)
{
    size_t len;
    int i;

    if (parent_path == NULL ||
        parent_path[0] == '\0' ||
        suffix_names == NULL ||
        suffix_count <= 0 ||
        out == NULL ||
        out_size == 0U) {
        return 0;
    }

    if (snprintf(out, out_size, "%s", parent_path) >= (int)out_size) {
        return 0;
    }
    len = strlen(out);
    while (len > 1U && out[len - 1U] == '/') {
        out[len - 1U] = '\0';
        len--;
    }

    for (i = suffix_count - 1; i >= 0; i--) {
        size_t name_len;

        if (suffix_names[i] == NULL || suffix_names[i][0] == '\0') {
            return 0;
        }
        name_len = strlen(suffix_names[i]);
        if (len + 1U + name_len + 1U > out_size) {
            return 0;
        }
        if (len == 0U || out[len - 1U] != '/') {
            out[len++] = '/';
            out[len] = '\0';
        }
        memcpy(out + len, suffix_names[i], name_len + 1U);
        len += name_len;
    }

    return 1;
}

static int build_promoted_exact_partial_context_path(
    const MftEntry *entry,
    const char *extension,
    char *out,
    size_t out_size
)
{
    const char *suffix_names[256];
    uint64_t suffix_records[256];
    int suffix_count = 0;
    uint64_t parent_record;
    uint16_t parent_seq;
    long long family_base_offset;
    int saw_seq_blocked = 0;
    int i;

    if (out != NULL && out_size > 0U) {
        out[0] = '\0';
    }
    if (entry == NULL ||
        extension == NULL ||
        out == NULL ||
        out_size == 0U ||
        !entry->has_name ||
        entry->name[0] == '\0' ||
        entry_is_ntfs_metadata(entry)) {
        return 0;
    }

    g_mft_name_live_stats.exact_partial_promotion_candidates++;

    family_base_offset = entry->family_base_offset;
    parent_record = entry->parent_record;
    parent_seq = entry->parent_seq;
    suffix_names[suffix_count] = entry->name;
    suffix_records[suffix_count] = (uint64_t)entry->record_number;
    suffix_count++;

    while (suffix_count < 256) {
        MftExactPartialPromotionChoice choice = {0};
        MftExactPartialWalkParent walk_parent = {0};
        int seq_blocked = 0;

        if (parent_record == 0ULL ||
            parent_record == 5ULL ||
            parent_record > (uint64_t)INT_MAX) {
            if (parent_seq == 0U) {
                g_mft_name_live_stats.exact_partial_promotion_seq_blocked++;
            }
            return 0;
        }

        for (i = 0; i < suffix_count; i++) {
            if (suffix_records[i] == parent_record) {
                return 0;
            }
        }

        exact_partial_promotion_collect_parent_paths(
            family_base_offset,
            parent_record,
            parent_seq,
            &choice,
            &seq_blocked
        );
        if (seq_blocked) {
            saw_seq_blocked = 1;
        }
        if (choice.found) {
            if (choice.ambiguous) {
                g_mft_name_live_stats.exact_partial_promotion_ambiguous++;
                return 0;
            }
            if (build_promoted_exact_partial_joined_path(
                    choice.path,
                    suffix_names,
                    suffix_count,
                    out,
                    out_size) &&
                contextual_path_is_usable_for_recovered_extension(out, extension)) {
                g_mft_name_live_stats.exact_partial_promotions++;
                return 1;
            }
            return 0;
        }

        seq_blocked = 0;
        if (!exact_partial_promotion_choose_walk_parent(
                family_base_offset,
                parent_record,
                parent_seq,
                &walk_parent,
                &seq_blocked) ||
            !walk_parent.valid ||
            walk_parent.name == NULL ||
            walk_parent.name[0] == '\0') {
            if (seq_blocked) {
                saw_seq_blocked = 1;
            }
            if (saw_seq_blocked || parent_seq == 0U) {
                g_mft_name_live_stats.exact_partial_promotion_seq_blocked++;
            }
            return 0;
        }
        if (seq_blocked) {
            saw_seq_blocked = 1;
        }

        suffix_names[suffix_count] = walk_parent.name;
        suffix_records[suffix_count] = parent_record;
        suffix_count++;
        family_base_offset = walk_parent.family_base_offset;
        parent_record = walk_parent.parent_record;
        parent_seq = walk_parent.parent_seq;
    }

    return 0;
}

static const char *mft_tree_class_label(MftTreeClass tree_class)
{
    switch (tree_class) {
        case MFT_TREE_ROOT:
            return "root";
        case MFT_TREE_USERS:
            return "users";
        case MFT_TREE_SYSTEM:
            return "system";
        case MFT_TREE_OTHER_ROOT:
            return "other-root";
        case MFT_TREE_ORPHAN:
            return "orphan";
        case MFT_TREE_PENDING:
            return "pending";
        case MFT_TREE_UNKNOWN:
        default:
            return "unknown";
    }
}

static void append_name_candidate_source_label(
    char *out,
    size_t out_size,
    const char *label
)
{
    if (out == NULL || out_size == 0U || label == NULL || label[0] == '\0') {
        return;
    }

    if (out[0] != '\0') {
        strncat(out, "+", out_size - strlen(out) - 1U);
    }
    strncat(out, label, out_size - strlen(out) - 1U);
}

static int should_emit_name_candidate_sources(
    const MftEntry *entry,
    const MftI30NameEntry *i30_entry
)
{
    if (entry != NULL &&
        (entry->has_name ||
         entry->has_data ||
         entry->i30_run_extent_count > 0U ||
         entry->i30_index_block_size > 0U)) {
        return 1;
    }

    return i30_entry != NULL && i30_entry->name[0] != '\0';
}

static void initialize_name_candidate_row(
    const MftEntry *entry,
    const MftI30NameEntry *i30_entry,
    MftNameCandidateRow *out_row
)
{
    if (out_row == NULL) {
        return;
    }

    memset(out_row, 0, sizeof(*out_row));
    out_row->preferred_name_origin = "";
    out_row->path_origin = "";
    out_row->mft_source_label = "";
    out_row->tree_class_label = "unknown";
    out_row->abs_offset = -1LL;

    if (entry != NULL) {
        out_row->family_base_offset = entry->family_base_offset;
        out_row->volume_serial = entry->volume_serial;
        out_row->volume_start = entry->volume_start;
        out_row->record_number = entry->record_number;
        out_row->record_seq = entry->record_seq;
        out_row->has_mft = 1;
        out_row->ntfs_metadata = entry_is_ntfs_metadata(entry) ? 1 : 0;
        out_row->mft_source_label =
            mft_name_trace_origin_label_from_source_kind(entry->source_kind);
        out_row->tree_class_label = mft_tree_class_label(entry->tree_class);
        switch (entry->source_kind) {
            case MFT_ENTRY_SOURCE_PRIMARY:
                out_row->source_mask |= MFT_NAME_CANDIDATE_SOURCE_PRIMARY;
                append_name_candidate_source_label(
                    out_row->source_labels,
                    sizeof(out_row->source_labels),
                    "mft-primary"
                );
                break;
            case MFT_ENTRY_SOURCE_MIRROR:
                out_row->source_mask |= MFT_NAME_CANDIDATE_SOURCE_MIRROR;
                append_name_candidate_source_label(
                    out_row->source_labels,
                    sizeof(out_row->source_labels),
                    "mft-mirror"
                );
                break;
            case MFT_ENTRY_SOURCE_SUPPLEMENTAL:
            default:
                out_row->source_mask |= MFT_NAME_CANDIDATE_SOURCE_SUPPLEMENTAL;
                append_name_candidate_source_label(
                    out_row->source_labels,
                    sizeof(out_row->source_labels),
                    "mft-supplemental"
                );
                break;
        }
    } else if (i30_entry != NULL) {
        out_row->family_base_offset = i30_entry->family_base_offset;
        out_row->volume_serial = i30_entry->volume_serial;
        out_row->volume_start = i30_entry->volume_start;
        out_row->record_number = i30_entry->record_number;
        out_row->record_seq = i30_entry->record_seq;
    }

    if (i30_entry != NULL) {
        uint8_t source_flags = i30_entry->source_flags;

        if (out_row->volume_serial == 0ULL) {
            out_row->volume_serial = i30_entry->volume_serial;
        }
        if (out_row->volume_start == 0LL) {
            out_row->volume_start = i30_entry->volume_start;
        }
        if (source_flags == 0U) {
            source_flags = MFT_NAME_CATALOG_SOURCE_I30;
        }
        if (out_row->record_seq == 0U) {
            out_row->record_seq = i30_entry->record_seq;
        }
        if ((source_flags & MFT_NAME_CATALOG_SOURCE_I30) != 0U) {
            out_row->has_i30 = 1;
            out_row->source_mask |= MFT_NAME_CANDIDATE_SOURCE_I30;
            append_name_candidate_source_label(
                out_row->source_labels,
                sizeof(out_row->source_labels),
                "i30"
            );
        }
        if ((source_flags & MFT_NAME_CATALOG_SOURCE_USN) != 0U) {
            out_row->has_usn = 1;
            out_row->source_mask |= MFT_NAME_CANDIDATE_SOURCE_USN;
            append_name_candidate_source_label(
                out_row->source_labels,
                sizeof(out_row->source_labels),
                "usn"
            );
        }
    }
    if (out_row->volume_serial == 0ULL) {
        out_row->volume_serial = mft_current_volume_serial_local();
    }
    if (out_row->volume_start == 0LL && !g_direct_mft_source) {
        out_row->volume_start = mft_current_volume_start_local();
    }
}

static void apply_name_candidate_parent_fields(
    const MftEntry *entry,
    const MftI30NameEntry *i30_entry,
    MftNameCandidateRow *row
)
{
    if (row == NULL) {
        return;
    }

    if (entry != NULL &&
        entry->parent_record > 0U &&
        entry->parent_record != UINT64_MAX) {
        row->parent_record = entry->parent_record;
        row->parent_seq = entry->parent_seq;
    }

    if (row->parent_record == 0U &&
        i30_entry != NULL &&
        i30_entry->parent_record > 0U) {
        row->parent_record = i30_entry->parent_record;
        row->parent_seq = i30_entry->parent_seq;
    }
}

static void apply_name_candidate_name_fields(
    const MftEntry *entry,
    const MftI30NameEntry *i30_entry,
    MftNameCandidateRow *row
)
{
    if (row == NULL) {
        return;
    }

    if (entry != NULL && entry->has_name && entry->name[0] != '\0') {
        snprintf(row->name, sizeof(row->name), "%s", entry->name);
        row->name_namespace = entry->name_namespace;
        row->has_name = 1;
        row->preferred_name_origin = "mft";
    }

    if (i30_entry != NULL && i30_entry->name[0] != '\0') {
        const char *catalog_origin =
            name_catalog_source_label_local(i30_entry->source_flags);

        if (!row->has_name) {
            snprintf(row->name, sizeof(row->name), "%s", i30_entry->name);
            row->name_namespace = i30_entry->name_namespace;
            row->has_name = 1;
            row->preferred_name_origin = catalog_origin;
        } else if (name_extension_matches_recovery_preference_local(i30_entry->name) &&
                   !name_extension_matches_recovery_preference_local(row->name)) {
            snprintf(row->name, sizeof(row->name), "%s", i30_entry->name);
            row->name_namespace = i30_entry->name_namespace;
            row->preferred_name_origin = catalog_origin;
        } else if (mft_compare_name_preference(
                       i30_entry->name,
                       i30_entry->name_namespace,
                       row->name,
                       row->name_namespace) > 0) {
            snprintf(row->name, sizeof(row->name), "%s", i30_entry->name);
            row->name_namespace = i30_entry->name_namespace;
            row->preferred_name_origin = catalog_origin;
        } else if (entry != NULL && strcmp(row->name, i30_entry->name) == 0) {
            row->preferred_name_origin =
                (i30_entry->source_flags & MFT_NAME_CATALOG_SOURCE_USN) != 0U
                    ? "mft+catalog"
                    : "mft+i30";
        }
    }
}

static int name_candidate_row_prefers_i30_path_local(
    const MftNameCandidateRow *row
)
{
    return row != NULL &&
           row->preferred_name_origin != NULL &&
           (strcmp(row->preferred_name_origin, "i30") == 0 ||
            strcmp(row->preferred_name_origin, "i30+usn") == 0);
}

static void apply_name_candidate_time_and_size_fields(
    const MftEntry *entry,
    const MftI30NameEntry *i30_entry,
    MftNameCandidateRow *row
)
{
    if (row == NULL) {
        return;
    }

    if (entry != NULL) {
        long long entry_abs_offset =
            mft_entry_effective_abs_offset_or_raw_local(entry);

        row->created_filetime = entry->created_filetime;
        row->created_unix = entry->created_unix;
        row->data_size = entry->data_size > 0ULL
            ? entry->data_size
            : entry->valid_data_size;
        row->allocated_size = entry->allocated_size;
        row->has_data = entry->has_data ? 1 : 0;
        row->is_resident = entry->is_resident ? 1 : 0;
        row->abs_offset = entry_abs_offset;
        row->run_extent_count = entry->run_extent_count;
        row->i30_run_extent_count = entry->i30_run_extent_count;
        row->direct_data_anchor =
            entry->has_data && !entry->is_resident && entry_abs_offset >= 0 ? 1 : 0;
    }

    if (row->created_filetime == 0ULL &&
        i30_entry != NULL &&
        i30_entry->created_filetime != 0ULL) {
        row->created_filetime = i30_entry->created_filetime;
        row->created_unix = (time_t)filetime_to_unix_seconds(
            i30_entry->created_filetime
        );
    }
    if (row->data_size == 0ULL && i30_entry != NULL) {
        row->data_size = i30_entry->data_size;
    }
    if (row->allocated_size == 0ULL && i30_entry != NULL) {
        row->allocated_size = i30_entry->allocated_size;
    }
}

static void apply_name_candidate_path_fields(
    const MftEntry *entry,
    const MftI30NameEntry *i30_entry,
    MftNameCandidateRow *row
)
{
    char mft_path[MFT_PATH_MAX] = "";
    char i30_path[MFT_PATH_MAX] = "";
    int mft_complete = 0;
    int i30_complete = 0;
    int mft_missing_parent = -1;
    uint64_t i30_missing_parent = 0ULL;
    int use_i30_path = 0;
    int mft_current_path = 0;

    if (row == NULL) {
        return;
    }

    if (entry != NULL) {
        if (build_current_view_full_path_details_from_entry(
                entry,
                mft_path,
                sizeof(mft_path),
                NULL)) {
            mft_complete = 1;
            mft_missing_parent = -1;
            mft_current_path = 1;
        } else {
            build_full_path_details_from_entry(
                entry,
                mft_path,
                sizeof(mft_path),
                &mft_complete,
                &mft_missing_parent
            );
        }
    }

    if (i30_entry != NULL) {
        build_full_path_details_from_i30_entry(
            i30_entry,
            i30_path,
            sizeof(i30_path),
            &i30_complete,
            &i30_missing_parent
        );
    }

    if (mft_path[0] == '\0' && i30_path[0] == '\0') {
        return;
    }

    if (mft_path[0] == '\0') {
        use_i30_path = 1;
    } else if (i30_path[0] == '\0') {
        use_i30_path = 0;
    } else if (name_candidate_row_prefers_i30_path_local(row)) {
        use_i30_path = 1;
    } else if (mft_current_path && mft_complete) {
        use_i30_path = 0;
    } else if (mft_complete != i30_complete) {
        use_i30_path = i30_complete ? 1 : 0;
    } else if (contextual_path_depth_local(i30_path) >
               contextual_path_depth_local(mft_path)) {
        use_i30_path = 1;
    }

    if (use_i30_path) {
        snprintf(row->path, sizeof(row->path), "%s", i30_path);
        row->path_origin =
            (i30_entry != NULL &&
             (i30_entry->source_flags & MFT_NAME_CATALOG_SOURCE_USN) != 0U &&
             (i30_entry->source_flags & MFT_NAME_CATALOG_SOURCE_I30) == 0U)
                ? "usn"
                : "i30";
        row->path_complete = i30_complete;
        row->path_missing_parent = (unsigned long long)i30_missing_parent;
    } else {
        snprintf(row->path, sizeof(row->path), "%s", mft_path);
        row->path_origin = mft_current_path ? "mft-current" : "mft";
        row->path_complete = mft_complete;
        row->path_missing_parent =
            mft_missing_parent >= 0 ? (unsigned long long)mft_missing_parent : 0ULL;
    }
}

static int build_name_candidate_row_from_sources_with_path_policy(
    const MftEntry *entry,
    const MftI30NameEntry *i30_entry,
    MftNameCandidateRow *out_row,
    int include_path
)
{
    if (!should_emit_name_candidate_sources(entry, i30_entry) ||
        out_row == NULL) {
        return 0;
    }

    initialize_name_candidate_row(entry, i30_entry, out_row);
    apply_name_candidate_parent_fields(entry, i30_entry, out_row);
    apply_name_candidate_name_fields(entry, i30_entry, out_row);
    apply_name_candidate_time_and_size_fields(entry, i30_entry, out_row);
    if (include_path) {
        apply_name_candidate_path_fields(entry, i30_entry, out_row);
    }
    return 1;
}

static int build_name_candidate_row_from_sources(
    const MftEntry *entry,
    const MftI30NameEntry *i30_entry,
    MftNameCandidateRow *out_row
)
{
    return build_name_candidate_row_from_sources_with_path_policy(
        entry,
        i30_entry,
        out_row,
        1
    );
}

static int build_name_candidate_row_from_sources_without_path(
    const MftEntry *entry,
    const MftI30NameEntry *i30_entry,
    MftNameCandidateRow *out_row
)
{
    return build_name_candidate_row_from_sources_with_path_policy(
        entry,
        i30_entry,
        out_row,
        0
    );
}

static const char *name_candidate_kind_label(const MftNameCandidateRow *row)
{
    if (row == NULL) {
        return "";
    }
    if (row->has_mft && row->has_i30) {
        return "merged";
    }
    if (row->has_mft && row->has_usn) {
        return "mft+usn";
    }
    if (row->has_mft) {
        return "mft-only";
    }
    if (row->has_i30) {
        return "i30-only";
    }
    if (row->has_usn) {
        return "usn-only";
    }
    return "unknown";
}

static const char *name_candidate_anchor_label(const MftNameCandidateRow *row)
{
    if (row == NULL) {
        return "";
    }
    if (row->direct_data_anchor) {
        return row->is_resident ? "resident-data" : "direct-data";
    }
    if (row->has_data) {
        return "data-without-offset";
    }
    if (row->has_i30) {
        return "catalog-only";
    }
    if (row->has_usn) {
        return "usn-catalog-only";
    }
    return "partial-only";
}

static const char *recovered_match_kind_label(MftRecoveredMatchKind kind)
{
    switch (kind) {
        case MFT_RECOVERED_MATCH_CONTEXT_COMPLETE:
            return "context_complete";
        case MFT_RECOVERED_MATCH_CONTEXT_PARTIAL:
            return "context_partial";
        case MFT_RECOVERED_MATCH_PARENT_GROUP:
            return "parent_group";
        case MFT_RECOVERED_MATCH_FLAT_NAME:
            return "flat_name";
        case MFT_RECOVERED_MATCH_HINT_CONTEXT_COMPLETE:
            return "hint_context_complete";
        case MFT_RECOVERED_MATCH_HINT_CONTEXT_PARTIAL:
            return "hint_context_partial";
        case MFT_RECOVERED_MATCH_HINT_PARENT_GROUP:
            return "hint_parent_group";
        case MFT_RECOVERED_MATCH_HINT_FLAT_NAME:
            return "hint_flat_name";
        case MFT_RECOVERED_MATCH_FOLDER_ONLY:
            return "folder_only";
        case MFT_RECOVERED_MATCH_NONE:
        default:
            return "none";
    }
}

static int path_is_partial_collision_storm_local(
    const char *target_path,
    MftRecoveredMatchKind match_kind,
    int context_complete
);

static int recovered_output_candidate_can_be_committed_local(
    long long abs_offset,
    const char *current_path,
    const char *extension,
    MftRecoveredMatchKind match_kind,
    int context_complete,
    const MftNameHintCandidate *resolved_hint_candidate,
    MftHintClaimKey *claimed_hint_keys,
    size_t claimed_hint_key_capacity,
    size_t *claimed_hint_key_count
);

static void note_name_match_preview_kind(
    MftNameMatchPreviewStats *stats,
    MftRecoveredMatchKind kind
)
{
    if (stats == NULL) {
        return;
    }

    switch (kind) {
        case MFT_RECOVERED_MATCH_CONTEXT_COMPLETE:
            stats->context_complete_matches++;
            break;
        case MFT_RECOVERED_MATCH_CONTEXT_PARTIAL:
            stats->context_partial_matches++;
            break;
        case MFT_RECOVERED_MATCH_PARENT_GROUP:
            stats->parent_group_matches++;
            break;
        case MFT_RECOVERED_MATCH_FLAT_NAME:
            stats->flat_name_matches++;
            break;
        case MFT_RECOVERED_MATCH_HINT_CONTEXT_COMPLETE:
            stats->hint_context_complete_matches++;
            break;
        case MFT_RECOVERED_MATCH_HINT_CONTEXT_PARTIAL:
            stats->hint_context_partial_matches++;
            break;
        case MFT_RECOVERED_MATCH_HINT_PARENT_GROUP:
            stats->hint_parent_group_matches++;
            break;
        case MFT_RECOVERED_MATCH_HINT_FLAT_NAME:
            stats->hint_flat_name_matches++;
            break;
        case MFT_RECOVERED_MATCH_FOLDER_ONLY:
            stats->context_partial_matches++;
            break;
        case MFT_RECOVERED_MATCH_NONE:
        default:
            break;
    }
}

static void note_name_candidate_row_stats(
    MftNameCandidateIndexStats *stats,
    const MftNameCandidateRow *row
)
{
    if (stats == NULL || row == NULL) {
        return;
    }

    stats->total_candidates++;
    if (row->has_mft && row->has_i30) {
        stats->merged_candidates++;
    } else if (row->has_mft) {
        stats->mft_only_candidates++;
    } else if (row->has_i30) {
        stats->i30_only_candidates++;
    }
    if (row->direct_data_anchor) {
        stats->direct_data_anchors++;
    }
    if (row->path_complete) {
        stats->complete_paths++;
    } else if (row->path[0] != '\0') {
        stats->partial_paths++;
    }
    if (row->has_name) {
        stats->named_candidates++;
    } else {
        stats->nameless_candidates++;
    }
    if (row->has_mft) {
        if (row->record_seq != 0U) {
            stats->mft_record_seq_present++;
        } else {
            stats->mft_record_seq_missing++;
        }
    }
}

static int compare_missing_parent_records_local(
    const void *lhs_void,
    const void *rhs_void
)
{
    uint64_t lhs = *(const uint64_t *)lhs_void;
    uint64_t rhs = *(const uint64_t *)rhs_void;

    if (lhs < rhs) {
        return -1;
    }
    if (lhs > rhs) {
        return 1;
    }
    return 0;
}

static int append_missing_parent_record_local(
    uint64_t **records,
    size_t *count,
    size_t *capacity,
    uint64_t parent_record
)
{
    uint64_t *grown;
    size_t new_capacity;

    if (records == NULL || count == NULL || capacity == NULL) {
        return 0;
    }
    if (parent_record == 0ULL) {
        return 1;
    }
    if (*count >= *capacity) {
        new_capacity = (*capacity == 0U) ? 1024U : (*capacity * 2U);
        grown = (uint64_t *)realloc(*records, new_capacity * sizeof(**records));
        if (grown == NULL) {
            return 0;
        }
        *records = grown;
        *capacity = new_capacity;
    }
    (*records)[(*count)++] = parent_record;
    return 1;
}

static void finalize_missing_parent_stats_local(
    MftNameCandidateIndexStats *stats,
    uint64_t *missing_parent_records,
    size_t missing_parent_count
)
{
    size_t index = 0U;

    if (stats == NULL || missing_parent_records == NULL || missing_parent_count == 0U) {
        return;
    }

    qsort(
        missing_parent_records,
        missing_parent_count,
        sizeof(*missing_parent_records),
        compare_missing_parent_records_local
    );

    while (index < missing_parent_count) {
        uint64_t current_record = missing_parent_records[index];
        size_t run_count = 1U;

        while (index + run_count < missing_parent_count &&
               missing_parent_records[index + run_count] == current_record) {
            run_count++;
        }

        stats->unique_missing_parents++;
        if (run_count > stats->top_missing_parent_blocked_candidates) {
            stats->top_missing_parent_blocked_candidates = run_count;
            stats->top_missing_parent_record = current_record;
        }
        index += run_count;
    }
}

static void mft_name_live_stats_note_candidate_index_stats(
    const MftNameCandidateIndexStats *stats
)
{
    if (stats == NULL) {
        return;
    }

    g_mft_name_live_stats.candidate_complete_paths_last =
        (uint64_t)stats->complete_paths;
    g_mft_name_live_stats.candidate_partial_paths_last =
        (uint64_t)stats->partial_paths;
    g_mft_name_live_stats.mft_record_seq_present_last =
        (uint64_t)stats->mft_record_seq_present;
    g_mft_name_live_stats.mft_record_seq_missing_last =
        (uint64_t)stats->mft_record_seq_missing;
    g_mft_name_live_stats.unique_missing_parents_last =
        (uint64_t)stats->unique_missing_parents;
    g_mft_name_live_stats.top_missing_parent_record_last =
        stats->top_missing_parent_record;
    g_mft_name_live_stats.top_missing_parent_blocked_candidates_last =
        (uint64_t)stats->top_missing_parent_blocked_candidates;
}

static int write_name_candidate_row_to_stream(
    FILE *file,
    const MftNameCandidateRow *row
)
{
    char sanitized_name[MFT_NAME_MAX];
    char sanitized_path[MFT_PATH_MAX];
    char serial_text[32] = "";

    if (file == NULL || row == NULL) {
        return 0;
    }

    mft_name_trace_sanitize_text(row->name, sanitized_name, sizeof(sanitized_name));
    mft_name_trace_sanitize_text(row->path, sanitized_path, sizeof(sanitized_path));
    scan_state_format_ntfs_serial(
        row->volume_serial,
        serial_text,
        sizeof(serial_text)
    );

    return fprintf(
               file,
               "%lld\t%s\t%lld\t%d\t%u\t%s\t%u\t%s\t%s\t%s\t%d\t%d\t%d\t%s\t%s\t%u\t%llu\t%u\t%llu\t%lld\t%llu\t%llu\t%d\t%d\t%lld\t%zu\t%zu\t%d\t%s\t%s\t%d\t%llu\t%s\n",
               row->family_base_offset,
               serial_text,
               row->volume_start,
               row->record_number,
               (unsigned int)row->record_seq,
               name_candidate_kind_label(row),
               row->source_mask,
               row->source_labels,
               row->mft_source_label,
               row->tree_class_label,
               row->ntfs_metadata ? 1 : 0,
               row->has_mft ? 1 : 0,
               row->has_i30 ? 1 : 0,
               row->preferred_name_origin,
               sanitized_name,
               (unsigned int)row->name_namespace,
               (unsigned long long)row->parent_record,
               (unsigned int)row->parent_seq,
               (unsigned long long)row->created_filetime,
               (long long)row->created_unix,
               (unsigned long long)row->data_size,
               (unsigned long long)row->allocated_size,
               row->has_data ? 1 : 0,
               row->is_resident ? 1 : 0,
               row->abs_offset,
               row->run_extent_count,
               row->i30_run_extent_count,
               row->direct_data_anchor ? 1 : 0,
               name_candidate_anchor_label(row),
               row->path_origin,
               row->path_complete ? 1 : 0,
               row->path_missing_parent,
               sanitized_path
           ) >= 0;
}

static int mft_build_name_candidate_index_local(
    MftNameCandidateIndexStats *out_stats,
    int write_artifact
)
{
    char path[1024];
    char tmp_path[1064];
    char progress_detail[96];
    FILE *file = NULL;
    size_t i;
    MftNameCandidateIndexStats stats = {0};
    uint64_t *missing_parent_records = NULL;
    size_t missing_parent_count = 0U;
    size_t missing_parent_capacity = 0U;
    size_t named_current = 0U;
    size_t unreconciled_current = 0U;
    size_t total_slots = 0U;
    size_t processed_slots = 0U;
    size_t output_index;
    double last_candidate_delta_at;
    size_t last_total_candidates = 0U;
    const char *activity_label = write_artifact
        ? "indexing name candidates"
        : "checking name candidate stats";
    const char *yield_label = write_artifact
        ? "NTFS name_candidate_index refresh"
        : "NTFS name_candidate_index stats check";

    if (out_stats != NULL) {
        memset(out_stats, 0, sizeof(*out_stats));
    }
    path[0] = '\0';
    tmp_path[0] = '\0';
    if (write_artifact) {
        if (!build_fixed_mft_output_path(
                path,
                sizeof(path),
                MFT_NAME_CANDIDATE_INDEX_FILE_NAME) ||
            !ensure_saved_directory()) {
            return 0;
        }
        if (snprintf(tmp_path, sizeof(tmp_path), "%s.tmp", path) >=
            (int)sizeof(tmp_path)) {
            return 0;
        }
    }

    total_slots = g_mft_record_index_capacity;
    if (SIZE_MAX - total_slots > g_mft_i30_name_index_capacity) {
        total_slots += g_mft_i30_name_index_capacity;
    } else {
        total_slots = SIZE_MAX;
    }
    for (output_index = 0U;
         output_index < g_recovered_output_count;
         output_index++) {
        if (recovered_output_counts_as_named(&g_recovered_outputs[output_index])) {
            named_current++;
        }
    }
    unreconciled_current =
        g_recovered_output_count >= named_current
            ? g_recovered_output_count - named_current
            : 0U;
    log_set_working_activity(activity_label);
    log_set_working_progress(0ULL, 0ULL);
    snprintf(
        progress_detail,
        sizeof(progress_detail),
        "index=0/%zu",
        total_slots
    );
    log_set_working_position_detail(progress_detail);
    write_name_progress_heartbeat_local(
        activity_label,
        0U,
        total_slots,
        named_current,
        unreconciled_current
    );

    if (write_artifact) {
        file = fopen(tmp_path, "w");
        if (file == NULL) {
            return 0;
        }
    }
    last_candidate_delta_at = monotonic_seconds_local();

    if (write_artifact) {
        if (fprintf(
                file,
                "family_base_offset\tvolume_serial\tvolume_start\trecord_number\trecord_seq\tcandidate_kind\tsource_mask\tsource_labels\tmft_source\ttree_class\tntfs_metadata\thas_mft\thas_i30\tpreferred_name_origin\tname\tname_namespace\tparent_record\tparent_seq\tcreated_filetime\tcreated_unix\tdata_size\tallocated_size\thas_data\tis_resident\tabs_offset\trun_extent_count\ti30_run_extent_count\tdirect_data_anchor\tanchor_kind\tpath_origin\tpath_complete\tpath_missing_parent\tpath\n") < 0) {
            fclose(file);
            unlink(tmp_path);
            return 0;
        }
    }

    for (i = 0U; i < g_mft_record_index_capacity; i++) {
        MftNameCandidateRow row;
        const MftI30NameEntry *i30_entry = NULL;
        size_t entry_index = 0U;
        MftEntry *entry;

        processed_slots++;
        if ((processed_slots % MFT_NAME_CANDIDATE_INDEX_HEARTBEAT_INTERVAL) == 0U) {
            double now = monotonic_seconds_local();

            if (stats.total_candidates != last_total_candidates) {
                last_total_candidates = stats.total_candidates;
                last_candidate_delta_at = now;
            } else if (now - last_candidate_delta_at >
                       MFT_NAME_RECONCILE_NO_DELTA_SECONDS) {
                log_info(
                    "%s yielded after %.0fs without new candidate rows: index=%zu/%zu candidates=%zu",
                    yield_label,
                    now - last_candidate_delta_at,
                    processed_slots,
                    total_slots,
                    stats.total_candidates
                );
                if (file != NULL) {
                    fclose(file);
                }
                if (write_artifact) {
                    unlink(tmp_path);
                }
                free(missing_parent_records);
                return 0;
            }
            snprintf(
                progress_detail,
                sizeof(progress_detail),
                "index=%zu/%zu candidates=%zu",
                processed_slots,
                total_slots,
                stats.total_candidates
            );
            log_set_working_position_detail(progress_detail);
            write_name_progress_heartbeat_local(
                activity_label,
                processed_slots,
                total_slots,
                named_current,
                unreconciled_current
            );
            if (app_stop_requested()) {
                if (file != NULL) {
                    fclose(file);
                }
                if (write_artifact) {
                    unlink(tmp_path);
                }
                free(missing_parent_records);
                return 0;
            }
        }
        if (!g_mft_record_index[i].in_use) {
            continue;
        }
        entry_index = g_mft_record_index[i].entry_index;
        if (entry_index >= g_mft_entry_count) {
            continue;
        }

        entry = &g_mft_entries[entry_index];
        (void)i30_name_index_lookup(
            entry->family_base_offset,
            entry->record_number,
            &i30_entry
        );
        if (!build_name_candidate_row_from_sources(entry, i30_entry, &row) ||
            (write_artifact && !write_name_candidate_row_to_stream(file, &row))) {
            if (file != NULL) {
                fclose(file);
            }
            if (write_artifact) {
                unlink(tmp_path);
            }
            free(missing_parent_records);
            return 0;
        }
        note_name_candidate_row_stats(&stats, &row);
        if (!append_missing_parent_record_local(
                &missing_parent_records,
                &missing_parent_count,
                &missing_parent_capacity,
                row.path_missing_parent)) {
            if (file != NULL) {
                fclose(file);
            }
            if (write_artifact) {
                unlink(tmp_path);
            }
            free(missing_parent_records);
            return 0;
        }
    }

    for (i = 0U; i < g_mft_i30_name_index_capacity; i++) {
        MftNameCandidateRow row;
        const MftI30NameEntry *i30_entry = &g_mft_i30_name_index[i];

        processed_slots++;
        if ((processed_slots % MFT_NAME_CANDIDATE_INDEX_HEARTBEAT_INTERVAL) == 0U) {
            double now = monotonic_seconds_local();

            if (stats.total_candidates != last_total_candidates) {
                last_total_candidates = stats.total_candidates;
                last_candidate_delta_at = now;
            } else if (now - last_candidate_delta_at >
                       MFT_NAME_RECONCILE_NO_DELTA_SECONDS) {
                log_info(
                    "%s yielded after %.0fs without new candidate rows: index=%zu/%zu candidates=%zu",
                    yield_label,
                    now - last_candidate_delta_at,
                    processed_slots,
                    total_slots,
                    stats.total_candidates
                );
                if (file != NULL) {
                    fclose(file);
                }
                if (write_artifact) {
                    unlink(tmp_path);
                }
                free(missing_parent_records);
                return 0;
            }
            snprintf(
                progress_detail,
                sizeof(progress_detail),
                "index=%zu/%zu candidates=%zu",
                processed_slots,
                total_slots,
                stats.total_candidates
            );
            log_set_working_position_detail(progress_detail);
            write_name_progress_heartbeat_local(
                activity_label,
                processed_slots,
                total_slots,
                named_current,
                unreconciled_current
            );
            if (app_stop_requested()) {
                if (file != NULL) {
                    fclose(file);
                }
                if (write_artifact) {
                    unlink(tmp_path);
                }
                free(missing_parent_records);
                return 0;
            }
        }
        if (!i30_entry->in_use ||
            i30_entry->name[0] == '\0' ||
            record_index_find_index(
                i30_entry->family_base_offset,
                i30_entry->record_number,
                NULL)) {
            continue;
        }

        if (!build_name_candidate_row_from_sources(NULL, i30_entry, &row) ||
            (write_artifact && !write_name_candidate_row_to_stream(file, &row))) {
            if (file != NULL) {
                fclose(file);
            }
            if (write_artifact) {
                unlink(tmp_path);
            }
            free(missing_parent_records);
            return 0;
        }
        note_name_candidate_row_stats(&stats, &row);
        if (!append_missing_parent_record_local(
                &missing_parent_records,
                &missing_parent_count,
                &missing_parent_capacity,
                row.path_missing_parent)) {
            if (file != NULL) {
                fclose(file);
            }
            if (write_artifact) {
                unlink(tmp_path);
            }
            free(missing_parent_records);
            return 0;
        }
    }

    if (write_artifact) {
        if (fclose(file) != 0) {
            unlink(tmp_path);
            free(missing_parent_records);
            return 0;
        }
        {
            MftNameCandidateIndexStats existing_stats = {0};

            if (load_name_candidate_index_stats_from_file_local(
                    path,
                    &existing_stats) &&
                existing_name_candidate_index_is_richer_local(
                    &existing_stats,
                    &stats)) {
                log_verbose(
                    "Keeping existing NTFS name_candidate_index.tsv because the fresh rewrite is thinner: existing_total=%zu fresh_total=%zu existing_complete=%zu fresh_complete=%zu existing_direct=%zu fresh_direct=%zu",
                    existing_stats.total_candidates,
                    stats.total_candidates,
                    existing_stats.complete_paths,
                    stats.complete_paths,
                    existing_stats.direct_data_anchors,
                    stats.direct_data_anchors
                );
                unlink(tmp_path);
                stats = existing_stats;
                finalize_missing_parent_stats_local(
                    &stats,
                    missing_parent_records,
                    missing_parent_count
                );
                free(missing_parent_records);
                mft_name_live_stats_note_candidate_index_stats(&stats);
                if (out_stats != NULL) {
                    *out_stats = stats;
                }
                return 1;
            }
        }
        if (rename(tmp_path, path) != 0) {
            unlink(tmp_path);
            free(missing_parent_records);
            return 0;
        }
    }

    finalize_missing_parent_stats_local(
        &stats,
        missing_parent_records,
        missing_parent_count
    );
    free(missing_parent_records);
    mft_name_live_stats_note_candidate_index_stats(&stats);
    snprintf(
        progress_detail,
        sizeof(progress_detail),
        "index=%zu/%zu candidates=%zu",
        processed_slots,
        total_slots,
        stats.total_candidates
    );
    log_set_working_position_detail(progress_detail);
    write_name_progress_heartbeat_local(
        activity_label,
        processed_slots,
        total_slots,
        named_current,
        unreconciled_current
    );

    if (out_stats != NULL) {
        *out_stats = stats;
    }
    return 1;
}

int mft_get_name_candidate_index_stats(MftNameCandidateIndexStats *out_stats)
{
    MftNameCandidateIndexStats stats = {0};

    if (g_mft_name_candidate_stats_cache_valid &&
        g_mft_name_candidate_stats_cache_revision == g_mft_catalog_revision) {
        g_mft_name_live_stats.candidate_stats_cache_hits++;
        g_mft_name_live_stats.candidate_stats_cache_revision =
            g_mft_name_candidate_stats_cache_revision;
        g_mft_name_live_stats.mft_catalog_revision_last =
            g_mft_catalog_revision;
        if (out_stats != NULL) {
            *out_stats = g_mft_name_candidate_stats_cache;
        }
        mft_name_live_stats_note_candidate_index_stats(
            &g_mft_name_candidate_stats_cache
        );
        return 1;
    }

    g_mft_name_live_stats.candidate_stats_cache_misses++;
    if (!mft_build_name_candidate_index_local(&stats, 0)) {
        return 0;
    }
    g_mft_name_candidate_stats_cache = stats;
    g_mft_name_candidate_stats_cache_revision = g_mft_catalog_revision;
    g_mft_name_candidate_stats_cache_valid = 1;
    g_mft_name_live_stats.candidate_stats_cache_revision =
        g_mft_name_candidate_stats_cache_revision;
    g_mft_name_live_stats.mft_catalog_revision_last =
        g_mft_catalog_revision;
    if (out_stats != NULL) {
        *out_stats = stats;
    }
    return 1;
}

int mft_write_name_candidate_index(MftNameCandidateIndexStats *out_stats)
{
    MftNameCandidateIndexStats stats = {0};

    if (!mft_build_name_candidate_index_local(&stats, 1)) {
        return 0;
    }
    g_mft_name_candidate_stats_cache = stats;
    g_mft_name_candidate_stats_cache_revision = g_mft_catalog_revision;
    g_mft_name_candidate_stats_cache_valid = 1;
    g_mft_name_live_stats.candidate_stats_cache_revision =
        g_mft_name_candidate_stats_cache_revision;
    g_mft_name_live_stats.mft_catalog_revision_last =
        g_mft_catalog_revision;
    if (out_stats != NULL) {
        *out_stats = stats;
    }
    return 1;
}

static const char *mft_unidentified_reason_for_preview_row(
    const MftRecoveredOutput *output,
    const char *extension,
    int matched,
    MftRecoveredMatchKind kind,
    const char *preview_path
)
{
    MftEntry *entry;
    char contextual_path[1024];
    int context_complete = 0;

    if (output == NULL || output->path[0] == '\0') {
        return "missing_output_state";
    }
    if (output->reconciled) {
        return "already_reconciled";
    }
    if (extension == NULL || extension[0] == '\0') {
        return "missing_extension";
    }
    if (matched &&
        preview_path != NULL &&
        preview_path[0] != '\0' &&
        !path_is_under_unident_local(preview_path)) {
        switch (kind) {
            case MFT_RECOVERED_MATCH_CONTEXT_COMPLETE:
            case MFT_RECOVERED_MATCH_HINT_CONTEXT_COMPLETE:
                return "match_ready_complete_path";
            case MFT_RECOVERED_MATCH_FOLDER_ONLY:
                return "match_ready_folder_only";
            case MFT_RECOVERED_MATCH_CONTEXT_PARTIAL:
            case MFT_RECOVERED_MATCH_HINT_CONTEXT_PARTIAL:
                return "match_ready_partial_path";
            case MFT_RECOVERED_MATCH_PARENT_GROUP:
            case MFT_RECOVERED_MATCH_HINT_PARENT_GROUP:
                return "match_ready_parent_group";
            case MFT_RECOVERED_MATCH_FLAT_NAME:
            case MFT_RECOVERED_MATCH_HINT_FLAT_NAME:
                return "match_ready_flat_name";
            case MFT_RECOVERED_MATCH_NONE:
            default:
                return "match_ready";
        }
    }

    entry = find_best_entry_for_data_offset(output->abs_offset);
    if (entry == NULL) {
        if (g_mft_entry_count == 0U && g_mft_i30_name_index_count == 0U) {
            return "no_metadata_catalog";
        }
        if (g_mft_i30_name_index_count == 0U) {
            return "no_mft_or_i30_candidate";
        }
        return "no_direct_mft_candidate";
    }
    if (entry_is_ntfs_metadata(entry)) {
        return "metadata_file_candidate";
    }
    if (entry->source_kind == MFT_ENTRY_SOURCE_MIRROR) {
        return "mirror_only_candidate";
    }
    if (!entry_starts_at_recovered_offset(entry, output->abs_offset)) {
        return "inside_mft_run_not_exact_start";
    }
    if (!entry->has_name || entry->name[0] == '\0') {
        return "mft_entry_nameless";
    }
    if (!entry_resolves_contextual_output_path_for_naming_with_status(
            entry,
            contextual_path,
            sizeof(contextual_path),
            &context_complete) ||
        contextual_path[0] == '\0') {
        return "path_not_resolved";
    }
    if (!contextual_path_is_usable_for_recovered_extension(
            contextual_path,
            extension)) {
        return "extension_or_context_rejected";
    }
    if (!context_complete) {
        return "parent_missing";
    }
    if (matched && preview_path != NULL && path_is_under_unident_local(preview_path)) {
        return "candidate_resolved_to_unident";
    }
    return "candidate_not_commitworthy";
}

int mft_write_name_match_preview(MftNameMatchPreviewStats *out_stats)
{
    char path[1024];
    FILE *file;
    size_t i;
    size_t preview_limit;
    size_t named_current = 0U;
    size_t unreconciled_current = 0U;
    int saved_preview_path_no_fs_checks;
    int preview_limited_by_count = 0;
    int preview_limited_by_time = 0;
    int preview_limited_by_output_budget = 0;
    double preview_started_at;
    MftNameMatchPreviewStats stats = {0};
    MftHintClaimKey *preview_claimed_hint_keys = NULL;
    size_t preview_claimed_hint_key_count = 0U;

    if (out_stats != NULL) {
        memset(out_stats, 0, sizeof(*out_stats));
    }
    if (!build_fixed_mft_output_path(
            path,
            sizeof(path),
            MFT_NAME_MATCH_PREVIEW_FILE_NAME) ||
        !ensure_saved_directory()) {
        return 0;
    }

    file = fopen(path, "w");
    if (file == NULL) {
        return 0;
    }

    if (fprintf(
            file,
            "abs_offset\treconciled\tcurrent_path\textension\tmatch_kind\tmatched\tsuggested_path\tunidentified_reason\n") < 0) {
        fclose(file);
        return 0;
    }

    preview_limit = g_recovered_output_count;
    if (preview_limit > MFT_NAME_MATCH_PREVIEW_OUTPUT_LIMIT) {
        preview_limit = MFT_NAME_MATCH_PREVIEW_OUTPUT_LIMIT;
    }
    for (i = 0U; i < g_recovered_output_count; i++) {
        if (recovered_output_counts_as_named(&g_recovered_outputs[i])) {
            named_current++;
        }
    }
    unreconciled_current =
        g_recovered_output_count >= named_current
            ? g_recovered_output_count - named_current
            : 0U;
    write_name_progress_heartbeat_local(
        "previewing saved name matches",
        0U,
        g_recovered_output_count,
        named_current,
        unreconciled_current
    );
    saved_preview_path_no_fs_checks = g_mft_preview_path_no_fs_checks;
    g_mft_preview_path_no_fs_checks = 1;
    preview_started_at = monotonic_seconds_local();
    if (g_recovered_output_count > 0U) {
        preview_claimed_hint_keys = (MftHintClaimKey *)calloc(
            g_recovered_output_count,
            sizeof(*preview_claimed_hint_keys)
        );
    }

    for (i = 0U; i < g_recovered_output_count; i++) {
        const MftRecoveredOutput *output = &g_recovered_outputs[i];
        const char *extension = path_extension_for_reconcile(output->path);
        MftRecoveredMatchKind kind = MFT_RECOVERED_MATCH_NONE;
        char preview_path[1024] = "";
        char sanitized_current[1024];
        char sanitized_preview[1024];
        const char *unidentified_reason;
        int contextual = 0;
        int context_complete = 0;
        int matched = 0;

        if (app_stop_requested()) {
            g_mft_preview_path_no_fs_checks = saved_preview_path_no_fs_checks;
            mft_name_match_preview_output_budget_clear();
            free(preview_claimed_hint_keys);
            fclose(file);
            return 0;
        }
        if (i >= preview_limit) {
            preview_limited_by_count = 1;
            break;
        }
        if ((i & (MFT_NAME_MATCH_PREVIEW_HEARTBEAT_INTERVAL - 1U)) == 0U) {
            write_name_progress_heartbeat_local(
                "previewing saved name matches",
                i + 1U,
                g_recovered_output_count,
                named_current,
                unreconciled_current
            );
            if (monotonic_seconds_local() - preview_started_at >
                MFT_NAME_MATCH_PREVIEW_TIME_BUDGET_SECONDS) {
                preview_limited_by_time = 1;
                break;
            }
        }

        if (output->reconciled || extension == NULL) {
            continue;
        }

        stats.total_outputs++;
        mft_name_match_preview_output_budget_start(
            MFT_NAME_MATCH_PREVIEW_OUTPUT_BUDGET_SECONDS
        );
        matched = mft_build_recovered_output_path_internal(
            preview_path,
            sizeof(preview_path),
            output->abs_offset,
            APP_DEFAULT_UNIDENT_DIR,
            "recov",
            extension,
            output->path,
            1,
            &kind,
            NULL,
            &contextual,
            &context_complete,
            NULL
        );
        if (mft_name_match_preview_output_budget_was_exhausted()) {
            mft_name_match_preview_output_budget_clear();
            stats.unmatched_outputs++;
            preview_limited_by_time = 1;
            preview_limited_by_output_budget = 1;
            break;
        }
        mft_name_match_preview_output_budget_clear();
        if (matched &&
            (!contextual ||
             !file_exists(output->path) ||
             path_is_partial_collision_storm_local(
                 preview_path,
                 kind,
                 context_complete) ||
             !recovered_output_candidate_can_be_committed_local(
                 output->abs_offset,
                 output->path,
                 extension,
                 kind,
                 context_complete,
                 NULL,
                 preview_claimed_hint_keys,
                 g_recovered_output_count,
                 &preview_claimed_hint_key_count))) {
            matched = 0;
        }
        if (matched) {
            stats.matched_outputs++;
            note_name_match_preview_kind(&stats, kind);
        } else {
            stats.unmatched_outputs++;
        }
        unidentified_reason = mft_unidentified_reason_for_preview_row(
            output,
            extension,
            matched,
            kind,
            preview_path
        );

        mft_name_trace_sanitize_text(
            output->path,
            sanitized_current,
            sizeof(sanitized_current)
        );
        mft_name_trace_sanitize_text(
            preview_path,
            sanitized_preview,
            sizeof(sanitized_preview)
        );
        if (fprintf(
                file,
                "%lld\t%d\t%s\t%s\t%s\t%d\t%s\t%s\n",
                output->abs_offset,
                output->reconciled ? 1 : 0,
                sanitized_current,
                extension != NULL ? extension : "",
                recovered_match_kind_label(kind),
                matched ? 1 : 0,
                sanitized_preview,
                unidentified_reason != NULL ? unidentified_reason : "unknown") < 0) {
            g_mft_preview_path_no_fs_checks = saved_preview_path_no_fs_checks;
            mft_name_match_preview_output_budget_clear();
            free(preview_claimed_hint_keys);
            fclose(file);
            return 0;
        }
    }

    g_mft_preview_path_no_fs_checks = saved_preview_path_no_fs_checks;
    mft_name_match_preview_output_budget_clear();
    if (fclose(file) != 0) {
        free(preview_claimed_hint_keys);
        return 0;
    }
    free(preview_claimed_hint_keys);
    if (preview_limited_by_count || preview_limited_by_time) {
        log_verbose(
            "Name match preview bounded: processed=%zu/%zu matched=%zu unmatched=%zu reason=%s",
            i < g_recovered_output_count ? i : g_recovered_output_count,
            g_recovered_output_count,
            stats.matched_outputs,
            stats.unmatched_outputs,
            preview_limited_by_count
                ? "output_limit"
                : (preview_limited_by_output_budget
                       ? "per_output_zero_delta_budget"
                       : (preview_limited_by_time ? "time_budget" : "bounded"))
        );
    }
    write_name_progress_heartbeat_local(
        "previewing saved name matches",
        i < g_recovered_output_count ? i : g_recovered_output_count,
        g_recovered_output_count,
        named_current,
        unreconciled_current
    );

    if (out_stats != NULL) {
        *out_stats = stats;
    }
    return 1;
}

static int refresh_name_candidate_index_core_local(const char *phase_label)
{
    MftNameCandidateIndexStats candidate_stats = {0};
    const char *label =
        (phase_label != NULL && phase_label[0] != '\0')
            ? phase_label
            : "MFT";

    if (mft_write_name_candidate_index(&candidate_stats)) {
        log_verbose(
            "%s name candidate index refreshed: total=%zu merged=%zu mft_only=%zu i30_only=%zu direct_anchors=%zu complete_paths=%zu partial_paths=%zu named=%zu nameless=%zu unique_missing_parents=%zu top_missing_parent=%llu top_missing_parent_blocked=%zu",
            label,
            candidate_stats.total_candidates,
            candidate_stats.merged_candidates,
            candidate_stats.mft_only_candidates,
            candidate_stats.i30_only_candidates,
            candidate_stats.direct_data_anchors,
            candidate_stats.complete_paths,
            candidate_stats.partial_paths,
            candidate_stats.named_candidates,
            candidate_stats.nameless_candidates,
            candidate_stats.unique_missing_parents,
            (unsigned long long)candidate_stats.top_missing_parent_record,
            candidate_stats.top_missing_parent_blocked_candidates
        );
        return 1;
    } else {
        log_info(
            "%s name candidate index could not be refreshed from the harvested NTFS metadata in this pass",
            label
        );
        return 0;
    }
}

static void refresh_name_candidate_artifacts_local(const char *phase_label)
{
    MftNameMatchPreviewStats preview_stats = {0};
    const char *label =
        (phase_label != NULL && phase_label[0] != '\0')
            ? phase_label
            : "MFT";

    (void)refresh_name_candidate_index_core_local(label);

    if (g_recovered_output_count > MFT_RECOVERED_DEEP_RECONCILE_OUTPUT_LIMIT) {
        log_info(
            "%s name match preview skipped: recovered=%zu exceeds safe preview limit=%u; name_candidate_index.tsv was still refreshed",
            label,
            g_recovered_output_count,
            (unsigned int)MFT_RECOVERED_DEEP_RECONCILE_OUTPUT_LIMIT
        );
        return;
    }

    if (mft_write_name_match_preview(&preview_stats)) {
        log_info(
            "%s name match preview refreshed: outputs=%zu matched=%zu unmatched=%zu context=%zu partial=%zu parent=%zu flat=%zu hint_context=%zu hint_partial=%zu hint_parent=%zu hint_flat=%zu",
            label,
            preview_stats.total_outputs,
            preview_stats.matched_outputs,
            preview_stats.unmatched_outputs,
            preview_stats.context_complete_matches,
            preview_stats.context_partial_matches,
            preview_stats.parent_group_matches,
            preview_stats.flat_name_matches,
            preview_stats.hint_context_complete_matches,
            preview_stats.hint_context_partial_matches,
            preview_stats.hint_parent_group_matches,
            preview_stats.hint_flat_name_matches
        );
    } else {
        log_info(
            "%s name match preview could not be refreshed from the harvested NTFS metadata in this pass",
            label
        );
    }
}

static int build_users_recovery_path_from_entry(
    const MftEntry *entry,
    char *out,
    size_t out_size
)
{
    const MftEntry *chain[256];
    const MftEntry *current = entry;
    long long family_base_offset;
    size_t chain_count = 0;
    size_t i;
    int found_users_root = 0;

    if (out == NULL || out_size == 0) {
        return 0;
    }
    out[0] = '\0';

    if (entry == NULL || !entry->has_name || entry_is_ntfs_metadata(entry)) {
        return 0;
    }

    family_base_offset = entry->family_base_offset;

    while (current != NULL && current->has_name && chain_count < 256U) {
        chain[chain_count++] = current;

        if ((current->flags & 0x0002) &&
            current->parent_record == 5 &&
            name_is_user_root(current->name)) {
            found_users_root = 1;
            break;
        }

        if (current->record_number == 5 ||
            current->parent_record == (uint64_t)current->record_number ||
            current->parent_record > (uint64_t)INT32_MAX) {
            break;
        }

        current = find_entry_by_family_and_record(
            family_base_offset,
            (int)current->parent_record
        );
    }

    if (!found_users_root) {
        return 0;
    }

    snprintf(out, out_size, "/");
    for (i = chain_count; i > 0; i--) {
        const MftEntry *part = chain[i - 1U];

        if (part == NULL || !part->has_name || part->record_number == 5) {
            continue;
        }

        if (strlen(out) > 1) {
            strncat(out, "/", out_size - strlen(out) - 1U);
        }
        strncat(out, part->name, out_size - strlen(out) - 1U);
    }

    return out[0] != '\0' && strcmp(out, "/") != 0;
}

static int entry_resolves_contextual_output_path_with_status(
    const MftEntry *entry,
    char *out,
    size_t out_size,
    int *out_complete
)
{
    int complete = 0;

    if (out_complete != NULL) {
        *out_complete = 0;
    }

    if (g_contextual_output_mode == MFT_CONTEXTUAL_OUTPUT_FULL_TREE) {
        if (!build_full_tree_contextual_path_from_entry_with_status(
                entry,
                out,
                out_size,
                &complete) ||
            !complete) {
            if (out != NULL && out_size > 0) {
                out[0] = '\0';
            }
            return 0;
        }

        if (out_complete != NULL) {
            *out_complete = 1;
        }
        return 1;
    }

    if (!build_users_recovery_path_from_entry(entry, out, out_size)) {
        return 0;
    }

    if (out_complete != NULL) {
        *out_complete = 1;
    }

    return 1;
}

static int entry_starts_at_recovered_offset(const MftEntry *entry, long long abs_offset)
{
    long long entry_abs_offset = -1LL;

    return entry != NULL &&
           abs_offset >= 0 &&
           entry->has_data &&
           !entry->is_resident &&
           mft_entry_effective_abs_offset_local(entry, &entry_abs_offset) &&
           entry_abs_offset == abs_offset;
}

static int exact_anchor_matches_live_mounted_path_local(
    const MftEntry *entry,
    const char *recovered_path
)
{
#ifdef __linux__
    static int mount_root_attempted = 0;
    static char mount_root[PATH_MAX];
    char contextual_path[1024];
    char live_path[PATH_MAX];
    uint64_t recovered_hash = 0ULL;
    uint64_t live_hash = 0ULL;
    uint64_t recovered_size = 0ULL;
    uint64_t live_size = 0ULL;
    int complete = 0;

    if (entry == NULL) {
        return 0;
    }

    /*
     * Fresh carving often asks for a target path before any recovered file
     * exists on disk. In that situation we cannot hash-verify against the live
     * mounted path yet, but we also should not veto a perfectly good exact
     * anchor just because there is nothing to compare with.
     */
    if (recovered_path == NULL || recovered_path[0] == '\0') {
        return 1;
    }

    if (!mount_root_attempted) {
        mount_root_attempted = 1;
        mount_root[0] = '\0';
        (void)resolve_live_mount_root_for_saved_ntfs_source_local(
            mount_root,
            sizeof(mount_root)
        );
    }

    if (mount_root[0] == '\0' ||
        !build_full_tree_contextual_path_from_entry_with_status(
            entry,
            contextual_path,
            sizeof(contextual_path),
            &complete) ||
        !complete ||
        contextual_path[0] != '/' ||
        snprintf(
            live_path,
            sizeof(live_path),
            "%s%s",
            mount_root,
            contextual_path) >= (int)sizeof(live_path) ||
        !file_exists(live_path) ||
        !hash_file_path_local(recovered_path, &recovered_hash, &recovered_size) ||
        !hash_file_path_local(live_path, &live_hash, &live_size)) {
        return 1;
    }

    return recovered_size == live_size && recovered_hash == live_hash;
#else
    (void)entry;
    (void)recovered_path;
    return 1;
#endif
}

static int entry_resolves_recovery_path(
    const MftEntry *entry,
    char *out,
    size_t out_size
)
{
    return entry_resolves_contextual_output_path_with_status(
        entry,
        out,
        out_size,
        NULL
    );
}

static int entry_has_complete_tree_path(const MftEntry *entry)
{
    int complete = 0;

    build_full_path_details_from_entry(entry, NULL, 0, &complete, NULL);
    return complete;
}

static int entry_is_visible_for_recovery(const MftEntry *entry)
{
    char recovery_path[1024];

    return entry_resolves_recovery_path(
        entry,
        recovery_path,
        sizeof(recovery_path)
    );
}

static void create_saved_directory_from_entry(const MftEntry *entry)
{
    char full_path[MFT_PATH_MAX];
    char recovery_path[1024];
    char normalized[1024];
    char conflict_safe[1024];

    if (entry == NULL || !entry->has_name) {
        return;
    }

    if (!(entry->flags & 0x0002)) {
        return;
    }

    if (!entry_is_primary_source(entry) ||
        !entry_is_visible_for_recovery(entry) ||
        !entry_has_complete_tree_path(entry)) {
        return;
    }

    if (!ensure_saved_directory()) {
        return;
    }

    build_full_path_from_entry(entry, full_path, sizeof(full_path));

    if (!resolve_recovery_path_from_mft(
            recovery_path,
            sizeof(recovery_path),
            full_path)) {
        return;
    }

    if (!mft_build_recovered_path(normalized, sizeof(normalized), recovery_path)) {
        return;
    }

    if (!mft_normalize_directory_conflicts_for_path(
            conflict_safe,
            sizeof(conflict_safe),
            normalized,
            1)) {
        return;
    }

    if (!ensure_directory_recursive(conflict_safe)) {
        log_error("Failed to create MFT directory tree: %s", conflict_safe);
    }
}

static int ascii_equals_ci(const char *a, const char *b)
{
    while (a != NULL && b != NULL && *a != '\0' && *b != '\0') {
        if (ascii_tolower_char(*a) != ascii_tolower_char(*b)) {
            return 0;
        }

        a++;
        b++;
    }

    return a != NULL &&
           b != NULL &&
           *a == '\0' &&
           *b == '\0';
}

static const char *path_basename_local(const char *path)
{
    const char *basename;

    if (path == NULL) {
        return NULL;
    }

    basename = strrchr(path, '/');
    return (basename != NULL) ? (basename + 1) : path;
}

static const char *path_extension_local(const char *path)
{
    const char *basename;
    const char *dot;

    if (path == NULL) {
        return NULL;
    }

    basename = path_basename_local(path);
    dot = strrchr(basename, '.');
    if (dot == NULL || dot[1] == '\0') {
        return NULL;
    }

    return dot + 1;
}

static int basename_is_system_container_ci(const char *basename)
{
    return ascii_equals_ci(basename, "hiberfil.sys") ||
           ascii_equals_ci(basename, "pagefile.sys") ||
           ascii_equals_ci(basename, "swapfile.sys") ||
           ascii_equals_ci(basename, "memory.dmp") ||
           ascii_equals_ci(basename, "dumpstack.log") ||
           ascii_equals_ci(basename, "dumpstack.log.tmp");
}

static int basename_is_low_confidence_numeric_name(const char *basename)
{
    const char *dot = NULL;
    const char *cursor = NULL;
    int saw_digit = 0;

    if (basename == NULL || basename[0] == '\0') {
        return 0;
    }

    dot = strrchr(basename, '.');
    cursor = basename;
    while (*cursor != '\0' && cursor != dot) {
        if (*cursor < '0' || *cursor > '9') {
            return 0;
        }
        saw_digit = 1;
        cursor++;
    }

    return saw_digit;
}

static int basename_is_low_confidence_dos_alias_name(const char *basename)
{
    return basename != NULL && mft_name_looks_like_dos_alias(basename);
}

static int path_uses_low_confidence_alias_basename(const char *path)
{
    const char *basename = path_basename_local(path);

    if (basename == NULL || basename[0] == '\0') {
        return 0;
    }

    return basename_is_low_confidence_numeric_name(basename) ||
           basename_is_low_confidence_dos_alias_name(basename);
}

static int basename_collision_group_stem_local(
    const char *basename,
    char *out,
    size_t out_size
)
{
    const char *dot = NULL;
    const char *last_us = NULL;
    size_t stem_len = 0U;
    size_t digit_count = 0U;
    int has_earlier_underscore = 0;

    if (out != NULL && out_size > 0U) {
        out[0] = '\0';
    }
    if (basename == NULL || basename[0] == '\0' || out == NULL || out_size == 0U) {
        return 0;
    }

    dot = strrchr(basename, '.');
    stem_len = dot != NULL ? (size_t)(dot - basename) : strlen(basename);
    if (stem_len == 0U || stem_len >= out_size) {
        return 0;
    }

    memcpy(out, basename, stem_len);
    out[stem_len] = '\0';

    last_us = strrchr(out, '_');
    if (last_us == NULL || last_us[1] == '\0') {
        return 1;
    }

    for (const char *cursor = last_us + 1; *cursor != '\0'; cursor++) {
        if (*cursor < '0' || *cursor > '9') {
            return 1;
        }
        digit_count++;
    }
    if (digit_count == 0U) {
        return 1;
    }

    has_earlier_underscore = memchr(out, '_', (size_t)(last_us - out)) != NULL;
    if (has_earlier_underscore || digit_count <= 3U) {
        out[last_us - out] = '\0';
    }

    return 1;
}

static size_t count_named_outputs_with_same_collision_group_local(
    const char *target_path
)
{
    const char *basename = NULL;
    const char *slash = NULL;
    size_t directory_length = 0U;
    char wanted_group[256];
    const char *wanted_extension = NULL;
    size_t count = 0U;
    size_t i;

    if (target_path == NULL || target_path[0] == '\0') {
        return 0U;
    }

    basename = path_basename_local(target_path);
    slash = strrchr(target_path, '/');
    directory_length = slash != NULL ? (size_t)(slash - target_path) : 0U;
    wanted_extension = path_extension_local(target_path);
    if (basename == NULL ||
        basename[0] == '\0' ||
        wanted_extension == NULL ||
        wanted_extension[0] == '\0' ||
        !basename_collision_group_stem_local(
            basename,
            wanted_group,
            sizeof(wanted_group))) {
        return 0U;
    }

    for (i = 0U; i < g_recovered_output_count; i++) {
        const char *existing_path = g_recovered_outputs[i].path;
        const char *existing_basename = NULL;
        const char *existing_extension = NULL;
        char existing_group[256];

        if (existing_path[0] == '\0' || path_is_under_unident_local(existing_path)) {
            continue;
        }
        if (strncmp(existing_path, target_path, directory_length) != 0 ||
            existing_path[directory_length] != '/') {
            continue;
        }

        existing_basename = path_basename_local(existing_path);
        existing_extension = path_extension_local(existing_path);
        if (existing_basename == NULL ||
            existing_extension == NULL ||
            !extensions_are_same_recovery_family(existing_extension, wanted_extension) ||
            !basename_collision_group_stem_local(
                existing_basename,
                existing_group,
                sizeof(existing_group))) {
            continue;
        }
        if (ascii_equals_ci(existing_group, wanted_group)) {
            count++;
        }
    }

    return count;
}

static int path_is_partial_collision_storm_local(
    const char *target_path,
    MftRecoveredMatchKind match_kind,
    int context_complete
)
{
    size_t family_count = 0U;

    if (target_path == NULL ||
        target_path[0] == '\0' ||
        context_complete ||
        match_kind != MFT_RECOVERED_MATCH_HINT_CONTEXT_PARTIAL ||
        !path_is_under_partial_tree_local(target_path)) {
        return 0;
    }

    family_count = count_named_outputs_with_same_collision_group_local(target_path);
    return family_count >= 8U;
}

static int recovered_output_counts_as_named(const MftRecoveredOutput *output)
{
    return output != NULL &&
           output->path[0] != '\0' &&
           output->reconciled &&
           !path_is_under_unident_local(output->path) &&
           !path_is_under_photorec_import_local(output->path);
}

static int recovered_output_needs_rename_reconsideration(
    const MftRecoveredOutput *output
)
{
    if (output == NULL || output->path[0] == '\0') {
        return 0;
    }

    return path_is_under_partial_tree_local(output->path) ||
           path_uses_low_confidence_alias_basename(output->path);
}

static int recovered_output_should_participate_in_name_pass(
    const MftRecoveredOutput *output
)
{
    if (output == NULL) {
        return 0;
    }

    if (!recovered_output_counts_as_named(output)) {
        return 1;
    }

    return recovered_output_needs_rename_reconsideration(output);
}

static int recovered_output_should_participate_in_exact_rehydrate(
    const MftRecoveredOutput *output
)
{
    return output != NULL &&
           output->path[0] != '\0' &&
           output->abs_offset >= 0 &&
           !path_is_under_photorec_import_local(output->path);
}

static int match_kind_is_weak_name_assignment_local(
    MftRecoveredMatchKind kind
)
{
    switch (kind) {
        case MFT_RECOVERED_MATCH_CONTEXT_PARTIAL:
        case MFT_RECOVERED_MATCH_PARENT_GROUP:
        case MFT_RECOVERED_MATCH_FLAT_NAME:
        case MFT_RECOVERED_MATCH_FOLDER_ONLY:
        case MFT_RECOVERED_MATCH_HINT_CONTEXT_PARTIAL:
        case MFT_RECOVERED_MATCH_HINT_PARENT_GROUP:
        case MFT_RECOVERED_MATCH_HINT_FLAT_NAME:
            return 1;
        case MFT_RECOVERED_MATCH_NONE:
        case MFT_RECOVERED_MATCH_CONTEXT_COMPLETE:
        case MFT_RECOVERED_MATCH_HINT_CONTEXT_COMPLETE:
        default:
            return 0;
    }
}

static int match_kind_uses_hint_candidate_local(
    MftRecoveredMatchKind kind
)
{
    switch (kind) {
        case MFT_RECOVERED_MATCH_HINT_CONTEXT_COMPLETE:
        case MFT_RECOVERED_MATCH_HINT_CONTEXT_PARTIAL:
        case MFT_RECOVERED_MATCH_HINT_PARENT_GROUP:
        case MFT_RECOVERED_MATCH_HINT_FLAT_NAME:
            return 1;
        case MFT_RECOVERED_MATCH_NONE:
        case MFT_RECOVERED_MATCH_CONTEXT_COMPLETE:
        case MFT_RECOVERED_MATCH_CONTEXT_PARTIAL:
        case MFT_RECOVERED_MATCH_PARENT_GROUP:
        case MFT_RECOVERED_MATCH_FLAT_NAME:
        case MFT_RECOVERED_MATCH_FOLDER_ONLY:
        default:
            return 0;
    }
}

static int match_source_is_i30_only_local(MftRecoveredMatchSource source)
{
    return source == MFT_RECOVERED_MATCH_SOURCE_I30_ONLY;
}

static void mft_name_live_stats_note_ambiguous_candidate(void)
{
    g_mft_name_live_stats.ambiguous_candidates++;
}

static void mft_name_live_stats_note_committed_rename(
    MftRecoveredMatchKind kind,
    MftRecoveredMatchSource source
)
{
    if (source == MFT_RECOVERED_MATCH_SOURCE_WINDOWS_SEARCH) {
        g_mft_name_live_stats.windows_search_renames++;
        return;
    }
    if (source == MFT_RECOVERED_MATCH_SOURCE_PARTIAL_SUBTREE_ANCHOR) {
        g_mft_name_live_stats.partial_subtree_anchor_promotions++;
        return;
    }
    if (match_source_is_i30_only_local(source)) {
        g_mft_name_live_stats.i30_only_renames++;
        return;
    }

    switch (source) {
        case MFT_RECOVERED_MATCH_SOURCE_DIRECT_ANCHOR:
            g_mft_name_live_stats.direct_anchor_renames++;
            return;
        case MFT_RECOVERED_MATCH_SOURCE_ACTIVE_SIBLING:
        case MFT_RECOVERED_MATCH_SOURCE_NAME_INDEX:
        case MFT_RECOVERED_MATCH_SOURCE_MFT_HINT:
            g_mft_name_live_stats.sibling_batch_renames++;
            return;
        case MFT_RECOVERED_MATCH_SOURCE_NONE:
        default:
            break;
    }

    if (!match_kind_uses_hint_candidate_local(kind) &&
        kind != MFT_RECOVERED_MATCH_NONE) {
        g_mft_name_live_stats.direct_anchor_renames++;
    } else if (match_kind_uses_hint_candidate_local(kind)) {
        g_mft_name_live_stats.sibling_batch_renames++;
    }
}

static int extension_is_thumbnail_prone_image_local(
    const char *extension
)
{
    return extension != NULL &&
           (ascii_equals_ci(extension, "jpg") ||
            ascii_equals_ci(extension, "jpeg") ||
            ascii_equals_ci(extension, "png") ||
            ascii_equals_ci(extension, "tif") ||
            ascii_equals_ci(extension, "tiff") ||
            ascii_equals_ci(extension, "bmp") ||
            ascii_equals_ci(extension, "gif") ||
            ascii_equals_ci(extension, "webp") ||
            ascii_equals_ci(extension, "jp2") ||
            ascii_equals_ci(extension, "heic") ||
            ascii_equals_ci(extension, "heif"));
}

static int recovered_output_is_small_thumbnail_risk_local(
    const char *path,
    const char *extension
)
{
    uint64_t size = 0ULL;

    if (path == NULL ||
        path[0] == '\0' ||
        !extension_is_thumbnail_prone_image_local(extension) ||
        !stat_regular_file_size_local(path, &size)) {
        return 0;
    }

    return size > 0ULL && size < (2ULL * 1024ULL * 1024ULL);
}

static int recovered_output_is_large_original_image_risk_local(
    const char *extension,
    int recovered_size_available,
    uint64_t recovered_size
)
{
    return extension_is_thumbnail_prone_image_local(extension) &&
           recovered_size_available &&
           recovered_size >= (2ULL * 1024ULL * 1024ULL);
}

static int candidate_is_small_derivative_image_mismatch_local(
    const char *recovered_extension,
    int recovered_size_available,
    uint64_t recovered_size,
    const char *candidate_name,
    const char *candidate_path,
    uint64_t expected_size
)
{
    if (!recovered_output_is_large_original_image_risk_local(
            recovered_extension,
            recovered_size_available,
            recovered_size) ||
        expected_size == 0ULL ||
        expected_size >= (2ULL * 1024ULL * 1024ULL)) {
        return 0;
    }

    if (basename_looks_nikon_derivative_ci(candidate_name)) {
        return 1;
    }

    if (path_looks_derivative_image_context_ci(candidate_path)) {
        return 1;
    }

    if (candidate_path != NULL &&
        candidate_path[0] != '\0' &&
        path_looks_systemish_ci(candidate_path) &&
        !path_looks_userish_ci(candidate_path)) {
        return 1;
    }

    return 0;
}

static int hint_claim_key_equals_local(
    const MftHintClaimKey *lhs,
    const MftHintClaimKey *rhs
)
{
    return lhs != NULL &&
           rhs != NULL &&
           lhs->family_base_offset == rhs->family_base_offset &&
           lhs->record_number == rhs->record_number &&
           (lhs->volume_serial == 0ULL ||
            rhs->volume_serial == 0ULL ||
            lhs->volume_serial == rhs->volume_serial) &&
           (lhs->volume_start == 0LL ||
            rhs->volume_start == 0LL ||
            lhs->volume_start == rhs->volume_start);
}

static int hint_claim_key_is_claimed_local(
    const MftHintClaimKey *claimed_keys,
    size_t claimed_count,
    const MftHintClaimKey *wanted_key
)
{
    size_t i;

    if (claimed_keys == NULL || wanted_key == NULL) {
        return 0;
    }

    for (i = 0U; i < claimed_count; i++) {
        if (hint_claim_key_equals_local(&claimed_keys[i], wanted_key)) {
            return 1;
        }
    }

    return 0;
}

static int hint_claim_key_try_claim_local(
    MftHintClaimKey *claimed_keys,
    size_t claimed_capacity,
    size_t *claimed_count,
    const MftHintClaimKey *wanted_key
)
{
    if (claimed_count == NULL || wanted_key == NULL) {
        return 1;
    }

    if (hint_claim_key_is_claimed_local(
            claimed_keys,
            *claimed_count,
            wanted_key)) {
        return 0;
    }

    if (claimed_keys == NULL || *claimed_count >= claimed_capacity) {
        return 1;
    }

    claimed_keys[*claimed_count] = *wanted_key;
    (*claimed_count)++;
    return 1;
}

static int extensions_are_same_recovery_family(const char *lhs, const char *rhs)
{
    if (lhs == NULL || rhs == NULL) {
        return 0;
    }

    if (ascii_equals_ci(lhs, rhs)) {
        return 1;
    }

    if ((ascii_equals_ci(lhs, "jpg") && ascii_equals_ci(rhs, "jpeg")) ||
        (ascii_equals_ci(lhs, "jpeg") && ascii_equals_ci(rhs, "jpg")) ||
        (ascii_equals_ci(lhs, "jpg") && ascii_equals_ci(rhs, "jpe")) ||
        (ascii_equals_ci(lhs, "jpe") && ascii_equals_ci(rhs, "jpg")) ||
        (ascii_equals_ci(lhs, "jpeg") && ascii_equals_ci(rhs, "jpe")) ||
        (ascii_equals_ci(lhs, "jpe") && ascii_equals_ci(rhs, "jpeg"))) {
        return 1;
    }

    if ((ascii_equals_ci(lhs, "tif") && ascii_equals_ci(rhs, "tiff")) ||
        (ascii_equals_ci(lhs, "tiff") && ascii_equals_ci(rhs, "tif"))) {
        return 1;
    }

    if ((ascii_equals_ci(lhs, "bmp") && ascii_equals_ci(rhs, "dib")) ||
        (ascii_equals_ci(lhs, "dib") && ascii_equals_ci(rhs, "bmp"))) {
        return 1;
    }

    if ((ascii_equals_ci(lhs, "heic") && ascii_equals_ci(rhs, "heif")) ||
        (ascii_equals_ci(lhs, "heif") && ascii_equals_ci(rhs, "heic"))) {
        return 1;
    }

    if ((ascii_equals_ci(lhs, "mpg") && ascii_equals_ci(rhs, "mpeg")) ||
        (ascii_equals_ci(lhs, "mpeg") && ascii_equals_ci(rhs, "mpg"))) {
        return 1;
    }

    return 0;
}

static int contextual_path_is_usable_for_recovered_extension(
    const char *contextual_path,
    const char *recovered_extension
)
{
    const char *basename;
    const char *path_extension;

    if (contextual_path == NULL || recovered_extension == NULL) {
        return 0;
    }

    basename = path_basename_local(contextual_path);
    if (basename == NULL || basename[0] == '\0') {
        return 0;
    }

    if (basename_is_system_container_ci(basename) ||
        basename_is_low_confidence_numeric_name(basename)) {
        return 0;
    }

    path_extension = path_extension_local(contextual_path);
    return extensions_are_same_recovery_family(
        path_extension,
        recovered_extension
    );
}

static int contextual_path_depth_local(const char *contextual_path)
{
    int depth = 0;
    const char *cursor = contextual_path;

    if (contextual_path == NULL || contextual_path[0] == '\0') {
        return 0;
    }

    while (*cursor != '\0') {
        while (*cursor == '/' || *cursor == '\\') {
            cursor++;
        }
        if (*cursor == '\0') {
            break;
        }
        depth++;
        while (*cursor != '\0' && *cursor != '/' && *cursor != '\\') {
            cursor++;
        }
    }

    return depth;
}

static int text_contains_ascii_ci_local(const char *haystack, const char *needle)
{
    size_t needle_len = 0U;

    if (haystack == NULL || needle == NULL || needle[0] == '\0') {
        return 0;
    }

    needle_len = strlen(needle);
    if (needle_len == 0U) {
        return 0;
    }

    while (*haystack != '\0') {
        size_t i = 0U;

        while (haystack[i] != '\0' &&
               needle[i] != '\0' &&
               ascii_tolower_char(haystack[i]) ==
                   ascii_tolower_char(needle[i])) {
            i++;
        }
        if (i == needle_len) {
            return 1;
        }
        haystack++;
    }

    return 0;
}

