static const char *entry_extension(const MftEntry *entry)
{
    const char *dot;

    if (entry == NULL || !entry->has_name) {
        return NULL;
    }

    dot = strrchr(entry->name, '.');
    if (dot == NULL || dot[1] == '\0') {
        return NULL;
    }

    return dot + 1;
}

static const char *i30_entry_extension(const MftI30NameEntry *entry)
{
    const char *dot;

    if (entry == NULL || entry->name[0] == '\0') {
        return NULL;
    }

    dot = strrchr(entry->name, '.');
    if (dot == NULL || dot[1] == '\0') {
        return NULL;
    }

    return dot + 1;
}

